import RPi.GPIO as GPIO
import time
import logging
import threading
import atexit
import sys

# Constants
MOTION_SENSOR_PIN_1 = 17
MOTION_SENSOR_PIN_2 = 27
LIGHTING_CONTROL_PIN = 22
LIGHT_THRESHOLD = 60
MOTION_THRESHOLD = 2
SAMPLING_PERIOD = 1.0
DEBOUNCE_TIME = 200
OFF_DELAY = 300
LED_ON_DURATION = 60

# Logging setup
log_level = logging.DEBUG if 'DEBUG' in sys.argv else logging.INFO
logging.basicConfig(
    level=log_level,
    format='%(asctime)s - %(levelname)s - %(message)s',
    handlers=[
        logging.FileHandler('occupancy_lights.log'),
        logging.StreamHandler()
    ]
)

class MotionSensor:
    def __init__(self, pin, name="MotionSensor"):
        self.pin = pin
        self.name = name
        self.count = 0
        self.last_event_time = 0.0
        self.sampling_period = SAMPLING_PERIOD
        self.motion_threshold = MOTION_THRESHOLD
        self.bouncetime = DEBOUNCE_TIME
        self._running = True

        try:
            GPIO.setup(self.pin, GPIO.IN, pull_up_down=GPIO.PUD_DOWN)
            GPIO.add_event_detect(self.pin, GPIO.RISING, callback=self._motion_callback, bouncetime=self.bouncetime)
            logging.info(f"{self.name}: Motion sensor initialized on GPIO {self.pin}.")
        except Exception as e:
            logging.error(f"{self.name}: Failed to initialize GPIO {self.pin}: {e}")
            raise

    def _motion_callback(self, channel):
        try:
            current_time = time.time()
            if current_time - self.last_event_time > self.sampling_period:
                self.count += 1
                self.last_event_time = current_time
                logging.debug(f"{self.name}: Motion detected on GPIO {channel}, count={self.count}")
        except Exception as e:
            logging.error(f"{self.name}: Error in motion callback: {e}")

    def check_threshold(self):
        try:
            return self.count > self.motion_threshold
        except Exception as e:
            logging.error(f"{self.name}: Error checking threshold: {e}")
            return False

    def reset(self):
        try:
            self.count = 0
            self.last_event_time = time.time()
            logging.info(f"{self.name}: Counter reset.")
        except Exception as e:
            logging.error(f"{self.name}: Error resetting counter: {e}")

    def cleanup(self):
        self._running = False
        try:
            GPIO.remove_event_detect(self.pin)
        except Exception:
            pass

class LightingController:
    def __init__(self, lighting_pin, light_threshold, off_delay, led_on_duration):
        self.lighting_pin = lighting_pin
        self.light_threshold = light_threshold
        self.off_delay = off_delay
        self.led_on_duration = led_on_duration
        self.led_state = False
        self.timer = None
        self.motion_sensor = None
        self.light_sensor = None

        try:
            GPIO.setup(self.lighting_pin, GPIO.OUT, initial=GPIO.LOW)
            logging.info(f"LightingController: GPIO {self.lighting_pin} configured as output.")
        except Exception as e:
            logging.error(f"LightingController: Failed to configure GPIO {self.lighting_pin}: {e}")
            raise

    def set_light(self, state):
        try:
            GPIO.output(self.lighting_pin, GPIO.HIGH if state else GPIO.LOW)
            self.led_state = state
            logging.info(f"LightingController: Light turned {'ON' if state else 'OFF'}.")
        except Exception as e:
            logging.error(f"LightingController: Failed to set light state: {e}")

    def turn_on_light(self, motion_detected, light_level):
        if motion_detected and light_level > self.light_threshold:
            self.set_light(True)
            self._schedule_off_timer()
        else:
            self.set_light(False)

    def _schedule_off_timer(self):
        if self.timer and self.timer.is_alive():
            self.timer.cancel()
        self.timer = threading.Timer(self.led_on_duration, self._turn_off_light)
        self.timer.daemon = True
        self.timer.start()

    def _turn_off_light(self):
        self.set_light(False)
        logging.info(f"LightingController: Light turned off after {self.led_on_duration}s.")
        self._schedule_off_timer()

    def cleanup(self):
        if self.timer and self.timer.is_alive():
            self.timer.cancel()
        self.set_light(False)
        logging.info("LightingController: Cleanup complete.")

def main():
    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setwarnings(False)
        atexit.register(GPIO.cleanup)

        motion_sensor_1 = MotionSensor(MOTION_SENSOR_PIN_1, "MotionSensor1")
        motion_sensor_2 = MotionSensor(MOTION_SENSOR_PIN_2, "MotionSensor2")
        lighting_controller = LightingController(LIGHTING_CONTROL_PIN, LIGHT_THRESHOLD, OFF_DELAY, LED_ON_DURATION)

        def read_light_level():
            try:
                return 50
            except Exception as e:
                logging.error(f"Error reading light level: {e}")
                return 0

        def light_sensor_callback(channel):
            try:
                light_level = read_light_level()
                logging.debug(f"Light level: {light_level}")
                lighting_controller.turn_on_light(motion_sensor_1.check_threshold() or motion_sensor_2.check_threshold(), light_level)
            except Exception as e:
                logging.error(f"Error in light sensor callback: {e}")

        GPIO.add_event_detect(LIGHTING_CONTROL_PIN, GPIO.RISING, callback=light_sensor_callback, bouncetime=200)

        logging.info("Occupancy Lighting System started.")
        while True:
            time.sleep(1)

    except KeyboardInterrupt:
        logging.info("Exiting program.")
    except Exception as e:
        logging.error(f"An unexpected error occurred: {e}")
    finally:
        GPIO.cleanup()
        logging.info("GPIO cleanup completed.")

if __name__ == "__main__":
    main()

