import spidev
import RPi.GPIO as GPIO
import time
import logging
import sys

logging.basicConfig(level=logging.INFO, format="%(asctime)s %(message)s")

WATERING_RELAY_PIN = 18
DRY_THRESHOLD = 450
SPI_BUS = 0
SPI_DEVICE = 0
SPI_SPEED_HZ = 1350000


class SmartGardenController:
    """Controls a retail green-wall watering pump from soil-moisture readings."""

    def __init__(self, relay_pin):
        self.relay_pin = relay_pin
        self.spi_link = None
        try:
            GPIO.setmode(GPIO.BCM)
            GPIO.setup(self.relay_pin, GPIO.OUT, initial=GPIO.LOW)
        except Exception as e:
            logging.error("GPIO setup failed: %s", e)
            raise
        try:
            self.spi_link = spidev.SpiDev()
            self.spi_link.open(SPI_BUS, SPI_DEVICE)
            self.spi_link.max_speed_hz = SPI_SPEED_HZ
        except Exception as e:
            logging.error("SPI open failed: %s", e)
            self.close()
            raise

    def read_moisture(self):
        """Read a 10-bit soil-moisture value from the MCP3008 ADC channel 0."""
        if self.spi_link is None:
            raise RuntimeError("SPI not initialized")
        try:
            command_byte = 0b00011000 | (0 << 3)
            response_bytes = self.spi_link.xfer2([command_byte, 0x00, 0x00])
            raw_value = ((response_bytes[1] & 0x03) << 8) | response_bytes[2]
            return raw_value
        except Exception as e:
            logging.error("SPI read failed: %s", e)
            raise

    def run_pump(self, seconds):
        """Turn the watering pump relay on for a fixed duration."""
        try:
            GPIO.output(self.relay_pin, GPIO.HIGH)
            time.sleep(seconds)
        except Exception as e:
            logging.error("Pump control failed: %s", e)
            raise
        finally:
            GPIO.output(self.relay_pin, GPIO.LOW)

    def irrigation_cycle(self):
        """Read moisture and water the green wall if it is dry."""
        moisture_value = self.read_moisture()
        logging.info("Raw moisture reading: %d", moisture_value)
        if moisture_value > DRY_THRESHOLD:
            logging.info("Green wall is dry, watering for 2 seconds")
            self.run_pump(2)
            return True
        return False

    def close(self):
        """Release SPI and GPIO resources."""
        if self.spi_link is not None:
            try:
                self.spi_link.close()
            except Exception as e:
                logging.error("SPI close error: %s", e)
            self.spi_link = None
        try:
            GPIO.cleanup()
        except Exception as e:
            logging.error("GPIO cleanup error: %s", e)


def schedule_cycles(controller, cycle_count, interval_seconds):
    """Run a fixed number of watering cycles with a short interval."""
    for cycle_index in range(cycle_count):
        try:
            controller.irrigation_cycle()
        except Exception as e:
            logging.error("Cycle %d failed: %s", cycle_index, e)
            raise
        if cycle_index < cycle_count - 1:
            time.sleep(interval_seconds)


if __name__ == "__main__":
    garden_controller = None
    try:
        garden_controller = SmartGardenController(WATERING_RELAY_PIN)
        schedule_cycles(garden_controller, 10, 3)
    except KeyboardInterrupt:
        logging.info("Interrupted by user")
    except Exception as e:
        logging.error("Fatal error: %s", e)
        sys.exit(1)
    finally:
        if garden_controller is not None:
            garden_controller.close()

