#!/usr/bin/env python3
"""
Greenhouse Controller for Raspberry Pi
Reads DHT22 on GPIO 4 every 300 s, controls relays on GPIO 17/27/22,
LED on GPIO 25, and MCP3008 channel 0 over SPI (CS/CE0 on GPIO 8).
Watchdog restarts the program if no data/command is processed within 600 s.
"""

import os
import sys
import time
import signal
import logging
import spidev
import gpiozero
import adafruit_dht

# --- Configuration ---
DHT_PIN = 4
PUMP_PIN = 17
FAN_PIN = 27
LIGHT_PIN = 22
LED_PIN = 25
MCP3008_CHANNEL = 0
SPI_BUS = 0
SPI_DEVICE = 0
SPI_MAX_SPEED_HZ = 1_000_000
WATCHDOG_TIMEOUT = 600
SENSOR_INTERVAL = 300
DHT_RETRIES = 3

# --- Logging Setup ---
logging.basicConfig(
    filename='greenhouse.log',
    level=logging.INFO,
    format='%(asctime)s - %(levelname)s - %(message)s'
)
logger = logging.getLogger(__name__)

# --- Global State ---
last_activity_time = time.time()
spi = None
dht_device = None
pump = fan = light = led = None
running = True

# --- Signal Handlers ---
def signal_handler(signum, frame):
    global running
    logger.info(f"Received signal {signum}, shutting down...")
    running = False

signal.signal(signal.SIGINT, signal_handler)
signal.signal(signal.SIGTERM, signal_handler)

# --- Initialization ---
def init_gpio():
    global pump, fan, light, led
    try:
        pump = gpiozero.OutputDevice(PUMP_PIN, initial_value=False)
        fan = gpiozero.OutputDevice(FAN_PIN, initial_value=False)
        light = gpiozero.OutputDevice(LIGHT_PIN, initial_value=False)
        led = gpiozero.OutputDevice(LED_PIN, initial_value=False)
        logger.info("GPIO initialized successfully")
    except Exception as e:
        logger.error(f"GPIO initialization failed: {e}")
        raise

def init_spi():
    global spi
    try:
        spi = spidev.SpiDev()
        spi.open(SPI_BUS, SPI_DEVICE)
        spi.max_speed_hz = SPI_MAX_SPEED_HZ
        spi.mode = 0
        logger.info("SPI initialized successfully")
    except Exception as e:
        logger.error(f"SPI initialization failed: {e}")
        raise

def init_dht22():
    global dht_device
    try:
        dht_device = adafruit_dht.DHT22(DHT_PIN, use_pulseio=False)
        logger.info("DHT22 initialized successfully")
    except Exception as e:
        logger.error(f"DHT22 initialization failed: {e}")
        dht_device = None

# --- Sensor Reading ---
def read_dht22():
    """Read temperature (C) and humidity (%) from DHT22 with retries."""
    if dht_device is None:
        logger.warning("DHT22 not initialized, skipping read")
        return None, None

    for attempt in range(DHT_RETRIES):
        try:
            temperature = dht_device.temperature
            humidity = dht_device.humidity
            if temperature is not None and humidity is not None:
                logger.info(f"DHT22 read: temp={temperature:.1f}C, humidity={humidity:.1f}%")
                return temperature, humidity
            else:
                logger.warning(f"DHT22 returned None (attempt {attempt+1}/{DHT_RETRIES})")
        except RuntimeError as e:
            logger.warning(f"DHT22 read error (attempt {attempt+1}/{DHT_RETRIES}): {e}")
        except Exception as e:
            logger.error(f"DHT22 unexpected error: {e}")
            break
        time.sleep(2)

    logger.error("DHT22 read failed after all retries")
    return None, None

def read_mcp3008(channel):
    """Read 10-bit value from MCP3008 ADC on given channel (0-7)."""
    if spi is None:
        logger.error("SPI not initialized")
        return None
    if not 0 <= channel <= 7:
        logger.error(f"Invalid MCP3008 channel: {channel}")
        return None
    try:
        # MCP3008 single-ended read: start bit, config byte, don't care
        cmd = 0b00011000 | (channel << 3)
        resp = spi.xfer2([0x01, cmd, 0x00])
        value = ((resp[1] & 0x03) << 8) | resp[2]
        logger.info(f"MCP3008 channel {channel} read: {value}")
        return value
    except Exception as e:
        logger.error(f"MCP3008 read error on channel {channel}: {e}")
        return None

# --- Actuator Control ---
def control_pump(command):
    if command not in ('on', 'off'):
        logger.warning(f"Invalid pump command: {command}")
        return
    try:
        if command == 'on':
            pump.on()
            logger.info("Pump turned ON")
        else:
            pump.off()
            logger.info("Pump turned OFF")
    except Exception as e:
        logger.error(f"Pump control failed: {e}")

def control_fan(command):
    if command not in ('on', 'off'):
        logger.warning(f"Invalid fan command: {command}")
        return
    try:
        if command == 'on':
            fan.on()
            logger.info("Fan turned ON")
        else:
            fan.off()
            logger.info("Fan turned OFF")
    except Exception as e:
        logger.error(f"Fan control failed: {e}")

def control_light(command):
    if command not in ('on', 'off'):
        logger.warning(f"Invalid light command: {command}")
        return
    try:
        if command == 'on':
            light.on()
            logger.info("Light turned ON")
        else:
            light.off()
            logger.info("Light turned OFF")
    except Exception as e:
        logger.error(f"Light control failed: {e}")

def set_led_status(status):
    if status not in ('online', 'offline', 'error', 'synchronizing'):
        logger.warning(f"Invalid LED status: {status}")
        return
    try:
        if status == 'online':
            led.on()
            led.off()  # solid on
        elif status == 'offline':
            led.off()
            led.off()
        elif status in ('error', 'synchronizing'):
            for _ in range(5):
                led.on()
                time.sleep(0.2)
                led.off()
                time.sleep(0.2)
    except Exception as e:
        logger.error(f"LED control failed: {e}")

# --- Watchdog ---
def check_watchdog():
    global last_activity_time
    if time.time() - last_activity_time > WATCHDOG_TIMEOUT:
        logger.critical("Watchdog timeout! Restarting program...")
        os.execv(sys.executable, [sys.executable] + sys.argv)
    last_activity_time = time.time()

# --- Cleanup ---
def cleanup():
    logger.info("Cleaning up resources...")
    if spi is not None:
        try:
            spi.close()
            logger.info("SPI closed")
        except Exception as e:
            logger.error(f"SPI close error: {e}")
    if dht_device is not None:
        try:
            dht_device.exit()
            logger.info("DHT22 device closed")
        except Exception as e:
            logger.error(f"DHT22 exit error: {e}")
    for dev in (pump, fan, light, led):
        if dev is not None:
            try:
                dev.close()
                logger.info(f"GPIO device {dev.pin} closed")
            except Exception as e:
                logger.error(f"GPIO close error on pin {dev.pin}: {e}")

# --- Main Loop ---
def main():
    global running
    try:
        init_gpio()
        init_spi()
        init_dht22()
        logger.info("Greenhouse controller started")

        while running:
            check_watchdog()

            # Read sensor
            temperature, humidity = read_dht22()
            if temperature is not None and humidity is not None:
                last_activity_time = time.time()
                # Example: control based on sensor readings
                if temperature > 30:
                    control_fan('on')
                if humidity < 40:
                    control_light('on')

            # Read MCP3008
            read_mcp3008(MCP3008_CHANNEL)

            # Process actuator commands (placeholder: replace with actual logic)
            # In a real system, commands would come from a network or file source
            # Here we simulate by checking for specific conditions
            if temperature is not None and temperature > 35:
                control_pump('on')
            elif temperature is not None and temperature < 20:
                control_pump('off')

            # Set LED status
            if temperature is not None and temperature > 40:
                set_led_status('error')
            elif temperature is not None and temperature < 10:
                set_led_status('synchronizing')
            else:
                set_led_status('online')

            # Wait for next cycle
            for _ in range(SENSOR_INTERVAL):
                if not running:
                    break
                time.sleep(1)

    except Exception as e:
        logger.critical(f"Unhandled exception: {e}")
    finally:
        cleanup()
        logger.info("Program terminated")

if __name__ == "__main__":
    main()

