import time
import logging
import signal
import sys
import board
import busio
import adafruit_ads1x15.ads1115 as ADS
from adafruit_ads1x15.analog_in import AnalogIn

logging.basicConfig(
    level=logging.INFO,
    format='%(asctime)s - %(levelname)s - %(message)s'
)

ADS1115_ADDRESS = 0x48
I2C_BUS_NUMBER = 1
SAMPLE_INTERVAL = 0.1  # 10 Hz


class Oscilloscope:
    """
    Object-oriented oscilloscope using an ADS1115 ADC on a Raspberry Pi.
    """

    def __init__(self, address=ADS1115_ADDRESS, busnum=I2C_BUS_NUMBER):
        self.i2c = None
        self.ads = None
        self.ch0 = None
        self.ch1 = None
        self.running = True
        self._install_signal_handlers()

        try:
            self.i2c = busio.I2C(board.SCL, board.SDA)
            self.ads = ADS.ADS1115(self.i2c, address=address)
            self.ads.gain = 1
            self.ch0 = AnalogIn(self.ads, ADS.P0)
            self.ch1 = AnalogIn(self.ads, ADS.P1)
            logging.info(
                "Oscilloscope initialized: ADS1115 at 0x%02X, gain=1, "
                "channels P0 and P1 (single-ended, continuous).",
                address
            )
        except Exception as e:
            logging.error("Failed to initialize oscilloscope: %s", e)
            self.close()
            raise

    def _install_signal_handlers(self):
        for sig in (signal.SIGINT, signal.SIGTERM):
            signal.signal(sig, self._signal_handler)

    def _signal_handler(self, signum, frame):
        logging.info("Received signal %s, shutting down...", signum)
        self.running = False

    def initialize(self):
        """Public initialization method."""
        logging.info("Initializing oscilloscope...")
        self.__init__()
        logging.info("Initialization complete.")

    def run(self):
        """Continuously sample and print CSV data until interrupted."""
        logging.info("Starting oscilloscope acquisition loop (Ctrl+C to stop).")
        while self.running:
            try:
                timestamp = time.monotonic()
                ch0_voltage = self.ch0.voltage
                ch1_voltage = self.ch1.voltage
                print(f"{timestamp:.6f},{ch0_voltage:.4f},{ch1_voltage:.4f}")
                sys.stdout.flush()
                time.sleep(SAMPLE_INTERVAL)
            except Exception as e:
                logging.error("Error during sampling: %s", e)
                self.running = False
                break

    def close(self):
        """Release all resources cleanly."""
        logging.info("Closing oscilloscope...")
        try:
            if self.ch0 is not None:
                self.ch0 = None
        except Exception as e:
            logging.error("Error clearing ch0: %s", e)
        try:
            if self.ch1 is not None:
                self.ch1 = None
        except Exception as e:
            logging.error("Error clearing ch1: %s", e)
        try:
            if self.ads is not None:
                self.ads = None
        except Exception as e:
            logging.error("Error clearing ads: %s", e)
        try:
            if self.i2c is not None:
                self.i2c.deinit()
                self.i2c = None
        except Exception as e:
            logging.error("Error deinitializing I2C bus: %s", e)
        logging.info("Oscilloscope closed.")


def main():
    oscilloscope = None
    try:
        oscilloscope = Oscilloscope()
        oscilloscope.initialize()
        oscilloscope.run()
    except KeyboardInterrupt:
        logging.info("KeyboardInterrupt received.")
    except Exception as e:
        logging.error("Fatal error: %s", e)
    finally:
        if oscilloscope is not None:
            oscilloscope.close()


if __name__ == "__main__":
    main()

