import time
import logging
from smbus2 import SMBus

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

class ADS1x15:
    """
    ADS1x15 ADC reader for Raspberry Pi using smbus2.
    """

    # Register addresses
    REG_CONVERSION = 0x00
    REG_CONFIG = 0x01

    # Config register bit masks
    CONFIG_OS_SINGLE = 0x8000
    CONFIG_MUX_SINGLE = {0: 0x4000, 1: 0x5000, 2: 0x6000, 3: 0x7000}
    CONFIG_PGA = {6144: 0x0000, 4096: 0x0200, 2048: 0x0400, 1024: 0x0600, 512: 0x0800, 256: 0x0A00}
    CONFIG_MODE_SINGLE = 0x0100
    CONFIG_DR_128 = 0x0000
    CONFIG_CQUE_NONE = 0x0003

    def __init__(self, address=0x48, bus_num=1):
        self.address = address
        self.bus = None
        try:
            self.bus = SMBus(bus_num)
            logging.info(f"ADS1x15 initialized at I2C address 0x{address:02X} on bus {bus_num}")
        except Exception as e:
            logging.error(f"Failed to initialize I2C bus {bus_num}: {e}")
            raise

    def _write_config(self, channel, pga):
        if channel not in self.CONFIG_MUX_SINGLE:
            raise ValueError(f"Invalid channel: {channel}. Must be 0-3.")
        if pga not in self.CONFIG_PGA:
            raise ValueError(f"Invalid PGA: {pga}. Must be one of {list(self.CONFIG_PGA.keys())}.")

        config = (self.CONFIG_OS_SINGLE |
                  self.CONFIG_MUX_SINGLE[channel] |
                  self.CONFIG_PGA[pga] |
                  self.CONFIG_MODE_SINGLE |
                  self.CONFIG_DR_128 |
                  self.CONFIG_CQUE_NONE)

        try:
            self.bus.write_i2c_block_data(self.address, self.REG_CONFIG, [(config >> 8) & 0xFF, config & 0xFF])
        except OSError as e:
            logging.error(f"I2C write error to config register: {e}")
            raise

    def _read_conversion(self):
        try:
            data = self.bus.read_i2c_block_data(self.address, self.REG_CONVERSION, 2)
            raw = (data[0] << 8) | data[1]
            if raw > 32767:
                raw -= 65536
            return raw
        except OSError as e:
            logging.error(f"I2C read error from conversion register: {e}")
            raise

    def read(self, channel, pga=6144):
        if not isinstance(channel, int) or not 0 <= channel <= 3:
            raise ValueError("Channel must be an integer between 0 and 3.")
        if not isinstance(pga, int) or pga not in self.CONFIG_PGA:
            raise ValueError("PGA must be one of the supported values.")

        self._write_config(channel, pga)
        time.sleep(0.01)  # Wait for conversion to complete
        raw = self._read_conversion()
        voltage = (raw / 32768.0) * pga
        return voltage

    def close(self):
        if self.bus:
            try:
                self.bus.close()
                logging.info("I2C bus closed.")
            except Exception as e:
                logging.error(f"Error closing I2C bus: {e}")
            finally:
                self.bus = None

    def __del__(self):
        self.close()

