import time
import datetime
import json
import logging
import signal
import sys
from pathlib import Path

import cv2
import numpy as np
from picamera2 import Picamera2
from gpiozero import OutputDevice

# Configure logging
logging.basicConfig(
    filename='bird_feeder.log',
    level=logging.INFO,
    format='%(asctime)s - %(levelname)s - %(message)s'
)

# Global flag for graceful shutdown
running = True

def signal_handler(sig, frame):
    """Handle SIGINT/SIGTERM for clean shutdown."""
    global running
    logging.info("Shutdown signal received. Cleaning up...")
    running = False

def load_config(config_path="config.json"):
    """Loads configuration from a JSON file."""
    try:
        with open(config_path, 'r') as f:
            return json.load(f)
    except FileNotFoundError:
        logging.error(f"Configuration file not found: {config_path}")
        return None
    except json.JSONDecodeError as e:
        logging.error(f"Invalid JSON in configuration file: {e}")
        return None

def initialize_camera():
    """Initializes the Raspberry Pi camera using picamera2."""
    try:
        picam2 = Picamera2()
        # Configure for 224x224 preview
        config = picam2.create_preview_configuration(
            main={"size": (224, 224), "format": "RGB888"}
        )
        picam2.configure(config)
        picam2.start()
        logging.info("Camera initialized successfully.")
        return picam2
    except Exception as e:
        logging.error(f"Camera initialization failed: {e}")
        return None

def capture_image(picam2):
    """Captures an image from the camera and converts it to a NumPy array."""
    try:
        # capture_array returns the configured preview array
        image = picam2.capture_array()
        if image is None or image.size == 0:
            logging.error("Captured image is empty.")
            return None
        return image
    except Exception as e:
        logging.error(f"Image capture failed: {e}")
        return None

def preprocess_image(image):
    """Preprocesses the image for inference."""
    try:
        # Convert RGB to BGR for OpenCV's Caffe-style preprocessing
        image_bgr = cv2.cvtColor(image, cv2.COLOR_RGB2BGR)
        # Caffe expects BGR input
        input_data = cv2.dnn.readNetFromCaffe('MobileNet_Caffe_deploy.prototxt', 'MobileNet_Caffe_deploy.caffemodel')
        blob = cv2.dnn.blobFromImage(image_bgr, 1.0, (224, 224), (0, 0, 0), swapRB=True, crop=False)
        input_data.setInput(blob)
        return input_data.forward()
    except Exception as e:
        logging.error(f"Image preprocessing failed: {e}")
        return None

def run_inference(output):
    """Runs inference on the preprocessed image and returns the bird probability."""
    try:
        # Assuming output shape is (1, 1000) as per MobileNet
        if output.shape[1] != 1000:
            logging.warning(f"Unexpected output shape: {output.shape}")
            return None
        return float(output[0][292])  # Placeholder class index for "bird"
    except Exception as e:
        logging.error(f"Inference failed: {e}")
        return None

def indicate_bird(led_pin):
    """Indicates a bird detection by activating the LED for 1 second."""
    try:
        led_pin.on()
        time.sleep(1)
        led_pin.off()
        logging.info("Bird detected! LED activated.")
    except Exception as e:
        logging.error(f"LED control failed: {e}")

def control_feeder_door(door, open_state):
    """Controls the feeder door based on configuration."""
    try:
        if open_state:
            door.on()  # Drive HIGH to open
        else:
            door.off()  # Drive LOW to close
        logging.info(f"Feeder door set to: {'OPEN' if open_state else 'CLOSED'}")
    except Exception as e:
        logging.error(f"Feeder door control failed: {e}")

def main():
    """Main function to run the bird feeder system."""
    global running

    # Register signal handlers
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    # Load configuration
    config = load_config()
    if not config:
        print("Failed to load configuration. Exiting.")
        return

    # Initialize camera
    picam2 = initialize_camera()
    if not picam2:
        print("Failed to initialize camera. Exiting.")
        return

    # Initialize GPIO for LED
    led_pin = config.get('gpio_led_pin')
    if led_pin is not None:
        try:
            led = OutputDevice(led_pin)
            logging.info(f"LED initialized on GPIO {led_pin}.")
        except Exception as e:
            logging.error(f"Failed to initialize LED on GPIO {led_pin}: {e}")
            led = None
    else:
        led = None

    # Initialize GPIO for door control if enabled
    door = None
    if config.get('gpio_door_control'):
        try:
            door = OutputDevice(config['gpio_door_control'])
            logging.info(f"Feeder door initialized on GPIO {config['gpio_door_control']}.")
        except Exception as e:
            logging.error(f"Failed to initialize feeder door on GPIO {config['gpio_door_control']}: {e}")
            door = None

    # Main loop
    try:
        while running:
            # Capture image
            image = capture_image(picam2)
            if image is None:
                time.sleep(0.1)
                continue

            # Preprocess and run inference
            output = preprocess_image(image)
            if output is None:
                time.sleep(0.1)
                continue

            # Run inference
            probability = run_inference(output)
            if probability is None:
                time.sleep(0.1)
                continue

            # Log detection
            timestamp = datetime.datetime.now().strftime("%Y-%m-%d %H:%M:%S")
            logging.info(f"{timestamp} - Bird probability: {probability:.4f}")

            # Indicate bird detection
            if led:
                indicate_bird(led)

            # Control feeder door if enabled
            if door:
                open_state = probability > 0.5
                control_feeder_door(door, open_state)

            time.sleep(0.1)  # Reduce CPU load

    except Exception as e:
        logging.error(f"Unexpected error in main loop: {e}")
    finally:
        # Clean up resources
        if picam2:
            try:
                picam2.stop()
                logging.info("Camera stopped.")
            except Exception as e:
                logging.error(f"Error stopping camera: {e}")
        if led:
            try:
                led.close()
                logging.info("LED GPIO released.")
            except Exception as e:
                logging.error(f"Error releasing LED GPIO: {e}")
        if door:
            try:
                door.close()
                logging.info("Feeder door GPIO released.")
            except Exception as e:
                logging.error(f"Error releasing feeder door GPIO: {e}")
        logging.info("Program finished.")

if __name__ == "__main__":
    main()

