import io
import time
import json
import queue
import threading
import signal
import sys
import RPi.GPIO as GPIO
from picamera2 import Picamera2
from gpiozero import LED

CONFIG_FILE = "config.json"
DEFAULT_CONFIG = {
    "resolution": {"width": 640, "height": 480},
    "framerate": 30,
    "buffer_size": 10,
    "gpio_pin": None,
    "motion_threshold": 25,
    "trigger_alert": False,
    "alert_duration": 5
}

running = True

def signal_handler(sig, frame):
    global running
    running = False

def load_config(config_file):
    try:
        with open(config_file, "r") as f:
            config = json.load(f)
        return {**DEFAULT_CONFIG, **config}
    except FileNotFoundError:
        print(f"Error: Configuration file '{config_file}' not found.")
        return None
    except json.JSONDecodeError:
        print(f"Error: Invalid JSON format in '{config_file}'.")
        return None
    except Exception as e:
        print(f"Error loading configuration: {e}")
        return None

def initialize_camera(config):
    try:
        width = config["resolution"]["width"]
        height = config["resolution"]["height"]
        framerate = config["framerate"]
        picam2 = Picamera2()
        camera_config = picam2.create_video_configuration(
            main={"size": (width, height), "format": "RGB888"},
            controls={"FrameRate": framerate}
        )
        picam2.configure(camera_config)
        picam2.start()
        time.sleep(2)
        return picam2
    except Exception as e:
        print(f"Error initializing camera: {e}")
        return None

def capture_frame(picam2, frame_queue, config):
    try:
        frame = picam2.capture_array()
        if frame is None:
            print("Error: Captured frame is None.")
            return
        frame_queue.put(frame)
    except Exception as e:
        print(f"Error capturing frame: {e}")

def process_frame(frame, previous_frame, config):
    try:
        if previous_frame is None:
            return frame, 0
        diff = abs(frame.astype(int).mean() - previous_frame.astype(int).mean())
        return frame, diff
    except Exception as e:
        print(f"Error processing frame: {e}")
        return frame, 0

def check_motion(previous_frame, config):
    try:
        threshold = config["motion_threshold"]
        if previous_frame is not None and previous_frame.size > 0:
            diff = previous_frame.astype(int).mean()
            if diff > threshold:
                return True
        return False
    except Exception as e:
        print(f"Error checking motion: {e}")
        return False

def trigger_alert(led, config):
    try:
        if config["trigger_alert"]:
            duration = config["alert_duration"]
            led.on()
            threading.Timer(duration, led.off).start()
    except Exception as e:
        print(f"Error triggering alert: {e}")

def main():
    global running
    signal.signal(signal.SIGINT, signal_handler)
    config = load_config(CONFIG_FILE)
    if config is None:
        sys.exit(1)
    picam2 = initialize_camera(config)
    if picam2 is None:
        sys.exit(1)
    frame_queue = queue.Queue(maxsize=config["buffer_size"])
    previous_frame = None
    led = None
    if config["gpio_pin"] is not None:
        try:
            led = LED(config["gpio_pin"])
        except Exception as e:
            print(f"Error initializing GPIO pin {config['gpio_pin']}: {e}")
    try:
        while running:
            try:
                frame = frame_queue.get(timeout=1)
            except queue.Empty:
                continue
            try:
                current_frame, diff = process_frame(frame, previous_frame, config)
                if check_motion(current_frame, config):
                    trigger_alert(led, config)
                previous_frame = current_frame
                time.sleep(0.1)
            except Exception as e:
                print(f"Error in main loop: {e}")
    except Exception as e:
        print(f"Unexpected error: {e}")
    finally:
        if picam2:
            picam2.stop()
        if led:
            led.close()
        GPIO.cleanup()
        print("Resources cleaned up. Exiting.")

if __name__ == "__main__":
    main()

