    # Initialize I2C bus
    try:
        i2c = busio.I2C(board.SCL, board.SDA)
    except Exception as e:
        print(f"Failed to initialize I2C bus: {e}")
        return False

    # Initialize AMG8833 sensor (default I2C address 0x69)
    try:
        amg = adafruit_amg88xx.AMG88XX(i2c)
        print("AMG8833 thermal camera sensor initialized.")
    except Exception as e:
        print(f"AMG8833 not found at address 0x69: {e}")
        print("Falling back to simulated thermal data.")
        amg = None

    # Initialize buzzer
    try:
        buzzer = Buzzer(BUZZER_PIN)
        print(f"Buzzer initialized on GPIO{BUZZER_PIN}.")
    except Exception as e:
        print(f"Failed to initialize buzzer on GPIO{BUZZER_PIN}: {e}")
        buzzer = None

    return True


def get_thermal_data():
    """Return 8x8 thermal data from AMG8833, or simulated values if sensor absent."""
    if amg is not None:
        try:
            pixels = amg.pixels
            if len(pixels) != 64:
                print(f"Warning: expected 64 pixels, got {len(pixels)}")
                return [0.0] * 64
            return pixels
        except Exception as e:
            print(f"Error reading AMG8833: {e}")
            return None
    else:
        return [random.uniform(20.0, 45.0) for _ in range(64)]


def detect_human(thermal_data):
    """Return True if any pixel exceeds TEMP_THRESHOLD."""
    if thermal_data is None:
        return False
    for temp in thermal_data:
        if temp > TEMP_THRESHOLD:
            return True
    return False


def trigger_alert(buzzer):
    """Sound the buzzer for BUZZER_DURATION seconds."""
    if buzzer is None:
        print("Buzzer not available; alert skipped.")
        return
    try:
        buzzer.on()
        time.sleep(BUZZER_DURATION)
        buzzer.off()
        print("Alert triggered: human detected!")
    except Exception as e:
        print(f"Error triggering buzzer: {e}")


