    """Release all hardware resources."""
    global buzzer, i2c
    if buzzer is not None:
        try:
            buzzer.close()
            print("Buzzer closed.")
        except Exception as e:
            print(f"Error closing buzzer: {e}")
        buzzer = None
    if i2c is not None:
        try:
            i2c.deinit()
            print("I2C bus released.")
        except Exception as e:
            print(f"Error releasing I2C: {e}")
        i2c = None


def main():
    """Main loop: poll thermal data, detect humans, trigger alerts."""
    global running

    # Register signal handlers
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    if not init_hardware():
        print("Hardware initialization failed. Exiting.")
        return

    print("Thermal security system started. Press Ctrl+C to exit.")

    try:
        while running:
            thermal_data = get_thermal_data()

            if thermal_data is not None:
                print(f"Thermal data: min={min(thermal_data):.1f}°C, max={max(thermal_data):.1f}°C")
            else:
                print("Thermal data: unavailable (sensor absent or read error)")

            if detect_human(thermal_data):
                trigger_alert(buzzer)

            time.sleep(POLL_INTERVAL)

    except Exception as e:
        print(f"Unexpected error in main loop: {e}")
    finally:
        cleanup()
        print("System shutdown complete.")


if __name__ == "__main__":
    main()

