cameras = []
try:
    cam0 = Picamera2(camera_num=0)
    cam0.configure(cam0.create_preview_configuration(main={"format": 'RGB888', "size": (640, 480)}))
    cam0.set_controls({"FrameDurationLimits": (33333, 33333)})
    cameras.append(cam0)
except Exception as e:
    print(f"Error initializing camera 0: {e}", file=sys.stderr)
    sys.exit(1)

try:
    cam1 = Picamera2(camera_num=1)
    cam1.configure(cam1.create_preview_configuration(main={"format": 'RGB888', "size": (640, 480)}))
    cam1.set_controls({"FrameDurationLimits": (33333, 33333)})
    cameras.append(cam1)
except Exception as e:
    print(f"Error initializing camera 1: {e}", file=sys.stderr)
    for c in cameras:
        try:
            c.stop()
        except Exception:
            pass
    sys.exit(1)

try:
    while running:
        try:
            frame0 = cam0.capture_array()
            frame1 = cam1.capture_array()
        except Exception as e:
            print(f"Error capturing frame: {e}", file=sys.stderr)
            time.sleep(0.1)
            continue

        if frame0 is None or frame1 is None:
            continue

        try:
            combined = np.hstack((frame0, frame1))
