import cv2
import numpy as np
import logging
import signal
import sys

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

class Camera:
    def __init__(self, camera_index=0, resolution=(320, 240)):
        self.camera_index = camera_index
        self.resolution = resolution
        self.cap = None
        self.running = False

    def open(self):
        self.cap = cv2.VideoCapture(self.camera_index)
        if not self.cap.isOpened():
            logging.error(f"Could not open camera index {self.camera_index}.")
            return False
        self.cap.set(cv2.CAP_PROP_FRAME_WIDTH, self.resolution[0])
        self.cap.set(cv2.CAP_PROP_FRAME_HEIGHT, self.resolution[1])
        self.running = True
        logging.info(f"Camera opened at index {self.camera_index} with resolution {self.resolution}.")
        return True

    def read(self):
        if not self.running or self.cap is None:
            return None
        ret, frame = self.cap.read()
        if not ret or frame is None:
            logging.warning("Failed to read frame from camera.")
            return None
        return frame

    def release(self):
        if self.cap is not None:
            self.cap.release()
            self.cap = None
            self.running = False
            logging.info("Camera released.")

    def get_frame_mse(self, prev_gray):
        if prev_gray is None:
            return 0.0
        frame_gray = cv2.cvtColor(self.read(), cv2.COLOR_BGR2GRAY)
        if frame_gray is None:
            return 0.0
        mse = np.mean((frame_gray.astype(np.float32) - prev_gray.astype(np.float32)) ** 2)
        return mse

    def detect_motion(self, mse_threshold=100.0):
        if self.read() is None:
            return False
        gray = cv2.cvtColor(self.read(), cv2.COLOR_BGR2GRAY)
        if gray is None:
            return False
        if self.get_frame_mse(gray) > mse_threshold:
            logging.info(f"Motion Detected using MSE! MSE: {self.get_frame_mse(gray):.2f}")
            return True
        return False

    def apply_gaussian_blur(self, ksize=3):
        if self.read() is None:
            return None
        gray = cv2.cvtColor(self.read(), cv2.COLOR_BGR2GRAY)
        if gray is None:
            return None
        blurred = cv2.GaussianBlur(gray, (ksize, ksize), 0)
        return blurred

    def apply_clahe(self):
        if self.read() is None:
            return None
        gray = cv2.cvtColor(self.read(), cv2.COLOR_BGR2GRAY)
        if gray is None:
            return None
        clahe = cv2.createCLAHE(clipLimit=2.0, tileGridSize=(8, 8))
        compensated = clahe.apply(gray)
        return compensated

    def apply_canny_edge_detection(self, low_threshold=100, high_threshold=200):
        if self.read() is None:
            return None
        gray = cv2.cvtColor(self.read(), cv2.COLOR_BGR2GRAY)
        if gray is None:
            return None
        edges = cv2.Canny(gray, low_threshold, high_threshold)
        return edges

    def display_images(self, original, compensated, gray, edges):
        cv2.imshow('Original', original)
        cv2.imshow('Compensated', compensated)
        cv2.imshow('Grayscale', gray)
        cv2.imshow('Edges', edges)

    def stop(self):
        self.running = False

def main():
    camera = Camera(camera_index=0, resolution=(320, 240))
    if not camera.open():
        sys.exit(1)

    prev_gray = None
    running = True

    def signal_handler(sig, frame):
        nonlocal running
        running = False

    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        while running:
            frame = camera.read()
            if frame is None:
                logging.warning("Frame is None. Exiting loop.")
                break

            gray = cv2.cvtColor(frame, cv2.COLOR_BGR2GRAY)
            if gray is None:
                logging.warning("Could not convert to grayscale.")
                continue

            blurred = cv2.GaussianBlur(gray, (3, 3), 0)
            compensated = camera.apply_clahe()
            edges = cv2.Canny(blurred, 100, 200)

            camera.display_images(frame, compensated, gray, edges)

            if camera.detect_motion(mse_threshold=100.0):
                logging.info("Motion detected!")

            key = cv2.waitKey(1) & 0xFF
            if key == 27:
                logging.info("Esc pressed. Exiting.")
                break
    except Exception as e:
        logging.error(f"An error occurred: {e}")
    finally:
        camera.release()
        cv2.destroyAllWindows()
        logging.info("Program terminated.")

if __name__ == "__main__":
    main()

