from picamera2.encoders import MJPEGEncoder
from picamera2.outputs import FileOutput

try:
    from config import Config
    from mail_config import mail_config
except ImportError as exc:
    print(f"Missing configuration module: {exc}")
    raise

app = Flask(__name__)
config = Config()
output = None
picam2: Optional[Picamera2] = None
shutdown_event = threading.Event()


def init_camera() -> Picamera2:
    """Initialize and start the Picamera2 instance for live streaming."""
    global picam2, output
    try:
        picam2 = Picamera2()
        video_config = picam2.create_video_configuration(
            main={"size": (640, 480), "format": "RGB888"},
            transform=picam2.camera_properties.get("transform"),
        )
        picam2.configure(video_config)
        picam2.start()
        output = FileOutput()
        encoder = MJPEGEncoder()
        encoder.output = output
        picam2.start_encoder(encoder)
        return picam2
    except Exception as e:
        print(f"Error initializing camera: {e}")
        traceback.print_exc()
        raise


def get_camera_frame() -> bytes:
    """Capture a single JPEG frame from the camera and return it as bytes."""
    if picam2 is None:
        raise RuntimeError("Camera not initialized")
    try:
        frame = picam2.capture_array()
        if frame is None:
            raise RuntimeError("capture_array returned None")
        # Picamera2 returns RGB888; convert to JPEG
        from PIL import Image
        import io as iomodule
        img = Image.fromarray(frame)
        buf = iomodule.BytesIO()
        img.save(buf, format="JPEG", quality=85)
        return buf.getvalue()
    except Exception as e:
        print(f"Error capturing frame: {e}")
        traceback.print_exc()
        return b""


def get_object(classifier) -> Tuple[bytes, bool]:
    """Run object detection using the given classifier and return (jpeg_bytes, detected_bool)."""
    if picam2 is None:
        raise RuntimeError("Camera not initialized")
    try:
        frame = get_camera_frame()
        if not frame:
            return frame, False
        import object_detection  # type: ignore
        detected, box = object_detection.detect_object(
            frame, classifier
        )
        return frame, detected
    except Exception as e:
        print(f"Error during object detection: {e}")
        traceback.print_exc()
        return b"", False


def get_object_with_basic_motion_detection() -> Tuple[bytes, bool]:
    """Run object detection with basic motion detection when classifier is 'motion_detector'."""
    if picam2 is None:
        raise RuntimeError("Camera not initialized")
    try:
        frame = get_camera_frame()
        if not frame:
            return frame, False
        import motion_detector  # type: ignore
        detected, box = motion_detector.detect_motion(frame)
        return frame, detected
    except Exception as e:
        print(f"Error during motion detection: {e}")
        traceback.print_exc()
        return b"", False


def check_for_objects() -> None:
    """Background thread: check for objects and send email notifications."""
    last_email_time = 0.0
    while not shutdown_event.is_set():
        try:
            if config.classifier_name == "motion_detector":
                frame, detected = get_object_with_basic_motion_detection()
            else:
                frame, detected = get_object(config.classifier)

            if detected:
                print(f"Detected object: {config.classifier_name}")
                if config.send_email_notifications:
                    if (time.time() - last_email_time) >= config.email_send_interval:
                        try:
                            mail_config.send_email(frame, config)
                            last_email_time = time.time()
                            print("Email sent successfully.")
                        except Exception as e:
                            print(f"Error sending email: {e}")
                            traceback.print_exc()
            shutdown_event.wait(1.0)
        except Exception as e:
            print(f"Error in check_for_objects: {e}")
            traceback.print_exc()
            shutdown_event.wait(1.0)


def gen(camera: Picamera2) -> bytes:
    """Generate JPEG frames for the video feed."""
    while not shutdown_event.is_set():
        try:
            frame = camera.capture_array()
            if frame is None:
                continue
            from PIL import Image
            import io as iomodule
            img = Image.fromarray(frame)
            buf = iomodule.BytesIO()
            img.save(buf, format="JPEG", quality=85)
            yield (
                b"--frame\r\n"
                b"Content-Type: image/jpeg\r\n\r\n" + buf.getvalue() + b"\r\n"
            )
        except Exception as e:
            print(f"Error generating video feed: {e}")
            traceback.print_exc()
            shutdown_event.wait(1.0)


@app.route("/", methods=["GET", "POST"])
def index() -> str:
    """Handle the main web page and form submissions."""
    if request.method == "POST":
        config.update_from_form(request.form)
    return render_template("index.html", classifiers=config.classifiers, config=config)


@app.route("/video_feed")
def video_feed() -> Response:
    """Stream the video feed as multipart/x-mixed-replace."""
    try:
        return Response(
            gen(picam2),
            mimetype="multipart/x-mixed-replace; boundary=frame",
        )
    except Exception as e:
        print(f"Error in video_feed: {e}")
        traceback.print_exc()
        return Response("Error streaming video", status=500)


def cleanup() -> None:
    """Release camera resources on exit."""
    global picam2, output
    print("Cleaning up resources...")
    shutdown_event.set()
    if picam2 is not None:
        try:
            picam2.stop_encoder()
        except Exception:
            pass
        try:
            picam2.stop()
        except Exception:
            pass
        try:
            picam2.close()
        except Exception:
            pass
        picam2 = None
    print("Cleanup complete.")


def signal_handler(signum, frame) -> None:
    """Handle SIGINT/SIGTERM for graceful shutdown."""
    print(f"Received signal {signum}, shutting down...")
    cleanup()
    exit(0)


if __name__ == "__main__":
    try:
        init_camera()
    except Exception:
        print("Failed to initialize camera. Exiting.")
        traceback.print_exc()
        exit(1)

    atexit.register(cleanup)
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    object_detection_thread = threading.Thread(target=check_for_objects, daemon=True)
    object_detection_thread.start()

    try:
        app.run(host="0.0.0.0", port=5000, debug=False, threaded=True)
    finally:
        cleanup()

