import json
import logging
import os
import signal
import statistics
import sys
import time
from datetime import datetime

try:
    from gpiozero import OutputDevice, InputDevice
    from gpiozero.exc import GPIOZeroError, DeviceClosed
except ImportError:
    print("gpiozero is required: pip install gpiozero", file=sys.stderr)
    sys.exit(1)

DEFAULT_CONFIG = {
    "sensors": [
        {"trigger_pin": 17, "echo_pin": 18, "offset": 0.0, "max_distance": 200.0},
        {"trigger_pin": 22, "echo_pin": 23, "offset": 0.0, "max_distance": 200.0},
        {"trigger_pin": 24, "echo_pin": 25, "offset": 0.0, "max_distance": 200.0},
    ],
    "alert_threshold_low": 10.0,
    "alert_threshold_high": 180.0,
    "alert_repeat_delay": 60,
    "log_file": "water_level.log",
}

_running = True


def _signal_handler(signum, frame):
    global _running
    _running = False


def load_config(config_path="config.json"):
    if not os.path.exists(config_path):
        logging.warning("config.json not found; creating default config.")
        try:
            with open(config_path, "w") as f:
                json.dump(DEFAULT_CONFIG, f, indent=2)
        except OSError as e:
            logging.error("Failed to write default config.json: %s", e)
        return dict(DEFAULT_CONFIG)
    try:
        with open(config_path, "r") as f:
            cfg = json.load(f)
        if not isinstance(cfg, dict):
            logging.error("config.json root is not an object; using defaults.")
            return dict(DEFAULT_CONFIG)
        return cfg
    except (OSError, json.JSONDecodeError) as e:
        logging.error("Error loading config.json: %s; using defaults.", e)
        return dict(DEFAULT_CONFIG)


def initialize_gpio(config):
    devices = {}
    for s in config.get("sensors", []):
        try:
            trig = OutputDevice(s["trigger_pin"])
            echo = InputDevice(s["echo_pin"])
            devices[(s["trigger_pin"], s["echo_pin"])] = (trig, echo)
        except GPIOZeroError as e:
            logging.error("Failed to initialize GPIO for trigger=%d echo=%d: %s",
                          s["trigger_pin"], s["echo_pin"], e)
            return None
    return devices


def measure_distance(trig, echo, offset, max_distance):
    try:
        trig.on()
        time.sleep(0.00001)
        trig.off()

        deadline = time.time() + 0.05
        while echo.is_active:
            if time.time() > deadline:
                return None
        pulse_start = time.time()

        deadline = time.time() + 0.05
        while not echo.is_active:
            if time.time() > deadline:
                return None
        pulse_end = time.time()

        pulse_duration = pulse_end - pulse_start
        distance = (pulse_duration * 34300) / 2.0
        distance += offset
        distance = max(0.0, min(distance, max_distance))
        return distance
    except (DeviceClosed, GPIOZeroError) as e:
        logging.error("GPIO error during measurement: %s", e)
        return None
    except Exception as e:
        logging.error("Unexpected error during measurement: %s", e)
        return None


def read_sensor_data(config, devices):
    readings = []
    for s in config.get("sensors", []):
        trig, echo = devices.get((s["trigger_pin"], s["echo_pin"]), (None, None))
        if trig is None or echo is None:
            logging.error("GPIO devices not initialized for trigger=%d echo=%d",
                          s["trigger_pin"], s["echo_pin"])
            continue
        for _ in range(3):
            d = measure_distance(trig, echo, s["offset"], s["max_distance"])
            if d is not None:
                readings.append(d)
                break
            time.sleep(0.1)
    if not readings:
        return None
    return statistics.median(readings)


def check_alerts(avg_level, config, last_alerts):
    now = time.time()
    low = config.get("alert_threshold_low", 0.0)
    high = config.get("alert_threshold_high", 0.0)
    delay = config.get("alert_repeat_delay", 0.0)

    if avg_level is None:
        return last_alerts

    if avg_level < low:
        key = (isinstance(avg_level, bool), avg_level, low, "low")
        if key not in last_alerts or (now - last_alerts[key][0]) > delay:
            logging.warning("Low water level: %.2f cm", avg_level)
            last_alerts[key] = (now, avg_level)
            return last_alerts
    elif avg_level > high:
        key = (isinstance(avg_level, bool), avg_level, high, "high")
        if key not in last_alerts or (now - last_alerts[key][0]) > delay:
            logging.warning("High water level: %.2f cm", avg_level)
            last_alerts[key] = (now, avg_level)
            return last_alerts
    return last_alerts


def cleanup(devices):
    for (trig_pin, echo_pin), (trig, echo) in devices.items():
        try:
            trig.close()
            echo.close()
        except Exception:
            pass


def main():
    global _running
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    logging.basicConfig(
        filename="water_level.log",
        level=logging.INFO,
        format="%(asctime)s - %(levelname)s - %(message)s",
    )
    logging.info("Water level monitoring system started.")

    config = load_config()
    devices = initialize_gpio(config)
    if devices is None:
        logging.error("GPIO initialization failed; exiting.")
        cleanup({})
        sys.exit(0)

    last_alerts = {}

    try:
        while _running:
            avg_level = read_sensor_data(config, devices)
            if avg_level is not None:
                logging.info("Average water level: %.2f cm", avg_level)
                last_alerts = check_alerts(avg_level, config, last_alerts)
            else:
                logging.warning("No valid sensor readings.")
            time.sleep(5)
    except Exception as e:
        logging.error("Unexpected error in main loop: %s", e)
    finally:
        cleanup(devices)
        logging.info("Water level monitoring system stopped.")


if __name__ == "__main__":
    main()

