#!/usr/bin/env python3
"""
Light-Based Security System for Raspberry Pi 5
Uses TSL2591 light sensor (I2C 0x29) and a buzzer on GPIO 17.
"""

import time
import logging
import signal
import sys
import board
import busio
import adafruit_tsl2591
from gpiozero import Buzzer

# Configuration
BUZZER_PIN = 17
I2C_ADDRESS = 0x29
THRESHOLD_PERCENT = 25.0
REARM_DELAY = 10.0
SAMPLE_INTERVAL = 0.5
BASELINE_SAMPLES = 5
BASELINE_SAMPLE_INTERVAL = 1.0
MAX_RETRIES = 3
RETRY_DELAY = 0.5
BUZZER_DURATION = 3.0

# Logging setup
logging.basicConfig(
    filename='security_system.log',
    level=logging.INFO,
    format='%(asctime)s - %(levelname)s - %(message)s'
)

# Global state for cleanup
buzzer = None
i2c = None
tsl = None
running = True

def signal_handler(signum, frame):
    """Handle SIGINT/SIGTERM for graceful shutdown."""
    global running
    logging.info(f"Received signal {signum}, shutting down...")
    running = False

def initialize_i2c():
    """Initialize I2C bus with retry logic."""
    global i2c
    for attempt in range(1, MAX_RETRIES + 1):
        try:
            i2c = busio.I2C(board.SCL, board.SDA)
            logging.info("I2C bus initialized successfully.")
            return True
        except Exception as e:
            logging.error(f"I2C initialization failed (attempt {attempt}/{MAX_RETRIES}): {e}")
            if attempt < MAX_RETRIES:
                time.sleep(RETRY_DELAY)
    logging.error("I2C initialization failed after all retries.")
    return False

def initialize_light_sensor():
    """Initialize TSL2591 sensor with retry logic."""
    global tsl
    for attempt in range(1, MAX_RETRIES + 1):
        try:
            tsl = adafruit_tsl2591.TSL2591(i2c)
            logging.info("TSL2591 sensor initialized successfully.")
            return True
        except Exception as e:
            logging.error(f"TSL2591 initialization failed (attempt {attempt}/{MAX_RETRIES}): {e}")
            if attempt < MAX_RETRIES:
                time.sleep(RETRY_DELAY)
    logging.error("TSL2591 initialization failed after all retries.")
    return False

def get_baseline_light_level():
    """Get baseline light level from multiple readings."""
    readings = []
    for i in range(BASELINE_SAMPLES):
        if not running:
            return None
        reading = get_light_level()
        if reading is not None:
            readings.append(reading)
        else:
            logging.warning(f"Failed to get baseline reading {i+1}/{BASELINE_SAMPLES}")
        if i < BASELINE_SAMPLES - 1:
            time.sleep(BASELINE_SAMPLE_INTERVAL)
    if not readings:
        logging.error("No valid baseline readings obtained.")
        return None
    return sum(readings) / len(readings)

def get_light_level():
    """Get current light level with retry logic."""
    for attempt in range(1, MAX_RETRIES + 1):
        try:
            return tsl.lux
        except Exception as e:
            logging.error(f"Failed to read light level (attempt {attempt}/{MAX_RETRIES}): {e}")
            if attempt < MAX_RETRIES:
                time.sleep(RETRY_DELAY)
    logging.error("Failed to read light level after all retries.")
    return None

def check_intrusion(light_level, baseline):
    """Check if light level has changed significantly."""
    if baseline is None:
        return False
    return abs(light_level - baseline) > (baseline * THRESHOLD_PERCENT / 100.0)

def trigger_buzzer(buzzer_obj, duration):
    """Trigger buzzer for specified duration."""
    try:
        buzzer_obj.on()
        time.sleep(duration)
        buzzer_obj.off()
        logging.info("Buzzer triggered.")
    except Exception as e:
        logging.error(f"Buzzer trigger failed: {e}")

def cleanup():
    """Release all resources."""
    global buzzer, i2c
    if buzzer is not None:
        try:
            buzzer.off()
            buzzer.close()
            logging.info("Buzzer turned off and closed.")
        except Exception as e:
            logging.error(f"Buzzer cleanup failed: {e}")
    if i2c is not None:
        try:
            i2c.deinit()
            logging.info("I2C bus deinitialized.")
        except Exception as e:
            logging.error(f"I2C deinit failed: {e}")

def main():
    """Main security system loop."""
    global buzzer, running

    # Register signal handlers
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    # Initialize hardware
    if not initialize_i2c():
        sys.exit(1)
    if not initialize_light_sensor():
        cleanup()
        sys.exit(1)
    try:
        buzzer = Buzzer(BUZZER_PIN)
        logging.info("Buzzer initialized on GPIO 17.")
    except Exception as e:
        logging.error(f"Buzzer initialization failed: {e}")
        cleanup()
        sys.exit(1)

    # Get baseline
    baseline = get_baseline_light_level()
    if baseline is None:
        logging.error("Failed to get baseline. Exiting.")
        cleanup()
        sys.exit(1)
    logging.info(f"Baseline light level: {baseline:.2f} lux")

    # Main monitoring loop
    try:
        while running:
            light_level = get_light_level()
            if light_level is None:
                time.sleep(SAMPLE_INTERVAL)
                continue

            if check_intrusion(light_level, baseline):
                logging.warning(f"Intrusion detected! Light level: {light_level:.2f} lux")
                trigger_buzzer(buzzer, BUZZER_DURATION)

                # Re-arm delay
                logging.info(f"Entering re-arm delay for {REARM_DELAY} seconds...")
                re_arm_start = time.time()
                while time.time() - re_arm_start < REARM_DELAY:
                    if not running:
                        break
                    light_level_check = get_light_level()
                    if light_level_check is not None:
                        if abs(light_level_check - baseline) <= (baseline * 5.0 / 100.0):
                            logging.info("Intrusion resolved.")
                            if buzzer.is_active:
                                buzzer.off()
                            break
                    time.sleep(SAMPLE_INTERVAL)

                # If still in re-arm and running, continue monitoring
                if running:
                    logging.info("Re-arm period complete. Resuming monitoring.")
            else:
                logging.debug(f"Light level: {light_level:.2f} lux (normal)")

            time.sleep(SAMPLE_INTERVAL)

    except Exception as e:
        logging.error(f"Unexpected error in main loop: {e}")
    finally:
        cleanup()
        logging.info("System shutdown.")

if __name__ == "__main__":
    main()

