import io
import os
import time
import signal
import datetime
import threading
import logging
from http.server import HTTPServer, SimpleHTTPRequestHandler
from picamera2 import Picamera2
from picamera2.encoders import H264Encoder
from picamera2.outputs import FileOutput

# Configuration
MOTION_THRESHOLD = 20
MIN_MOTION_VECTORS = 10
PRE_RECORD_SECONDS = 5
POST_RECORD_SECONDS = 10
MAX_DISK_SPACE_GB = 1.0
CAMERA_RESOLUTION = (640, 480)
CAMERA_FRAMERATE = 15
SERVER_PORT = 8000
RECORDINGS_DIR = "recordings"

# Logging setup
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')
logger = logging.getLogger(__name__)

# Global state
running = True
picam2 = None
httpd = None

class MotionDetector:
    def __init__(self, threshold, min_vectors):
        self.threshold = threshold
        self.min_vectors = min_vectors
        self.previous_frame = None
        self.motion_vectors = []

    def analyze(self, current_frame):
        # Placeholder for actual motion detection logic
        self.motion_vectors = []
        return len(self.motion_vectors) >= self.min_vectors

class DiskManager:
    def __init__(self, max_gb):
        self.max_gb = max_gb
        self.total_bytes = self.get_total_disk_space()
        self.recordings_dir = RECORDINGS_DIR
        self.create_recordings_directory()

    def get_total_disk_space(self):
        statvfs = os.statvfs(self.recordings_dir)
        return statvfs.f_blocks * statvfs.f_frsize

    def create_recordings_directory(self):
        try:
            os.makedirs(self.recordings_dir, exist_ok=True)
        except OSError as e:
            logger.error(f"Error creating recordings directory: {e}")
            raise

    def get_oldest_file(self):
        try:
            files = [f for f in os.listdir(self.recordings_dir) if f.endswith('.h264')]
            if not files:
                return None
            oldest_file = min(files, key=lambda f: os.path.getmtime(os.path.join(self.recordings_dir, f)))
            return os.path.join(self.recordings_dir, oldest_file)
        except FileNotFoundError:
            return None
        except Exception as e:
            logger.error(f"Error getting oldest file: {e}")
            return None

    def delete_oldest_file(self):
        try:
            file_to_delete = self.get_oldest_file()
            if file_to_delete:
                os.remove(file_to_delete)
                logger.info(f"Deleted oldest file: {file_to_delete}")
        except Exception as e:
            logger.error(f"Error deleting oldest file: {e}")

    def manage_disk_space(self):
        while running:
            time.sleep(60)
            if self.total_bytes > self.max_bytes:
                self.delete_oldest_file()
                self.total_bytes = self.get_total_disk_space()

    def record(self, filename, stream):
        try:
            with open(filename, 'wb') as f:
                f.write(stream.getbuffer())
            self.total_bytes = self.get_total_disk_space()
        except OSError as e:
            logger.error(f"Error writing to file: {e}")
            raise

    @property
    def max_bytes(self):
        return self.max_gb * 1024 * 1024 * 1024

class CameraHandler:
    def __init__(self, resolution, framerate):
        self.resolution = resolution
        self.framerate = framerate
        self.encoder = H264Encoder()
        self.output = FileOutput()

    def start_recording(self, filename):
        try:
            self.encoder.output = FileOutput(filename)
            self.encoder.start()
            logger.info(f"Started recording: {filename}")
        except Exception as e:
            logger.error(f"Error starting recording: {e}")
            raise

    def stop_recording(self):
        try:
            self.encoder.stop()
            logger.info("Stopped recording.")
        except Exception as e:
            logger.error(f"Error stopping recording: {e}")

    def capture_loop(self, motion_detector, disk_manager):
        global running
        try:
            picam2 = Picamera2()
            video_config = picam2.create_video_configuration(
                main={"size": self.resolution, "format": "RGB888"},
                lores={"size": (320, 240), "format": "YUV420"}
            )
            picam2.configure(video_config)
            picam2.start()
            logger.info("Camera started.")

            while running:
                frame = picam2.capture_array("lores")
                if frame is None:
                    logger.warning("Failed to capture frame.")
                    continue

                motion_detector.previous_frame = frame
                if motion_detector.analyze(frame):
                    logger.info("Motion detected!")
                    timestamp = datetime.datetime.now().strftime("%Y-%m-%d_%H-%M-%S")
                    filename = os.path.join(disk_manager.recordings_dir, f"{timestamp}.h264")
                    disk_manager.start_recording(filename, io.BytesIO())
                    start_time = time.time()
                    while time.time() - start_time < POST_RECORD_SECONDS and running:
                        frame = picam2.capture_array("lores")
                        if frame is None:
                            logger.warning("Failed to capture frame during post-record.")
                            continue
                        motion_detector.previous_frame = frame
                        if motion_detector.analyze(frame):
                            logger.info("Motion detected during post-record!")
                            break
                        time.sleep(0.1)
                    disk_manager.stop_recording()
        except Exception as e:
            logger.error(f"Error in capture loop: {e}")
        finally:
            if picam2:
                try:
                    picam2.stop()
                    picam2.close()
                except Exception as e:
                    logger.error(f"Error closing camera: {e}")

class SimpleHTTPRequestHandlerWithDirectoryListing(SimpleHTTPRequestHandler):
    def do_GET(self):
        if self.path == '/':
            self.send_response(301)
            self.send_header('Location', '/index.html')
            self.end_headers()
        else:
            super().do_GET()

    def list_directory(self, path):
        try:
            names = os.listdir(path)
        except OSError:
            self.send_error(403, "Forbidden")
            self.end_headers()
            return
        names.sort()
        result = []
        prefix = '/'
        for name in names:
            url = prefix + name
            fullname = os.path.join(path, name)
            if os.path.isdir(fullname):
                result.append(f'<a href="{url}/">{name}/</a>\n')
            else:
                result.append(f'<a href="{url}">{name}</a>\n')
        self.send_response(200)
        self.send_header('Content-type', 'text/html; charset=utf-8')
        self.end_headers()
        self.wfile.write(b'<html><head><title>Index</title></head><body><h1>Index</h1><ul>')
        for item in result:
            self.wfile.write(item.encode('utf-8'))
        self.wfile.write(b'</ul></body></html>')

def signal_handler(sig, frame):
    global running, httpd, picam2
    logger.info("Shutting down...")
    running = False
    if httpd:
        httpd.shutdown()
    if picam2:
        try:
            picam2.stop()
            picam2.close()
        except Exception:
            pass

def main():
    global running, httpd, picam2

    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        os.makedirs(RECORDINGS_DIR, exist_ok=True)
    except OSError as e:
        logger.error(f"Error creating recordings directory: {e}")
        return

    disk_manager = DiskManager(MAX_DISK_SPACE_GB)
    motion_detector = MotionDetector(MOTION_THRESHOLD, MIN_MOTION_VECTORS)
    camera_handler = CameraHandler(CAMERA_RESOLUTION, CAMERA_FRAMERATE)

    camera_thread = threading.Thread(target=camera_handler.capture_loop, args=(motion_detector, disk_manager))
    camera_thread.daemon = True
    camera_thread.start()

    disk_thread = threading.Thread(target=disk_manager.manage_disk_space)
    disk_thread.daemon = True
    disk_thread.start()

    try:
        httpd = HTTPServer(('', SERVER_PORT), SimpleHTTPRequestHandlerWithDirectoryListing)
        logger.info(f"Serving at port {SERVER_PORT}")
        httpd.serve_forever()
    except Exception as e:
        logger.error(f"Error starting server: {e}")
    finally:
        running = False
        if picam2:
            try:
                picam2.stop()
                picam2.close()
            except Exception:
                pass
        if httpd:
            httpd.server_close()

if __name__ == '__main__':
    main()

