import argparse
import datetime
import os
import signal
import sys
import time
from typing import Optional, Tuple

import cv2
import numpy as np
from picamera2 import Picamera2

# Global shutdown flag
_shutdown = False


def _signal_handler(signum, frame):
    global _shutdown
    _shutdown = True


def parse_args() -> argparse.Namespace:
    parser = argparse.ArgumentParser(
        description="Raspberry Pi motion-detection capture using picamera2 (libcamera)."
    )
    parser.add_argument(
        "-d", "--directory", default="./saved_imgs",
        help="Directory to save captured images (default: ./saved_imgs)"
    )
    parser.add_argument(
        "-t", "--threshold", type=int, default=5,
        help="Delta threshold for background subtraction (default: 5)"
    )
    parser.add_argument(
        "-a", "--area", type=int, default=5000,
        help="Minimum motion area in pixels (default: 5000)"
    )
    parser.add_argument(
        "-m", "--min-motion", type=int, default=8,
        help="Minimum consecutive frames with motion to trigger saving (default: 8)"
    )
    parser.add_argument(
        "-u", "--upload-interval", type=int, default=30,
        help="Minimum seconds between saved images (default: 30)"
    )
    parser.add_argument(
        "-v", "--video", type=str, default="",
        help="Path to a video file for testing (optional)"
    )
    return parser.parse_args()


def ensure_directory(path: str) -> None:
    try:
        os.makedirs(path, exist_ok=True)
    except OSError as exc:
        print(f"Error: cannot create directory '{path}': {exc}", file=sys.stderr)
        sys.exit(1)


def detect_motion(
    frame: np.ndarray,
    avg: np.ndarray,
    delta_thresh: int,
    min_area: int,
) -> Tuple[bool, Optional[int]]:
    """Return (motion_detected, frame_number)."""
    text = "No motion detected.."
    frame_number = None

    # picamera2 returns RGB; convert to BGR for OpenCV consistency
    if frame.shape[2] == 3:
        frame_bgr = cv2.cvtColor(frame, cv2.COLOR_RGB2BGR)
    else:
        frame_bgr = frame

    gray = cv2.cvtColor(frame_bgr, cv2.COLOR_BGR2GRAY)
    gray = cv2.GaussianBlur(gray, (21, 21), 0)

    cv2.accumulateWeighted(gray, avg, 0.5)
    frame_delta = cv2.absdiff(gray, cv2.convertScaleAbs(avg))

    thresh = cv2.threshold(
        frame_delta, delta_thresh, 255, cv2.THRESH_BINARY
    )[1]
    thresh = cv2.dilate(thresh, None, iterations=2)

    contours, _ = cv2.findContours(
        thresh.copy(), cv2.RETR_EXTERNAL, cv2.CHAIN_APPROX_SIMPLE
    )

    for contour in contours:
        if cv2.contourArea(contour) < min_area:
            continue
        (x, y, w, h) = cv2.boundingRect(contour)
        cv2.rectangle(frame_bgr, (x, y), (x + w, y + h), (0, 255, 0), 2)
        text = "Motion Detected!"

    if text == "Motion Detected!":
        ts = datetime.datetime.now().strftime("%A %d %B %Y %I:%M:%S%p")
        cv2.putText(
            frame_bgr,
            f"Alert: Motion Detected! {ts}",
            (10, 20),
            cv2.FONT_HERSHEY_SIMPLEX,
            0.5,
            (0, 0, 255),
            2,
        )

    return (text != "No motion detected.."), int(time.time())


def main() -> int:
    global _shutdown

    args = parse_args()

    ensure_directory(args.directory)

    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    picam2: Optional[Picamera2] = None
    avg: Optional[np.ndarray] = None
    last_uploaded: float = 0.0
    motion_counter: int = 0
    start_time: float = time.time()

    try:
        if args.video:
            cap = cv2.VideoCapture(args.video)
            if not cap.isOpened():
                print(f"Error: cannot open video file '{args.video}'", file=sys.stderr)
                return 1
            print(f"Using video file: {args.video}")
        else:
            try:
                picam2 = Picamera2()
                config = picam2.create_preview_configuration(
                    main={"size": (640, 480), "format": "RGB888"}
                )
                picam2.configure(config)
                picam2.start()
            except Exception as exc:
                print(f"Error: failed to initialize Pi Camera: {exc}", file=sys.stderr)
                return 1

            time.sleep(2.0)  # warm-up for auto-exposure / AWB to settle

            if picam2 is not None:
                avg = np.zeros((480, 640), dtype=np.float32)

        while not _shutdown:
            try:
                if picam2 is not None:
                    frame = picam2.capture_array()
                else:
                    ret, frame = cap.read()
                    if not ret:
                        print("Warning: failed to read frame from video.", file=sys.stderr)
                        break

                if frame is None or frame.size == 0:
                    print("Warning: empty frame received.", file=sys.stderr)
                    continue

                motion, frame_number = detect_motion(
                    frame, avg, args.threshold, args.area
                )

                if motion:
                    motion_counter += 1
                    if (
                        motion_counter >= args.min_motion
                        and (time.time() - start_time) >= args.upload_interval
                    ):
                        ts = datetime.datetime.now().strftime("%Y%m%d_%H%M%S")
                        filename = os.path.join(
                            args.directory, f"motion_{ts}.jpg"
                        )
                        if cv2.imwrite(filename, frame):
                            print(f"Saved: {filename}")
                            last_uploaded = time.time()
                            start_time = time.time()
                            motion_counter = 0
                        else:
                            print(f"Error: failed to write '{filename}'", file=sys.stderr)
                else:
                    motion_counter = 0

            except Exception as exc:
                print(f"Error during processing: {exc}", file=sys.stderr)
                break

    finally:
        if picam2 is not None:
            try:
                picam2.stop()
            except Exception:
                pass
        if cap is not None:
            cap.release()
        cv2.destroyAllWindows()
        print("Shutdown complete.")

    return 0


if __name__ == "__main__":
    sys.exit(main())

