import argparse
import datetime
import json
import logging
import os
import signal
import sys
import threading
import time

import cv2
import face_recognition
import numpy as np
from picamera2 import Picamera2
from gpiozero import OutputDevice

DEFAULT_CONFIG = {
    "resolution": (640, 480),
    "motion_threshold": 500,
    "confidence_threshold": 0.6,
    "door_open_duration": 5,
    "debounce_time": 2,
    "log_level": "INFO",
    "relay_pin": 17,
}


def load_config(config_file="config.json"):
    config = dict(DEFAULT_CONFIG)
    try:
        with open(config_file, "r") as f:
            user_config = json.load(f)
        config.update(user_config)
    except FileNotFoundError:
        logging.warning("Config file not found; using default settings.")
    except json.JSONDecodeError as e:
        logging.error(f"Invalid JSON in config file: {e}; using defaults.")
    return config


def setup_logging(log_level):
    numeric_level = getattr(logging, log_level.upper(), None)
    if not isinstance(numeric_level, int):
        raise ValueError(f"Invalid log level: {log_level}")
    logging.basicConfig(
        level=numeric_level,
        format="%(asctime)s - %(levelname)s - %(message)s",
        datefmt="%Y-%m-%d %H:%M:%S",
    )


def initialize_camera(resolution):
    try:
        picam2 = Picamera2()
        config = picam2.create_preview_configuration(
            main={"format": "XRGB8888", "size": resolution}
        )
        picam2.configure(config)
        picam2.start()
        logging.info("Camera initialized successfully.")
        return picam2
    except Exception as e:
        logging.error(f"Failed to initialize camera: {e}")
        return None


def detect_motion(frame1, frame2, motion_threshold):
    try:
        gray1 = cv2.cvtColor(frame1, cv2.COLOR_BGR2GRAY)
        gray2 = cv2.cvtColor(frame2, cv2.COLOR_BGR2GRAY)
        diff = cv2.absdiff(gray1, gray2)
        thresh = cv2.threshold(diff, 25, 255, cv2.THRESH_BINARY)[1]
        thresh = cv2.dilate(thresh, None, iterations=2)
        motion_pixels = cv2.countNonZero(thresh)
        return motion_pixels > motion_threshold
    except Exception as e:
        logging.error(f"Error detecting motion: {e}")
        return False


def recognize_face(frame, known_encodings, known_names):
    try:
        rgb_frame = cv2.cvtColor(frame, cv2.COLOR_BGR2RGB)
        face_locations = face_recognition.face_locations(rgb_frame)
        face_encodings = face_recognition.face_encodings(rgb_frame, face_locations)
        for face_encoding in face_encodings:
            matches = face_recognition.compare_faces(known_encodings, face_encoding)
            face_distances = face_recognition.face_distance(known_encodings, face_encoding)
            best_match_index = np.argmin(face_distances)
            if matches[best_match_index] and face_distances[best_match_index] < 0.6:
                confidence = 1 - face_distances[best_match_index]
                name = known_names[best_match_index]
                return name, confidence
        return None, 0.0
    except Exception as e:
        logging.error(f"Error recognizing face: {e}")
        return None, 0.0


def activate_relay(relay, door_open_duration, debounce_time):
    logging.info("Activating relay.")
    relay.on()
    time.sleep(door_open_duration)
    relay.off()
    logging.info("Relay deactivated.")
    time.sleep(debounce_time)


def signal_handler(signum, frame, picam2, relay):
    logging.info(f"Received signal {signum}, shutting down...")
    if picam2:
        try:
            picam2.stop()
        except Exception:
            pass
    if relay:
        try:
            relay.close()
        except Exception:
            pass
    sys.exit(0)


def main():
    parser = argparse.ArgumentParser(description="Facial Recognition Door Access System")
    parser.add_argument("--resolution", type=str, default="640x480")
    parser.add_argument("--motion_threshold", type=int, default=500)
    parser.add_argument("--confidence_threshold", type=float, default=0.6)
    parser.add_argument("--door_open_duration", type=int, default=5)
    parser.add_argument("--debounce_time", type=int, default=2)
    parser.add_argument("--log_level", type=str, default="INFO")
    parser.add_argument("--relay_pin", type=int, default=17)
    args = parser.parse_args()

    config = load_config()
