    config["motion_threshold"] = args.motion_threshold
    config["confidence_threshold"] = args.confidence_threshold
    config["door_open_duration"] = args.door_open_duration
    config["debounce_time"] = args.debounce_time
    config["log_level"] = args.log_level
    config["relay_pin"] = args.relay_pin

    setup_logging(config["log_level"])

    picam2 = initialize_camera(config["resolution"])
    if not picam2:
        logging.critical("Camera initialization failed. Exiting.")
        sys.exit(1)

    relay = None
    try:
        relay = OutputDevice(config["relay_pin"], active_high=True, initial_value=False)
    except Exception as e:
        logging.error(f"Failed to initialize relay on GPIO {config['relay_pin']}: {e}")
        picam2.stop()
        sys.exit(1)

    signal.signal(signal.SIGINT, lambda s, f: signal_handler(s, f, picam2, relay))
    signal.signal(signal.SIGTERM, lambda s, f: signal_handler(s, f, picam2, relay))

    known_encodings = {}
    known_names = {}
    try:
        with open("encodings.json", "r") as f:
            known_encodings = json.load(f)
        if not isinstance(known_encodings, dict):
