        if not isinstance(known_names, dict):
            logging.warning("names.json contains non-dict data; using empty names.")
            known_names = {}
    except FileNotFoundError:
        logging.warning("encodings.json or names.json not found; using empty encodings.")
    except json.JSONDecodeError as e:
        logging.error(f"Error decoding JSON from encodings.json or names.json: {e}")
        known_encodings = {}
        known_names = {}

    last_access_time = 0.0
