import time
import signal
import sys
import cv2
import numpy as np
import RPi.GPIO as GPIO
import serial
from picamera2 import Picamera2

# Constants
CAMERA_RESOLUTION = (160, 120)
CAMERA_FRAMERATE = 16
SERVO_PIN_1 = 7
SERVO_PIN_2 = 13
SERIAL_PORT = '/dev/ttyACM0'
SERIAL_BAUDRATE = 115200
SERVO_FREQUENCY = 50
SERVO_CENTER_DUTY_CYCLE = 7.0
MIN_TARGET_AREA = 10
X_THRESHOLD = 24
SERIAL_RECONNECT_DELAY = 5
MAX_SERIAL_RECONNECT_ATTEMPTS = 3

# Global state for cleanup
running = True
picam2 = None
ser = None


def signal_handler(sig, frame):
    global running
    running = False


def initialize_camera():
    global picam2
    try:
        picam2 = Picamera2()
        config = picam2.create_preview_configuration(
            main={"size": CAMERA_RESOLUTION, "format": "BGR888"},
            controls={"FrameRate": CAMERA_FRAMERATE}
        )
        picam2.configure(config)
        picam2.start()
        return True
    except Exception as e:
        print(f"Error initializing camera: {e}")
        return False


def initialize_servos():
    try:
        GPIO.setmode(GPIO.BOARD)
        GPIO.setup(SERVO_PIN_1, GPIO.OUT)
        GPIO.setup(SERVO_PIN_2, GPIO.OUT)
        servo1 = GPIO.PWM(SERVO_PIN_1, SERVO_FREQUENCY)
        servo2 = GPIO.PWM(SERVO_PIN_2, SERVO_FREQUENCY)
        servo1.start(SERVO_CENTER_DUTY_CYCLE)
        servo2.start(SERVO_CENTER_DUTY_CYCLE)
        return servo1, servo2
    except Exception as e:
        print(f"Error initializing servos: {e}")
        return None, None


def initialize_serial():
    global ser
    for attempt in range(MAX_SERIAL_RECONNECT_ATTEMPTS):
        try:
            ser = serial.Serial(SERIAL_PORT, SERIAL_BAUDRATE, timeout=1)
            time.sleep(2)
            return True
        except serial.SerialException as e:
            print(f"Serial connection failed (attempt {attempt + 1}/{MAX_SERIAL_RECONNECT_ATTEMPTS}): {e}")
            if attempt < MAX_SERIAL_RECONNECT_ATTEMPTS - 1:
                time.sleep(SERIAL_RECONNECT_DELAY)
            else:
                print("Max serial reconnect attempts reached. Exiting.")
                return False
    return False


def segment_red_hsv(frame):
    hsv = cv2.cvtColor(frame, cv2.COLOR_BGR2HSV)
    lower_red = np.array([160, 160, 10])
    upper_red = np.array([190, 255, 255])
    mask = cv2.inRange(hsv, lower_red, upper_red)
    return mask


def segment_red_ycrcb(frame):
    ycr = cv2.cvtColor(frame, cv2.COLOR_BGR2YCrCb)
    lower_red = np.array([0, 165, 0])
    upper_red = np.array([255, 255, 255])
    mask = cv2.inRange(ycr, lower_red, upper_red)
    return mask


def find_blob(mask):
    contours, _ = cv2.findContours(mask, cv2.RETR_EXTERNAL, cv2.CHAIN_APPROX_SIMPLE)
    largest_contour = (0, 0, 2, 2)
    largest_area = 0
    for contour in contours:
        area = cv2.contourArea(contour)
        if area > largest_area:
            largest_area = area
            largest_contour = cv2.boundingRect(contour)
    return largest_contour, largest_area


def control_servo(servo1, servo2, servo1_angle, servo2_angle):
    try:
        servo1.ChangeDutyCycle(servo1_angle)
        servo2.ChangeDutyCycle(servo2_angle)
    except Exception as e:
        print(f"Error controlling servos: {e}")


def send_command(ser, command):
    try:
        ser.write(command.encode() + b'\n')
    except serial.SerialException as e:
        print(f"Error sending command: {e}")


def cleanup():
    global picam2, ser
    print("Cleaning up resources...")
    if picam2 is not None:
        try:
            picam2.stop()
        except Exception:
            pass
    if ser is not None and ser.is_open:
        try:
            ser.close()
        except Exception:
            pass
    if servo1 is not None:
        try:
            servo1.stop()
        except Exception:
            pass
    if servo2 is not None:
        try:
            servo2.stop()
        except Exception:
            pass
    GPIO.cleanup()
    print("Cleanup complete.")


signal.signal(signal.SIGINT, signal_handler)
signal.signal(signal.SIGTERM, signal_handler)

servo1 = None
servo2 = None

if initialize_camera() and initialize_servos() and initialize_serial():
    try:
        while running:
            frame = picam2.capture_array()
            if frame is None:
                continue

            mask1 = segment_red_hsv(frame)
            mask2 = segment_red_ycrcb(frame)
            mask = cv2.bitwise_and(mask1, mask2)

            x, y, w, h = find_blob(mask)

            if w * h > MIN_TARGET_AREA:
                center_x = x + w / 2. - CAMERA_RESOLUTION[0] / 2.
                center_y = CAMERA_RESOLUTION[1] / 2. - (y + h / 2.)

                if abs(center_x) > X_THRESHOLD:
                    if center_x > 0:
                        send_command(ser, "Forward")
                    else:
                        send_command(ser, "Backward")

                control_servo(servo1, servo2, 2.5, 10.0) if center_y > 0 else control_servo(servo1, servo2, 12.5, 2.5)
            else:
                send_command(ser, "Stop")
                control_servo(servo1, servo2, SERVO_CENTER_DUTY_CYCLE, SERVO_CENTER_DUTY_CYCLE)

            cv2.imshow("Mask", mask)
            if cv2.waitKey(1) & 0xFF == ord('q'):
                break
    except Exception as e:
        print(f"Runtime error: {e}")
    finally:
        cleanup()
else:
    cleanup()
    sys.exit(1)

