import os
import signal
import sys
import time
from datetime import datetime

import numpy as np
import mxnet as mx
from mxnet import image, nd
from mxnet.gluon.model_zoo import vision as models
from mxnet.gluon.utils import download

try:
    from picamera2 import Picamera2
except ImportError:
    print("picamera2 is not installed. Install with: pip install picamera2", file=sys.stderr)
    sys.exit(1)

# ---------------------------------------------------------------------------
# Globals for cleanup
# ---------------------------------------------------------------------------
_camera = None
_running = True


def _signal_handler(signum, frame):
    global _running
    _running = False


signal.signal(signal.SIGINT, _signal_handler)
signal.signal(signal.SIGTERM, _signal_handler)


def cleanup():
    global _camera
    if _camera is not None:
        try:
            _camera.stop()
        except Exception:
            pass
        try:
            _camera.close()
        except Exception:
            pass
        _camera = None


def transform_image(img_path):
    """Transform a raw image into a normalized 224x224x3 float32 tensor."""
    try:
        img = image.imread(img_path)
    except Exception as exc:
        raise RuntimeError(f"Failed to read image '{img_path}': {exc}") from exc

    if img is None:
        raise RuntimeError(f"Image data is None for path '{img_path}'")

    # Resize to the short side of 256, then center-crop to 224x224
    try:
        resized = image.resize_short(img, 256)
        cropped, _ = image.center_crop(resized, (224, 224))
    except Exception as exc:
        raise RuntimeError(f"Image transformation failed: {exc}") from exc

    # Convert to float32, add batch dimension, and normalize
    try:
        x = cropped.astype('float32') / 255.0
        x = x.transpose((2, 0, 1)).expand_dims(axis=0)
        mean = nd.array([0.485, 0.456, 0.406]).reshape((1, 3, 1, 1))
        std = nd.array([0.229, 0.224, 0.225]).reshape((1, 3, 1, 1))
        return (x - mean) / std
    except Exception as exc:
        raise RuntimeError(f"Normalization failed: {exc}") from exc


def predict(img_path, text_labels, text_prob):
    """Load the pretrained model, transform the image, and print top-3 results."""
    global _camera

    # --- Load the model ----------------------------------------------------
    try:
        net = models.resnet50_v2(pretrained=True)
    except Exception as exc:
        raise RuntimeError(f"Failed to load ResNet-50_v2 model: {exc}") from exc

    # --- Capture image -----------------------------------------------------
    try:
        _camera = Picamera2(0)
        config = _camera.create_still_configuration(
            main={"size": (640, 480), "format": "RGB888"}
        )
        _camera.configure(config)
        _camera.start()
    except Exception as exc:
