import io
import logging
import signal
import threading
from typing import Callable, Optional

import cv2
import numpy as np

try:
    from picamera2 import Picamera2
except ImportError:
    Picamera2 = None

logger = logging.getLogger(__name__)


class WebSocketHandler:
    """Stub WebSocket handler interface."""

    def has_connections(self) -> bool:
        raise NotImplementedError

    def broadcast(self, data: bytes) -> None:
        raise NotImplementedError


class CameraStreamBuffer:
    """Buffers raw JPEG bytes from picamera2 and broadcasts complete frames over WebSocket."""

    def __init__(self, web_socket_handler: WebSocketHandler):
        if not isinstance(web_socket_handler, WebSocketHandler):
            raise TypeError("web_socket_handler must be a WebSocketHandler instance")
        self.web_socket_handler = web_socket_handler
        self.buffer = io.BytesIO()
        self.lock = threading.Lock()
        self._frame: Optional[bytes] = None

    def write(self, data: bytes) -> int:
        """Called by picamera2 with raw JPEG bytes. Returns number of bytes written."""
        try:
            with self.lock:
                self.buffer.write(data)
                # Detect start of new JPEG via SOI marker (0xff 0xd8)
                while data:
                    marker = data[:2]
                    if marker.startswith(b'\xff\xd8'):
                        # Found start of new JPEG — finalize previous frame
                        frame_data = self.buffer.getvalue()
                        if frame_data:
                            self._frame = frame_data
                        self.buffer.seek(0)
                        self.buffer.truncate()
                        data = data[2:]
                    else:
                        self.buffer.write(data[:2])
                        data = data[2:]
                return len(data)
        except Exception as e:
            logger.error("Error in CameraStreamBuffer.write: %s", e)
            return 0

    def has_frame(self) -> bool:
        with self.lock:
            return self._frame is not None

    def get_frame(self) -> Optional[bytes]:
        with self.lock:
            frame = self._frame
            self._frame = None
            return frame

    def flush(self) -> None:
        """Emit any remaining buffered frame."""
        with self.lock:
            if self._frame is not None:
                self.web_socket_handler.broadcast(self._frame)
                self._frame = None


class MotionDetectionBuffer:
    """Detects motion between consecutive JPEG frames using OpenCV."""

    def __init__(self, detect_motion_function: Callable[[np.ndarray, np.ndarray], None]):
        if not callable(detect_motion_function):
            raise TypeError("detect_motion_function must be callable")
        self.detect_motion_function = detect_motion_function
        self.buffer = io.BytesIO()
        self.lock = threading.Lock()
        self.previous_frame: Optional[np.ndarray] = None
        self.current_frame: Optional[np.ndarray] = None

    def _convert_to_opencv_frame(self, frame_data: bytes) -> Optional[np.ndarray]:
        try:
            if not frame_data:
                return None
            data = np.frombuffer(frame_data, dtype=np.uint8)
            frame = cv2.imdecode(data, cv2.IMREAD_COLOR)
            if frame is None:
                logger.error("cv2.imdecode returned None for frame data")
                return None
            return frame
        except Exception as e:
            logger.error("Error converting frame data to OpenCV frame: %s", e)
            return None

    def write(self, data: bytes) -> int:
        """Called by picamera2 with raw JPEG bytes. Returns number of bytes written."""
        try:
            with self.lock:
                self.buffer.write(data)
                # Detect start of new JPEG via SOI marker (0xff 0xd8)
                while data:
                    marker = data[:2]
                    if marker.startswith(b'\xff\xd8'):
                        # Found start of new JPEG — process previous frame
                        frame_data = self.buffer.getvalue()
                        if frame_data:
                            frame = self._convert_to_opencv_frame(frame_data)
                            if frame is not None:
                                self.previous_frame = self.current_frame
                                self.current_frame = frame
                                if self.previous_frame is not None:
                                    self.detect_motion_function(
                                        self.previous_frame, self.current_frame
                                    )
                        self.buffer.seek(0)
                        self.buffer.truncate()
                        data = data[2:]
                    else:
                        self.buffer.write(data[:2])
                        data = data[2:]
                return len(data)
        except Exception as e:
            logger.error("Error in MotionDetectionBuffer.write: %s", e)
            return 0

    def flush(self) -> None:
        """Emit any remaining buffered frame."""
        with self.lock:
            if self.buffer.tell() > 0:
                frame_data = self.buffer.getvalue()
                frame = self._convert_to_opencv_frame(frame_data)
                if frame is not None:
                    self.previous_frame = self.current_frame
                    self.current_frame = frame
                    if self.previous_frame is not None:
                        self.detect_motion_function(
                            self.previous_frame, self.current_frame
                        )
                self.buffer.seek(0)
                self.buffer.truncate()


_shutdown_requested = False


def _signal_handler(signum, frame):
    global _shutdown_requested
    logger.info("Signal %s received, shutting down...", signum)
    _shutdown_requested = True


def main():
    logging.basicConfig(level=logging.INFO)
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    if Picamera2 is None:
        logger.error("picamera2 library not installed")
        return

    picam2 = Picamera2()
    video_config = picam2.create_video_configuration(
        main={"size": (640, 480), "format": "RGB888"},
        controls={"FrameRate": 10},
    )
    picam2.configure(video_config)

    stream_buffer = CameraStreamBuffer(WebSocketHandler())
    motion_buffer = MotionDetectionBuffer(lambda p, c: logger.info("Motion detected"))

    try:
        picam2.start()
        logger.info("Camera started. Streaming frames...")
        while not _shutdown_requested:
            frame = picam2.capture_array()
            if frame is None:
                logger.warning("capture_array returned None")
                continue
            # picamera2 returns RGB888; convert to JPEG bytes
            ok, encoded = cv2.imencode(".jpg", frame)
            if not ok:
                logger.warning("Failed to encode frame to JPEG")
                continue
            jpeg_bytes = encoded.tobytes()
            stream_buffer.write(jpeg_bytes)
            motion_buffer.write(jpeg_bytes)
    except Exception as e:
        logger.error("Camera error: %s", e)
    finally:
        logger.info("Stopping camera...")
        try:
            picam2.stop()
        except Exception as e:
            logger.error("Error stopping camera: %s", e)
        stream_buffer.flush()
        motion_buffer.flush()
        logger.info("Shutdown complete.")


if __name__ == "__main__":
    main()

