import os
import sys
import signal
import logging
import threading
from http.server import BaseHTTPRequestHandler, HTTPServer
from threading import Condition, Event
from typing import Optional, Tuple

import cv2
import numpy as np
from picamera2 import Picamera2
from twilio.rest import Client

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')
logger = logging.getLogger(__name__)

TWILIO_ACCOUNT_SID = os.environ.get("TWILIO_ACCOUNT_SID")
TWILIO_AUTH_TOKEN = os.environ.get("TWILIO_AUTH_TOKEN")
TWILIO_PHONE_NUMBER = os.environ.get("TWILIO_PHONE_NUMBER")
RECIPIENT_PHONE_NUMBER = os.environ.get("RECIPIENT_PHONE_NUMBER")

FACE_CASCADE_PATH = "/home/pi/Downloads/IoT-and-Computing-Lab-main/haarcascade_frontalface_default.xml"
MOTION_THRESHOLD = 10000
RESOLUTION = (640, 480)
FRAMERATE = 15
SERVER_PORT = 8000

HTML_PAGE = """<html>
<head><title>Raspberry Pi Surveillance Stream</title></head>
<body>
<h1>Raspberry Pi Surveillance Stream</h1>
<img src="stream.mjpg" width="640" height="480" />
</body>
</html>"""

class MotionDetector:
    def __init__(self, threshold: int = MOTION_THRESHOLD):
        self.threshold = threshold
        self.prev_frame: Optional[np.ndarray] = None
        self.condition = Condition()

    def detect(self, frame: np.ndarray) -> bool:
        gray = cv2.cvtColor(frame, cv2.COLOR_BGR2GRAY)
        gray = cv2.GaussianBlur(gray, (21, 21), 0)

        if self.prev_frame is None:
            self.prev_frame = gray
            return False

        frame_delta = cv2.absdiff(self.prev_frame, gray)
        thresh = cv2.threshold(frame_delta, 25, 255, cv2.THRESH_BINARY)[1]
        thresh = cv2.dilate(thresh, None, iterations=2)

        contours, _ = cv2.findContours(thresh.copy(), cv2.RETR_EXTERNAL, cv2.CHAIN_APPROX_SIMPLE)

        self.prev_frame = gray
        for contour in contours:
            if cv2.contourArea(contour) >= self.threshold:
                with self.condition:
                    self.condition.notify_all()
                return True
        return False

class FaceDetector:
    def __init__(self, cascade_path: str):
        if not os.path.exists(cascade_path):
            raise FileNotFoundError(f"Haar cascade file not found: {cascade_path}")
        self.face_cascade = cv2.CascadeClassifier(cascade_path)
        if self.face_cascade.empty():
            raise ValueError(f"Failed to load Haar cascade from {cascade_path}")

    def detect(self, frame: np.ndarray) -> np.ndarray:
        gray = cv2.cvtColor(frame, cv2.COLOR_BGR2GRAY)
        faces = self.face_cascade.detectMultiScale(gray, scaleFactor=1.1, minNeighbors=5, minSize=(30, 30))
        for (x, y, w, h) in faces:
            cv2.rectangle(frame, (x, y), (x + w, y + h), (0, 255, 0), 2)
        return frame

class SurveillanceCamera:
    def __init__(self, resolution: Tuple[int, int] = RESOLUTION, framerate: int = FRAMERATE):
        self.picam2 = Picamera2()
        config = self.picam2.create_preview_configuration(
            main={"size": resolution, "format": "BGR888"},
            controls={"FrameRate": framerate}
        )
        self.picam2.configure(config)
        self.picam2.start()
        self.rotation = 180
        self.apply_rotation()

    def apply_rotation(self):
        try:
            self.picam2.set_controls({"Hflip": True, "Vflip": True})
        except Exception as e:
            logger.warning(f"Failed to apply rotation: {e}")

    def read_frame(self) -> Optional[np.ndarray]:
        try:
            return self.picam2.capture_array()
        except Exception as e:
            logger.error(f"Error reading frame: {e}")
            return None

    def close(self):
        try:
            self.picam2.stop()
        except Exception:
            pass

class StreamingHttpHandler(BaseHTTPRequestHandler):
    def do_GET(self):
        if self.path == '/':
            self.send_response(301)
            self.send_header('Location', '/index.html')
            self.end_headers()
        elif self.path == '/index.html':
            self.send_html_page()
        elif self.path == '/stream.mjpg':
            self.stream_video()
        else:
            self.send_error(404)
            self.end_headers()

    def send_html_page(self):
        content = HTML_PAGE.encode('utf-8')
