import io
import logging
import numpy as np
import cv2
from picamera2 import Picamera2

logging.basicConfig(level=logging.INFO, format="%(asctime)s [%(levelname)s] %(message)s")
log = logging.getLogger("camera_buffers")


class CameraStreamBuffer:
    """Accumulates MJPEG bytes from picamera2, flushing complete P-frames to an output sink."""

    def __init__(self, c: Picamera2, sink=None):
        self.c = c
        self.b = io.BytesIO()
        self._sink = sink if sink is not None else (lambda x: None)

    def write(self, d: bytes) -> int:
        """Write raw bytes; flush a P-frame when complete and frame_type != 1."""
        try:
            self.b.write(d)
            cfg = self.c.current_configuration()
            metadata = cfg.get("metadata", {})
            frame_complete = metadata.get("frame_complete", False)
            frame_type = metadata.get("frame_type", 0)
            if frame_complete and frame_type != 1:
                self._sink(self.b.getvalue())
                self.b.seek(0)
                self.b.truncate(0)
            return len(d)
        except Exception as exc:
            log.error("CameraStreamBuffer write error: %s", exc)
            return len(d)


class MotionDetectionBuffer:
    """MJPEG parser that invokes a callback with BGR frames separated by SOI markers."""

    def __init__(self, f):
        self.f = f
        self.b = io.BytesIO()
        self._prev = None

    def write(self, d: bytes) -> int:
        """Parse MJPEG byte stream; callback invoked on each decoded frame (skipping the first)."""
        try:
            self.b.write(d)
            s = self.b.getvalue()
            if not s:
                return len(d)
            # Find the SOI marker (\xff\xd8) which separates JPEG frames.
            soi_idx = s.find(b"\xff\xd8")
            if soi_idx == -1:
                return len(d)
            prev = self._prev
            self.b.seek(0)
            frame = np.frombuffer(self.b.read(soi_idx), dtype=np.uint8)
            self.b.seek(0)
            self.b.truncate(0)
            if frame.size == 0:
                return len(d)
            curr = cv2.imdecode(frame, cv2.IMREAD_COLOR)
            if curr is None:
                log.warning("Failed to decode JPEG frame: %s", frame)
                return len(d)
            if prev is not None:
                self.f(prev, curr)
            self._prev = curr
            return len(d)
        except Exception as exc:
            log.error("MotionDetectionBuffer write error: %s", exc)
            return len(d)

