import cv2
import pygame.mixer
import time
import signal
import sys
import os
from threading import Thread

import config
import face

from gpiozero import Button, OutputDevice
from picamera2 import Picamera2

# ---------------------------------------------------------------------------
# Globals for cleanup
# ---------------------------------------------------------------------------
_running = True
_camera = None
_door = None
_button = None
_sound_channel = None


def _signal_handler(signum, frame):
    global _running
    _running = False


def _cleanup():
    global _camera, _door, _button, _sound_channel
    if _door is not None:
        _door.close()
        _door = None
    if _button is not None:
        _button.close()
        _button = None
    if _camera is not None:
        _camera.stop()
        _camera = None
    if _sound_channel is not None:
        _sound_channel.stop()
        _sound_channel = None
    pygame.mixer.quit()


def load_sound(path):
    if not os.path.isfile(path):
        raise FileNotFoundError(f"Sound file not found: {path}")
    try:
        return pygame.mixer.Sound(path)
    except pygame.error as exc:
        raise RuntimeError(f"Failed to load sound '{path}': {exc}") from exc


def load_model():
    if not os.path.isfile(config.TRAINING_FILE):
        raise FileNotFoundError(f"Model file not found: {config.TRAINING_FILE}")
    try:
        return cv2.face.EigenFaceRecognizer_create().read(config.TRAINING_FILE)
    except cv2.error as exc:
        raise RuntimeError(f"Failed to load model '{config.TRAINING_FILE}': {exc}") from exc


def init_hardware():
    global _camera, _door, _button
    try:
        _camera = Picamera2()
        _camera.configure(_camera.create_preview_configuration(main={"format": "RGB888"}))
        _camera.start()
    except Exception as exc:
        raise RuntimeError(f"Failed to initialize camera: {exc}") from exc

    try:
        _door = OutputDevice(18, active_high=True, initial_value=True)
    except Exception as exc:
        raise RuntimeError(f"Failed to initialize door lock on GPIO 18: {exc}") from exc

    try:
        _button = Button(17, pull_up=True)
    except Exception as exc:
        raise RuntimeError(f"Failed to initialize button on GPIO 17: {exc}") from exc


def init_audio():
    global _sound_channel
    try:
        pygame.mixer.init(frequency=48000, size=-16, channels=1, buffer=1024)
    except pygame.error as exc:
        raise RuntimeError(f"Failed to initialize pygame.mixer: {exc}") from exc

    try:
        welcome = load_sound(config.WELCOME_SOUND)
        wait = load_sound(config.WAIT_SOUND)
        later = load_sound(config.LATER_SOUND)
    except (FileNotFoundError, RuntimeError) as exc:
        raise RuntimeError(f"Failed to load sounds: {exc}") from exc

    try:
        _sound_channel = pygame.mixer.Channel(0)
    except pygame.error as exc:
        raise RuntimeError(f"Failed to create mixer channel: {exc}") from exc

    return welcome, wait, later


def recognize_face(model, camera):
    try:
        frame = camera.capture_array()
    except Exception as exc:
        print(f"Camera capture error: {exc}")
        return None

    if frame is None or frame.size == 0:
        print("Empty frame received from camera.")
        return None

    try:
        gray = cv2.cvtColor(frame, cv2.COLOR_RGB2GRAY)
        label, confidence = model.predict(gray)
        return label, confidence
    except cv2.error as exc:
        print(f"Face recognition error: {exc}")
        return None


def main():
    global _running

    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    try:
        init_hardware()
    except RuntimeError as exc:
        print(f"Hardware init failed: {exc}")
        _cleanup()
        sys.exit(1)

    try:
        model = load_model()
    except RuntimeError as exc:
        print(f"Model load failed: {exc}")
        _cleanup()
        sys.exit(1)

    try:
        welcome, wait, later = init_audio()
    except RuntimeError as exc:
        print(f"Audio init failed: {exc}")
        _cleanup()
        sys.exit(1)

    print("Running. Press Ctrl+C to exit.")

    try:
        while _running:
            if _button.is_active:
                label, confidence = recognize_face(model, _camera)

                if label is None:
                    print("Face recognition failed.")
                    if _sound_channel is not None:
                        _sound_channel.play(later)
                elif label == config.POSITIVE_LABEL and confidence < config.POSITIVE_THRESHOLD:
                    print("Face recognized! Unlocking...")
                    _door.off()
                    if _sound_channel is not None:
                        _sound_channel.play(welcome)
                else:
                    print("Face not recognized.")
                    if _sound_channel is not None:
                        _sound_channel.play(wait)

            time.sleep(0.1)
    except Exception as exc:
        print(f"Runtime error: {exc}")
    finally:
        _cleanup()


if __name__ == "__main__":
    main()

