    except (FileNotFoundError, RuntimeError) as exc:
        raise RuntimeError(f"Failed to load sounds: {exc}") from exc

    try:
        _sound_channel = pygame.mixer.Channel(0)
    except pygame.error as exc:
        raise RuntimeError(f"Failed to create mixer channel: {exc}") from exc

    return welcome, wait, later


def recognize_face(model, camera):
    try:
        frame = camera.capture_array()
    except Exception as exc:
        print(f"Camera capture error: {exc}")
        return None

    if frame is None or frame.size == 0:
        print("Empty frame received from camera.")
        return None

    try:
        gray = cv2.cvtColor(frame, cv2.COLOR_RGB2GRAY)
        label, confidence = model.predict(gray)
        return label, confidence
    except cv2.error as exc:
        print(f"Face recognition error: {exc}")
        return None


def main():
    global _running

    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    try:
        init_hardware()
    except RuntimeError as exc:
        print(f"Hardware init failed: {exc}")
        _cleanup()
        sys.exit(1)

    try:
        model = load_model()
    except RuntimeError as exc:
        print(f"Model load failed: {exc}")
        _cleanup()
        sys.exit(1)

    try:
        welcome, wait, later = init_audio()
    except RuntimeError as exc:
        print(f"Audio init failed: {exc}")
        _cleanup()
        sys.exit(1)

    print("Running. Press Ctrl+C to exit.")

    try:
        while _running:
            if _button.is_active:
                label, confidence = recognize_face(model, _camera)

                if label is None:
                    print("Face recognition failed.")
                    if _sound_channel is not None:
                        _sound_channel.play(later)
                elif label == config.POSITIVE_LABEL and confidence < config.POSITIVE_THRESHOLD:
                    print("Face recognized! Unlocking...")
                    _door.off()
                    if _sound_channel is not None:
                        _sound_channel.play(welcome)
                else:
                    print("Face not recognized.")
                    if _sound_channel is not None:
                        _sound_channel.play(wait)

            time.sleep(0.1)
    except Exception as exc:
        print(f"Runtime error: {exc}")
    finally:
        _cleanup()


if __name__ == "__main__":
    main()

