import signal
import sys
import time
from smbus2 import SMBus
from luma.core.interface.serial import i2c
from luma.oled.device import ssd1306

I2C_BUS = 1
BH1750_ADDR = 0x23
OLED_ADDR = 0x3C
BH1750_CMD_ONE_TIME_HIGH_RES = 0x20
CONVERSION_DELAY_S = 0.12
LOOP_INTERVAL_S = 1.0

running = True
bus = None
display = None

def signal_handler(signum, frame):
    global running
    running = False

def read_light_level(bus, addr):
    bus.write_byte(addr, BH1750_CMD_ONE_TIME_HIGH_RES)
    time.sleep(CONVERSION_DELAY_S)
    data = bus.read_i2c_block_data(addr, 0x00, 2)
    raw = (data[0] << 8) | data[1]
    return raw / 1.2

def lux_to_contrast(lux):
    return int(255 * lux / 65535.0)

def main():
    global bus, display
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        bus = SMBus(I2C_BUS)
    except OSError as e:
        print(f"Failed to open I2C bus {I2C_BUS}: {e}", file=sys.stderr)
        sys.exit(1)

    try:
        display = ssd1306(i2c(port=I2C_BUS, address=OLED_ADDR))
    except Exception as e:
        print(f"Failed to initialize SSD1306 at 0x{OLED_ADDR:02X}: {e}", file=sys.stderr)
        bus.close()
        sys.exit(1)

    try:
        while running:
            try:
                lux = read_light_level(bus, BH1750_ADDR)
                contrast = lux_to_contrast(lux)
                display.contrast = contrast
            except OSError as e:
                print(f"I2C error reading light sensor: {e}", file=sys.stderr)
            except Exception as e:
                print(f"Unexpected error: {e}", file=sys.stderr)

            time.sleep(LOOP_INTERVAL_S)
    finally:
        if display is not None:
            try:
                display.clear()
            except Exception:
                pass
        if bus is not None:
            try:
                bus.close()
            except Exception:
                pass

if __name__ == "__main__":
    main()

