LCD_ROWS = 2
I2C_ADDRESS = 0x27
DHT_PIN = board.D4
UPDATE_INTERVAL = 2.0

# Global resources for cleanup
lcd = None
dht_device = None
running = True


def signal_handler(signum, frame):
    """Handle SIGINT/SIGTERM for clean shutdown."""
    global running
    running = False


def cleanup():
    """Clear the LCD and release sensor resources."""
    global lcd, dht_device
    if lcd is not None:
        try:
            lcd.clear()
        except Exception:
            pass
    if dht_device is not None:
        try:
            dht_device.exit()
        except Exception:
            pass


def initialize_i2c():
    """Initialize the I2C bus."""
    try:
        i2c_bus = busio.I2C(board.SCL, board.SDA)
        return i2c_bus
    except Exception as e:
        print(f"Error initializing I2C bus: {e}")
        return None


def initialize_lcd(i2c_bus):
    """Initialize the LCD display."""
    try:
        lcd_display = character_lcd.Character_LCD_I2C(i2c_bus, LCD_COLUMNS, LCD_ROWS, address=I2C_ADDRESS)
        return lcd_display
    except Exception as e:
        print(f"Error initializing LCD at address 0x{I2C_ADDRESS:02X}: {e}")
        return None


def initialize_dht22():
    """Initialize the DHT22 sensor."""
    try:
        sensor = adafruit_dht.DHT22(DHT_PIN, use_pulseio=False)
        return sensor
    except Exception as e:
        print(f"Error initializing DHT22 sensor on GPIO4: {e}")
        return None


def read_sensor_data(sensor):
    """Read temperature and humidity from the DHT22 sensor."""
    try:
        temperature = sensor.temperature
        humidity = sensor.humidity
        if temperature is None or humidity is None:
            raise RuntimeError("Sensor returned None for temperature or humidity")
        return temperature, humidity
    except Exception as e:
        print(f"Error reading DHT22 sensor: {e}")
        return None, None


def display_data(lcd_display, temperature, humidity):
    """Display temperature and humidity on the LCD."""
    try:
        lcd_display.message = f"Temp: {temperature:.1f} C\nHumidity: {humidity:.1f}%"
    except Exception as e:
        print(f"Error displaying data on LCD: {e}")


def main():
    """Main function to read sensor data and display it on the LCD."""
    global lcd, dht_device

    # Register signal handlers for clean shutdown
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    i2c_bus = initialize_i2c()
    if i2c_bus is None:
        sys.exit(1)

    lcd = initialize_lcd(i2c_bus)
    if lcd is None:
        sys.exit(1)

    dht_device = initialize_dht22()
    if dht_device is None:
        sys.exit(1)

    try:
        while running:
            temperature, humidity = read_sensor_data(dht_device)
            if temperature is not None and humidity is not None:
                display_data(lcd, temperature, humidity)
            time.sleep(UPDATE_INTERVAL)
    except Exception as e:
        print(f"Unexpected error in main loop: {e}")
    finally:
        cleanup()


if __name__ == "__main__":
    main()

