import os
import signal
import sys
import time
from typing import List, Optional

from PIL import Image, ImageOps
from luma.core.interface.serial import spi
from luma.core.render import canvas
from luma.lcd.device import st7789

GIF_FOLDER = os.getcwd()
DISPLAY_WIDTH = 240
DISPLAY_HEIGHT = 240
FRAME_DURATION_MS = 100


class GifPlayer:
    """
    A class to manage playing GIF files on an ST7789 display via SPI.
    """

    def __init__(self, display_width: int = DISPLAY_WIDTH, display_height: int = DISPLAY_HEIGHT):
        self.display_width = display_width
        self.display_height = display_height
        self.gif_files: List[str] = []
        self.gif_sequence: List[Optional[Image.Image]] = []
        self.serial = None
        self.device = None
        self._running = True

        try:
            self.serial = spi(port=0, device=0)
            self.device = st7789(self.serial, width=display_width, height=display_height)
        except Exception as e:
            print(f"Error initializing ST7789 display: {e}")
            self.cleanup()
            raise

    def _signal_handler(self, signum, frame):
        print(f"\nReceived signal {signum}, shutting down...")
        self._running = False

    def get_gif_files(self, folder: str = GIF_FOLDER) -> List[str]:
        try:
            gif_files = [f for f in os.listdir(folder) if f.lower().endswith('.gif')]
            if not gif_files:
                print(f"No GIF files found in {folder}")
            return gif_files
        except FileNotFoundError:
            print(f"Error: Folder not found: {folder}")
            return []
        except Exception as e:
            print(f"Error listing files in {folder}: {e}")
            return []

    def load_gif(self, filename: str) -> Optional[List[Image.Image]]:
        try:
            with Image.open(filename) as image:
                if image.is_animated:
                    duration = image.info.get("duration")
                    if duration is None:
                        duration = FRAME_DURATION_MS
                    frames = [image.convert("RGB") for _ in range(image.n_frames)]
                    for i in range(image.n_frames):
                        image.seek(i)
                        frames[i] = image.convert("RGB")
                    return frames, duration
                else:
                    return [image.convert("RGB")], None
        except FileNotFoundError:
