import smbus2
import time
import signal
import sys

LCD_ADDR = 0x27
I2C_BUS = 1

# PCF8574 bit layout for common I2C LCD backpacks
EN = 0x04
RW = 0x02
RS = 0x01
BL = 0x08

i2c_bus = None


def lcd_write_byte(byte_val, rs_mode):
    """Write a byte to the HD44780 via the PCF8574 expander."""
    high = byte_val & 0xF0
    low = (byte_val << 4) & 0xF0
    for nibble in (high, low):
        data = nibble | BL | rs_mode
        try:
            i2c_bus.write_byte(LCD_ADDR, data)
        except OSError:
            raise
        time.sleep(0.001)
        try:
            i2c_bus.write_byte(LCD_ADDR, data | EN)
        except OSError:
            raise
        time.sleep(0.001)
        try:
            i2c_bus.write_byte(LCD_ADDR, data & ~EN)
        except OSError:
            raise


def lcd_command(cmd):
    lcd_write_byte(cmd, 0)
    if cmd in (0x01, 0x02):
        time.sleep(0.002)


def lcd_data(data):
    lcd_write_byte(data, RS)


def cleanup(signum=None, frame=None):
    global i2c_bus
    if i2c_bus is not None:
        try:
            lcd_command(0x01)
            time.sleep(0.05)
        except OSError:
            pass
        try:
            i2c_bus.close()
        except OSError:
            pass
        i2c_bus = None
    if signum is not None:
        sys.exit(0)


def main():
    global i2c_bus
    signal.signal(signal.SIGINT, cleanup)
    signal.signal(signal.SIGTERM, cleanup)

    try:
        i2c_bus = smbus2.SMBus(I2C_BUS)
    except OSError as e:
        print(f"Failed to open I2C bus {I2C_BUS}: {e}", file=sys.stderr)
        sys.exit(1)

    try:
        lcd_command(0x33)
        lcd_command(0x32)
        lcd_command(0x28)   # 2-line display, 5x8 font
        lcd_command(0x0C)   # Display ON, cursor OFF, blink OFF
        lcd_command(0x06)   # Entry mode: increment, no shift
        lcd_command(0x01)   # Clear display
        time.sleep(0.05)

        for ch in "Hello, Pi!":
            lcd_data(ord(ch))
            time.sleep(0.05)

        time.sleep(2)

        lcd_command(0x01)
        time.sleep(0.05)

        for ch in "I2C LCD Ready":
            lcd_data(ord(ch))
            time.sleep(0.05)

    except OSError as e:
        print(f"I2C communication error with LCD at 0x{LCD_ADDR:02X}: {e}", file=sys.stderr)
    finally:
        cleanup()


if __name__ == "__main__":
    main()

