    from luma.core.render import canvas
    from luma.oled.device import ssd1306
except ImportError as e:
    print(f"Missing required library: {e}")
    print("Install with: pip install luma.oled luma.core pillow")
    sys.exit(1)

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')
logger = logging.getLogger(__name__)

GIF_FOLDER = "gifs"
DISPLAY_WIDTH = 128
DISPLAY_HEIGHT = 64
I2C_PORT = 1
I2C_ADDRESS = 0x3C

_running = True

def _signal_handler(signum, frame):
    global _running
    _running = False
    logger.info("Shutdown signal received, exiting...")

def load_gif_files(folder):
    if not os.path.isdir(folder):
        logger.error(f"Folder not found: {folder}")
        return []
    return [os.path.join(folder, f) for f in os.listdir(folder) if f.lower().endswith(".gif")]

def resize_frame(frame, width, height):
    try:
        resized = ImageOps.fit(frame, (width, height), method=Image.LANCZOS, bleed=0.0, centering=(0.5, 0.5))
        padded = Image.new("RGB", (width, height), (0, 0, 0))
        padded.paste(resized, (0, 0))
        return padded
    except Exception as e:
        logger.error(f"Error resizing frame: {e}")
        return None

def play_gif(device, gif_path, loop_count=None):
    try:
        with Image.open(gif_path) as image:
            if image.is_animated:
                n_frames = image.n_frames
                loop = loop_count if loop_count is not None else 0
                for i in range(n_frames):
                    if not _running:
                        break
                    image.seek(i)
                    duration = image.info.get("duration", 100)
                    frame = image.convert("RGB")
                    resized_frame = resize_frame(frame, DISPLAY_WIDTH, DISPLAY_HEIGHT)
                    if resized_frame is None:
                        continue
                    with canvas(device) as draw:
                        draw.rectangle((0, 0, DISPLAY_WIDTH - 1, DISPLAY_HEIGHT - 1), outline="black", fill="black")
                        draw.image(resized_frame)
                    time.sleep(duration / 1000.0)
                    if loop > 0 and i >= n_frames - 1:
                        break
            else:
                logger.warning(f"File {gif_path} is not an animated GIF.")
    except FileNotFoundError:
        logger.error(f"GIF file not found: {gif_path}")
    except Exception as e:
        logger.error(f"Error playing GIF {gif_path}: {e}")

def main():
    global _running
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    try:
        serial = i2c(port=I2C_PORT, address=I2C_ADDRESS)
        device = ssd1306(serial, width=DISPLAY_WIDTH, height=DISPLAY_HEIGHT)
    except Exception as e:
        logger.error(f"Failed to initialize I2C or OLED display: {e}")
        sys.exit(1)

    try:
        gif_files = load_gif_files(GIF_FOLDER)
        if not gif_files:
            logger.warning(f"No GIF files found in folder: {GIF_FOLDER}")
            return

        for gif_path in gif_files:
            if not _running:
                break
            logger.info(f"Playing GIF: {gif_path}")
            play_gif(device, gif_path)
            if not _running:
                break
    finally:
        try:
            device.cleanup()
        except Exception:
            pass

if __name__ == "__main__":
    main()

