            logging.error(f"I2C bus {self.i2c_bus_num} not found. Enable I2C and check /dev/i2c-{self.i2c_bus_num}.")
            raise
        except PermissionError:
            logging.error(f"Permission denied on /dev/i2c-{self.i2c_bus_num}. Add user to the 'i2c' group or run with appropriate privileges.")
            raise
        except OSError as e:
            logging.error(f"Failed to open I2C bus {self.i2c_bus_num}: {e}")
            raise

        if not self._initialize_sensor():
            self.close()
            raise RuntimeError("DHT20 initialization failed.")

    def _initialize_sensor(self):
        try:
            time.sleep(0.5)
            status = self.bus.read_byte_data(self.i2c_address, 0x71)
            if (status & 0x18) != 0x18:
                logging.error(f"DHT20 status byte 0x71 readback failed: 0x{status:02X}. Sensor not ready or not present.")
                return False
            logging.info("DHT20 initialized successfully.")
            return True
        except OSError as e:
            logging.error(f"I2C communication error during init: {e}")
            return False

    def get_temperature_and_humidity(self):
        for attempt in range(self.retry_count):
            if not self._running:
                logging.info("Shutdown requested; aborting measurement.")
                return None, None, True
            try:
                self.bus.write_i2c_block_data(self.i2c_address, 0xAC, [0x33, 0x00])
                start_time = time.time()
                while True:
                    status = self.bus.read_byte_data(self.i2c_address, 0x71)
                    if (status & 0x80) == 0:
                        break
                    if time.time() - start_time > 0.1:
                        logging.warning(f"Timeout waiting for DHT20 measurement (attempt {attempt + 1}/{self.retry_count}).")
                        break
                    time.sleep(0.005)
                if (status & 0x80) == 0:
                    data = self.bus.read_i2c_block_data(self.i2c_address, 0x71, 7)
                    raw_humidity = ((data[3] << 12) | (data[4] << 4) | (data[5] >> 4)) & 0xFFFFF
                    raw_temperature = (((data[5] & 0x0F) << 16) | (data[4] >> 4) | (data[3] << 4)) & 0xFFFFF
                    temperature = raw_temperature / 5242.88 - 50
                    humidity = raw_humidity / 1048576 * 100
                    if self._verify_crc(data):
                        return temperature, humidity, False
                    logging.warning("CRC error detected; retrying measurement.")
                else:
                    logging.warning(f"Measurement not ready (status 0x{status:02X}); retrying.")
            except OSError as e:
                logging.error(f"I2C communication error during measurement (attempt {attempt + 1}/{self.retry_count}): {e}")
            if attempt < self.retry_count - 1:
                time.sleep(self.retry_delay)
        logging.error("Failed to get valid data from DHT20 after all retries.")
        return None, None, True

    @staticmethod
    def _verify_crc(data):
        crc = 0xFF
        for byte in data[:6]:
            crc ^= byte
            for _ in range(8):
                if crc & 0x80:
                    crc = ((crc << 1) ^ 0x31) & 0xFF
                else:
                    crc = (crc << 1) & 0xFF
        return crc == 0

    def cleanup(self):
        self._running = False
        if self.bus is not None:
            try:
                self.bus.close()
            except OSError:
                pass
            self.bus = None

    def __del__(self):
        self.cleanup()


def _signal_handler(signum, frame):
    logging.info(f"Signal {signum} received; shutting down.")
    raise SystemExit(0)


if __name__ == '__main__':
    signal.signal(signal.SIGINT, _signal_handler)
    sensor = None
    try:
        sensor = DHT20(i2c_bus=1, i2c_address=0x38)
        temp, hum, err = sensor.get_temperature_and_humidity()
        if err:
            print("Failed to get valid data from DHT20.")
        else:
            print(f"Temperature: {temp:.2f} C")
            print(f"Humidity: {hum:.2f} %")
    except (FileNotFoundError, PermissionError, OSError, RuntimeError) as e:
        print(f"Initialization error: {e}")
    finally:
