import logging
import smbus2

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')
logger = logging.getLogger(__name__)


class DHT20:
    """Driver for the Aosong DHT20 I2C temperature/humidity sensor."""

    def __init__(self, bus=1, addr=0x38, timeout=0.1):
        self.bus_num = bus
        self.addr = addr
        self.timeout = timeout
        self.bus = None
        self.crc_error = False
        self._running = True

        try:
            self.bus = smbus2.SMBus(bus)
        except FileNotFoundError:
            logger.error("I2C bus /dev/i2c-%d not found. Enable I2C with 'sudo raspi-config'.", bus)
            self.bus = None
            return
        except PermissionError:
            logger.error("Permission denied on /dev/i2c-%d. Add user to 'i2c' group or run with sudo.", bus)
            self.bus = None
            return
        except OSError as e:
            logger.error("Failed to open I2C bus %d: %s", bus, e)
            self.bus = None
            return

        if self.bus is None:
            return

        # Probe the sensor by reading the status register (0x71).
        try:
            status = self.bus.read_byte_data(self.addr, 0x71)
        except OSError as e:
            logger.error("No DHT20 detected at address 0x%02X on bus %d: %s", addr, bus, e)
            self.bus.close()
            self.bus = None
            return

        logger.info("DHT20 status register 0x71 = 0x%02X", status)

    def _signal_handler(self, signum, frame):
        logger.info("Signal %d received, shutting down.", signum)
        self._running = False

    def measure(self):
        if self.bus is None:
            logger.error("I2C bus not initialized.")
            return None, None, True

        if not self._running:
            return None, None, True

        try:
            # Send measurement command: [0x33, 0x00] to register 0xAC.
            self.bus.write_i2c_block_data(self.addr, 0xAC, [0x33, 0x00])

            # Wait for measurement to complete (bit 7 of status clears).
            deadline = time.monotonic() + self.timeout
            while time.monotonic() < deadline:
                try:
                    status = self.bus.read_byte_data(self.addr, 0x71)
                except OSError as e:
                    logger.error("I2C read status error: %s", e)
                    return None, None, True
                if (status & 0x80) == 0:
                    break
                time.sleep(0.01)
            else:
                logger.error("Measurement timeout: status bit 7 did not clear within %.1f s.", self.timeout)
                return None, None, True

            # Read 7 bytes starting at register 0x71.
            try:
                data = self.bus.read_i2c_block_data(self.addr, 0x71, 7)
            except OSError as e:
                logger.error("I2C read data error: %s", e)
                return None, None, True

            # CRC-8 check (polynomial 0x31, init 0xFF).
            crc = 0xFF
            for b in data[:6]:
                crc ^= b
                for _ in range(8):
                    if crc & 0x80:
                        crc = ((crc << 1) ^ 0x31) & 0xFF
                    else:
                        crc = (crc << 1) & 0xFF
            if crc != data[6]:
                logger.error("CRC mismatch: computed 0x%02X, received 0x%02X", crc, data[6])
                self.crc_error = True
                return None, None, True

            # 20-bit humidity: data[1..3] << 8 | data[0]
            humidity_raw = ((data[1] << 12) | (data[2] << 4) | (data[0] >> 4)) & 0xFFFFF
            # 20-bit temperature: data[3..5] << 8 | data[2] >> 4
            temperature_raw = (((data[3] << 16) | (data[4] << 8) | (data[5] >> 4)) & 0xFFFFF)

            temperature = float(temperature_raw) / 5242.88 - 50.0
            humidity = float(humidity_raw) / 0x100000 * 100.0

            return temperature, humidity, self.crc_error

        except Exception as e:
            logger.error("Unexpected error during measurement: %s", e)
            return None, None, True

    def close(self):
        if self.bus is not None:
            try:
                self.bus.close()
            except Exception as e:
                logger.error("Error closing I2C bus: %s", e)
            finally:
                self.bus = None


if __name__ == "__main__":
    sensor = DHT20(bus=1, addr=0x38, timeout=0.1)
    if sensor.bus is None:
        logger.error("Sensor initialization failed. Exiting.")
        raise SystemExit(1)

    signal.signal(signal.SIGINT, sensor._signal_handler)
    signal.signal(signal.SIGTERM, sensor._signal_handler)

    try:
        temp, hum, err = sensor.measure()
        if err:
            logger.error("Measurement failed: %s", err)
        else:
            logger.info("Temperature: %.2f °C", temp)
            logger.info("Humidity: %.2f %%", hum)
    finally:
        sensor.close()

