import time
import board
import busio
import adafruit_tca9548a
import adafruit_bme280
import adafruit_tsl2591

# Constants
TCA9548A_ADDRESS = 0x70
BME280_CHANNEL = 0
TSL2591_CHANNEL = 1
READ_INTERVAL_SECONDS = 2


def initialize_i2c():
    """Initializes the I2C bus on board.SCL (GPIO3) and board.SDA (GPIO2)."""
    try:
        i2c_bus = busio.I2C(board.SCL, board.SDA)
        return i2c_bus
    except Exception as e:
        print(f"Error initializing I2C bus: {e}")
        return None


def initialize_multiplexer(i2c_bus):
    """Initializes the TCA9548A I2C multiplexer."""
    try:
        multiplexer = adafruit_tca9548a.TCA9548A(i2c_bus, address=TCA9548A_ADDRESS)
        return multiplexer
    except Exception as e:
        print(f"Error initializing TCA9548A multiplexer: {e}")
        return None


def initialize_bme280_sensor(multiplexer):
    """Initializes the BME280 sensor on the specified multiplexer channel."""
    try:
        bme280_sensor = adafruit_bme280.Adafruit_BME280_I2C(multiplexer, address=0x76)
        return bme280_sensor
    except Exception as e:
        print(f"Error initializing BME280 sensor: {e}")
        return None


def initialize_tsl2591_sensor(multiplexer):
    """Initializes the TSL2591 sensor on the specified multiplexer channel."""
    try:
        tsl2591_sensor = adafruit_tsl2591.TSL2591(multiplexer, address=0x29)
        return tsl2591_sensor
    except Exception as e:
        print(f"Error initializing TSL2591 sensor: {e}")
        return None


def read_sensor_data(bme280_sensor, tsl2591_sensor):
    """Reads temperature, humidity, and light intensity from the sensors."""
    temperature = None
    humidity = None
    light_intensity = None

    if bme280_sensor:
        try:
            temperature = bme280_sensor.temperature
            humidity = bme280_sensor.humidity
        except Exception as e:
            print(f"Error reading BME280 data: {e}")

    if tsl2591_sensor:
        try:
            light_intensity = tsl2591_sensor.lux
        except Exception as e:
            print(f"Error reading TSL2591 data: {e}")

    return temperature, humidity, light_intensity


def display_sensor_data(temperature, humidity, light_intensity):
    """Displays the sensor data in a user-friendly format."""
    print("-" * 40)
    print(f"Temperature: {temperature:.2f} C" if temperature is not None else "Temperature: N/A")
    print(f"Humidity: {humidity:.2f} %" if humidity is not None else "Humidity: N/A")
    print(f"Light Intensity: {light_intensity:.2f} lux" if light_intensity is not None else "Light Intensity: N/A")
    print("-" * 40)


def main():
    """Main function to read and display sensor data every 2 seconds."""
    i2c_bus = initialize_i2c()
    if i2c_bus is None:
        return

    multiplexer = initialize_multiplexer(i2c_bus)
    if multiplexer is None:
        return

    bme280_sensor = initialize_bme280_sensor(multiplexer)
    tsl2591_sensor = initialize_tsl2591_sensor(multiplexer)

    if bme280_sensor is None and tsl2591_sensor is None:
        print("No sensors detected. Check I2C connections and addresses.")
        return

    try:
        while True:
            temperature, humidity, light_intensity = read_sensor_data(bme280_sensor, tsl2591_sensor)
            display_sensor_data(temperature, humidity, light_intensity)
            time.sleep(READ_INTERVAL_SECONDS)
    except KeyboardInterrupt:
        print("\nExiting program.")
    finally:
        # Release resources on exit
        if i2c_bus:
            i2c_bus.deinit()


if __name__ == "__main__":
    main()

