import time
import signal
import sys
from gpiozero import PWMOutputDevice

FAN_PIN = 18
PWM_FREQ = 50
TEMP_MIN = 40.0
TEMP_MAX = 50.0
SAMPLE_INTERVAL = 1.0

_running = True

def _handle_signal(signum, frame):
    global _running
    _running = False

def read_cpu_temp():
    try:
        with open('/sys/class/thermal/thermal_zone0/temp', 'r') as f:
            return float(f.read().strip()) / 1000.0
    except (OSError, ValueError) as e:
        print(f"Error reading CPU temperature: {e}", file=sys.stderr)
        return None

def compute_duty(temp):
    if temp <= TEMP_MIN:
        return 0.0
    if temp >= TEMP_MAX:
        return 100.0
    return (temp - TEMP_MIN) * 100.0 / (TEMP_MAX - TEMP_MIN)

def main():
    global _running
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    try:
        fan = PWMOutputDevice(FAN_PIN, frequency=PWM_FREQ, initial_value=0.0)
    except Exception as e:
        print(f"Failed to initialize PWM on GPIO{FAN_PIN}: {e}", file=sys.stderr)
        sys.exit(1)

    try:
        while _running:
            temp = read_cpu_temp()
            if temp is not None:
                duty = compute_duty(temp)
                fan.value = duty / 100.0
                print(f"CPU: {temp:.1f}C  Fan: {duty:.1f}%")
            time.sleep(SAMPLE_INTERVAL)
    finally:
        fan.value = 0.0
        fan.close()
        print("Fan stopped and GPIO released.")

if __name__ == "__main__":
    main()

