import time
import logging
import signal
import sys
from smbus2 import SMBus

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')
logger = logging.getLogger(__name__)


class DHT20:
    DHT20_I2C_ADDR = 0x38
    DHT20_STATUS_REG = 0x71
    DHT20_MEASURE_REG = 0xAC
    DHT20_DATA_REG = 0x71
    MEASURE_CMD = [0x33, 0x00]
    MEASURE_TIMEOUT = 0.8
    MIN_MEASURE_INTERVAL = 2.0
    MAX_MEASURE_ATTEMPTS = 5
    MAX_POLL_ATTEMPTS = 10
    POLL_INTERVAL = 0.08
    RETRY_DELAY = 0.01
    POWER_ON_DELAY = 0.5

    def __init__(self, i2c_bus=1):
        self._i2c_bus_num = i2c_bus
        self._bus = None
        self._last_temperature = None
        self._last_humidity = None
        self._last_error = None
        self._running = True

    def __enter__(self):
        self.begin()
        return self

    def __exit__(self, exc_type, exc_val, exc_tb):
        self.close()

    def begin(self):
        try:
            self._bus = SMBus(self._i2c_bus_num)
        except OSError as e:
            logger.error(f"Failed to open I2C bus {self._i2c_bus_num}: {e}")
            return False

        time.sleep(self.POWER_ON_DELAY)

        for attempt in range(self.MAX_MEASURE_ATTEMPTS):
            try:
                status = self._read_register(self.DHT20_STATUS_REG, 1)[0]
                if (status & 0x18) != 0x18:
                    logger.warning(f"Sensor not ready (status 0x{status:02X}), attempt {attempt + 1}")
                    time.sleep(self.RETRY_DELAY)
                    continue
                break
            except OSError as e:
                logger.error(f"Error reading status register: {e}")
                self.close()
                return False

        if attempt >= self.MAX_MEASURE_ATTEMPTS:
            logger.error("Failed to initialize DHT20 (sensor not ready).")
            self.close()
            return False

        logger.info("DHT20 initialized successfully.")
        return True

    def close(self):
        if self._bus is not None:
            try:
                self._bus.close()
            except OSError:
                pass
            self._bus = None

    def get_temperature_and_humidity(self):
        if self._last_error is not None:
            raise self._last_error

        if self._last_temperature is not None and self._last_humidity is not None:
            if time.time() - self._last_measure_time < self.MIN_MEASURE_INTERVAL:
                logger.debug("Using cached result (within minimum interval).")
                return self._last_temperature, self._last_humidity, False

        for attempt in range(self.MAX_MEASURE_ATTEMPTS):
            try:
                if not self._measure_once():
                    time.sleep(self.RETRY_DELAY)
                    continue
                temperature, humidity, error = self._process_data()
                if error:
                    raise OSError(f"DHT20 CRC error: {error}")
                self._last_temperature = temperature
                self._last_humidity = humidity
                self._last_measure_time = time.time()
                return temperature, humidity, False
            except OSError as e:
                self._last_error = e
                logger.warning(f"I2C error during measurement (attempt {attempt + 1}): {e}")
                time.sleep(self.RETRY_DELAY)

        logger.error("Failed to get temperature and humidity after multiple attempts.")
        return self._last_temperature, self._last_humidity, True

    def _measure_once(self):
        try:
            self._write_register(self.DHT20_MEASURE_REG, self.MEASURE_CMD)
        except OSError as e:
            logger.error(f"Failed to trigger measurement: {e}")
            return False

        for attempt in range(self.MAX_POLL_ATTEMPTS):
            try:
                status = self._read_register(self.DHT20_STATUS_REG, 1)[0]
                if (status & 0x80) == 0:
                    return True
                time.sleep(self.POLL_INTERVAL)
            except OSError as e:
                logger.error(f"Failed to poll measurement status (attempt {attempt + 1}): {e}")
                time.sleep(self.POLL_INTERVAL)

        logger.error("Measurement timed out.")
        return False

    def _read_register(self, register, length):
        return self._bus.read_i2c_block_data(self.DHT20_I2C_ADDR, register, length)

    def _write_register(self, register, data):
        self._bus.write_i2c_block_data(self.DHT20_I2C_ADDR, register, data)

    def _process_data(self):
        try:
            data = self._read_register(self.DHT20_DATA_REG, 7)
        except OSError as e:
            logger.error(f"Failed to read sensor data: {e}")
            return None, None, True

        if self._calculate_crc8(data) != data[6]:
            logger.warning("CRC mismatch, retrying data read.")
            return None, None, True

        humidity_raw = ((data[1] << 12) | (data[2] << 4) | ((data[3] & 0xF0) >> 4))
        humidity = (humidity_raw / 0x100000) * 100.0

        temperature_raw = (((data[3] & 0x0F) << 16) | (data[4] << 8) | data[5])
        temperature = (temperature_raw / 0x10000) * 200.0 - 50.0

        return temperature, humidity, False

    @staticmethod
    def _calculate_crc8(data):
        crc = 0xFF
        for byte in data[:-1]:
            crc ^= byte
            for _ in range(8):
                if crc & 0x80:
                    crc = ((crc << 1) ^ 0x31) & 0xFF
                else:
                    crc = (crc << 1) & 0xFF
        return crc

    @property
    def _last_measure_time(self):
        return self._last_measure_time or 0.0


def _signal_handler(signum, frame):
    logger.info(f"Signal {signum} received, shutting down.")
    sys.exit(0)


if __name__ == '__main__':
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    sensor = DHT20(i2c_bus=1)
    if not sensor.begin():
        logger.error("Failed to initialize DHT20. Exiting.")
        sys.exit(0)

    try:
        while True:
            temp, hum, err = sensor.get_temperature_and_humidity()
            if err:
                logger.error("Sensor read failed.")
            else:
                logger.info(f"Temperature: {temp:.2f} C, Humidity: {hum:.2f} %")
            time.sleep(1.0)
    except KeyboardInterrupt:
        logger.info("Interrupted by user.")
    except SystemExit:
        pass
    finally:
        sensor.close()

