import time
import logging
import board
import adafruit_dht

# Configure logging to both console and file
logging.basicConfig(
    level=logging.ERROR,
    format='%(asctime)s - %(levelname)s - %(message)s',
    handlers=[
        logging.StreamHandler(),
        logging.FileHandler('wildlife_monitoring.log')
    ]
)

# Define GPIO pins for DHT22 sensors (BCM numbering)
DHT22_PINS = [board.D4, board.D17]

# Anomaly thresholds
TEMPERATURE_MIN = 5
TEMPERATURE_MAX = 35
HUMIDITY_MAX = 90

# Retry settings
MAX_RETRIES = 3
RETRY_DELAY = 2  # seconds

def read_dht22(pin):
    """
    Reads temperature and humidity from a DHT22 sensor.
    Returns (temperature, humidity) or (None, None) on failure.
    """
    dht_device = None
    try:
        dht_device = adafruit_dht.DHT22(pin, use_pulseio=False)
        for attempt in range(1, MAX_RETRIES + 1):
            try:
                temperature = dht_device.temperature
                humidity = dht_device.humidity
                if temperature is not None and humidity is not None:
                    return temperature, humidity
                else:
                    logging.error(f"DHT22 on pin {pin}: Incomplete data (attempt {attempt})")
            except RuntimeError as e:
                logging.error(f"DHT22 on pin {pin}: Read error (attempt {attempt}): {e}")
            if attempt < MAX_RETRIES:
                time.sleep(RETRY_DELAY)
        logging.error(f"DHT22 on pin {pin}: Failed after {MAX_RETRIES} attempts")
        return None, None
    except Exception as e:
        logging.error(f"DHT22 on pin {pin}: Initialization error: {e}")
        return None, None
    finally:
        if dht_device:
            try:
                dht_device.exit()
            except Exception:
                pass

def check_anomalies(temperature, humidity, pin):
    """
    Checks for temperature and humidity anomalies and logs them if found.
    """
    if temperature is not None and humidity is not None:
        if temperature < TEMPERATURE_MIN or temperature > TEMPERATURE_MAX:
            logging.error(f"Temperature anomaly: {temperature:.1f}°C (pin {pin})")
        if humidity > HUMIDITY_MAX:
            logging.error(f"Humidity anomaly: {humidity:.1f}% (pin {pin})")

def main():
    """
    Main function to read sensor data and check for anomalies.
    """
    try:
        while True:
            for pin in DHT22_PINS:
                temperature, humidity = read_dht22(pin)
                check_anomalies(temperature, humidity, pin)
            time.sleep(60)
    except KeyboardInterrupt:
        print("Program terminated by user.")
    except Exception as e:
        logging.error(f"Unexpected error: {e}")
    finally:
        # Clean up any remaining resources
        for pin in DHT22_PINS:
            dht_device = None
            try:
                dht_device = adafruit_dht.DHT22(pin, use_pulseio=False)
                dht_device.exit()
            except Exception:
                pass

if __name__ == "__main__":
    main()

