import time
import datetime
import csv
import os
import fcntl
import random
import logging
import signal
import sys
import traceback
from typing import Optional, Tuple

import adafruit_dht
import board

# Configuration
DHT22_PINS = [board.D17, board.D27]
HIGH_HUMIDITY_THRESHOLD = 75.0
LOW_HUMIDITY_THRESHOLD = 45.0
ALERT_DEBOUNCE_MINUTES = 30
MAX_RETRIES = 3
RETRY_DELAY_SECONDS = 2
CLOUD_SUCCESS_RATE = 0.8
DATA_LOGGING_INTERVAL = 60
CSV_HEADER = ['Timestamp', 'Sensor1_Temp_C', 'Sensor1_Humidity_Pct', 'Sensor2_Temp_C', 'Sensor2_Humidity_Pct']

# Logging setup
logging.basicConfig(
    filename='error.log',
    level=logging.ERROR,
    format='%(asctime)s - %(levelname)s - %(message)s',
    datefmt='%Y-%m-%d %H:%M:%S'
)

# Global state
running = True
last_alert_time: dict = {pin: 0.0 for pin in DHT22_PINS}
alert_count: dict = {pin: 0 for pin in DHT22_PINS}
alert_type: dict = {pin: None for pin in DHT22_PINS}
sensor_data: dict = {pin: None for pin in DHT22_PINS}
sensor_failures: dict = {pin: 0 for pin in DHT22_PINS}

# Initialize DHT22 sensors
sensors: list = []
for pin in DHT22_PINS:
    try:
        sensor = adafruit_dht.DHT22(pin, use_pulseio=False)
        sensors.append(sensor)
        logging.info(f"Initialized DHT22 on pin {pin}")
    except Exception as e:
        logging.error(f"Failed to initialize DHT22 on pin {pin}: {e}")
        traceback.print_exc()
        sensors.append(None)

def read_dht22(sensor, pin) -> Optional[Tuple[float, float]]:
    """Read temperature and humidity from a DHT22 sensor with retries."""
    for attempt in range(MAX_RETRIES):
        try:
            temperature = sensor.temperature
            humidity = sensor.humidity
            if temperature is not None and humidity is not None:
                if 0.0 <= humidity <= 100.0 and 0.0 <= temperature <= 35.0:
                    return temperature, humidity
                else:
                    logging.warning(f"Invalid reading from pin {pin}: temp={temperature}, humidity={humidity}")
            else:
                logging.warning(f"Sensor {pin} returned None on attempt {attempt + 1}")
        except RuntimeError as e:
            logging.warning(f"RuntimeError reading pin {pin} on attempt {attempt + 1}: {e}")
        except Exception as e:
            logging.error(f"Unexpected error reading pin {pin} on attempt {attempt + 1}: {e}")
            traceback.print_exc()
        if attempt < MAX_RETRIES - 1:
            time.sleep(RETRY_DELAY_SECONDS)
    return None

def log_data_to_csv(timestamp: str, s1_temp: float, s1_hum: float, s2_temp: float, s2_hum: float) -> None:
    """Append a row to the daily CSV file with file locking."""
    today = datetime.date.today().strftime("%Y-%m-%d")
    filename = f"retail_data_{today}.csv"
    file_exists = os.path.isfile(filename)
    try:
        with open(filename, 'a', newline='') as csvfile:
            fcntl.flock(csvfile.fileno(), fcntl.LOCK_EX)
            try:
                writer = csv.writer(csvfile)
                if not file_exists:
                    writer.writerow(CSV_HEADER)
                writer.writerow([timestamp, f"{s1_temp:.2f}", f"{s1_hum:.2f}", f"{s2_temp:.2f}", f"{s2_hum:.2f}"])
            finally:
                fcntl.flock(csvfile.fileno(), fcntl.LOCK_UN)
    except Exception as e:
        logging.error(f"Error writing to CSV file {filename}: {e}")
        traceback.print_exc()

def trigger_alert(pin, alert_type_str: str) -> None:
    """Log an alert to retail_alerts.log and update global state."""
    global last_alert_time, alert_count, alert_type
    timestamp = datetime.datetime.now().strftime("%Y-%m-%d %H:%M:%S")
    message = f"{timestamp} - Alert: {alert_type_str} on pin {pin}"
    logging.info(message)
    print(message)
    alert_type[pin] = alert_type_str
    last_alert_time[pin] = time.time()
    alert_count[pin] += 1

def check_alerts() -> None:
    """Check humidity trends and trigger alerts with debouncing."""
    now = time.time()
    for pin, sensor in enumerate(sensors):
        if sensor is None:
            continue
        if sensor_failures[pin] >= MAX_RETRIES:
            logging.error(f"Sensor {pin} failed after {MAX_RETRIES} retries, skipping")
            continue
        if sensor_data[pin] is None:
            continue
        humidity = sensor_data[pin][1]
        if humidity > HIGH_HUMIDITY_THRESHOLD:
            if alert_type[pin] != "High Humidity Alert" or (now - last_alert_time[pin] > ALERT_DEBOUNCE_MINUTES * 60):
                if alert_count[pin] >= 3:
                    trigger_alert(pin, "High Humidity Alert")
                else:
                    alert_type[pin] = "High Humidity Alert"
        elif humidity < LOW_HUMIDITY_THRESHOLD:
            if alert_type[pin] != "Low Humidity Alert" or (now - last_alert_time[pin] > ALERT_DEBOUNCE_MINUTES * 60):
                if alert_count[pin] >= 3:
                    trigger_alert(pin, "Low Humidity Alert")
                else:
                    alert_type[pin] = "Low Humidity Alert"

def simulate_cloud_push(timestamp: str, s1_temp: float, s1_hum: float, s2_temp: float, s2_hum: float) -> None:
    """Simulate sending data to a cloud service."""
    success = random.random() < CLOUD_SUCCESS_RATE
    if success:
        print(f"Cloud push successful: {timestamp}, S1={s1_temp:.2f}/{s1_hum:.2f}, S2={s2_temp:.2f}/{s2_hum:.2f}")
    else:
        logging.warning("Simulated cloud push failed")

def cleanup() -> None:
    """Release sensor resources."""
    for sensor in sensors:
        if sensor is not None:
            try:
                sensor.exit()
            except Exception:
                pass

def signal_handler(sig, frame) -> None:
    """Handle SIGINT/SIGTERM for clean shutdown."""
    global running
    running = False

def main() -> None:
    global running, sensor_data, sensor_failures
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)
    try:
        while running:
            timestamp = datetime.datetime.now().strftime("%Y-%m-%d %H:%M:%S")
            s1_data = read_dht22(sensors[0], DHT22_PINS[0])
            s2_data = read_dht22(sensors[1], DHT22_PINS[1])
            if s1_data is not None and s2_data is not None:
                sensor_data[DHT22_PINS[0]] = s1_data
                sensor_data[DHT22_PINS[1]] = s2_data
                sensor_failures[DHT22_PINS[0]] = 0
                sensor_failures[DHT22_PINS[1]] = 0
                log_data_to_csv(timestamp, s1_data[0], s1_data[1], s2_data[0], s2_data[1])
                simulate_cloud_push(timestamp, s1_data[0], s1_data[1], s2_data[0], s2_data[1])
                check_alerts()
            else:
                sensor_failures[DHT22_PINS[0]] += 1
                sensor_failures[DHT22_PINS[1]] += 1
                logging.warning("Failed to read from one or both sensors")
            for _ in range(DATA_LOGGING_INTERVAL):
                if not running:
                    break
                time.sleep(1)
    except Exception as e:
        logging.error(f"Unexpected error in main loop: {e}")
        traceback.print_exc()
    finally:
        cleanup()

if __name__ == "__main__":
    main()

