import signal
import sys
import time
import logging
from gpiozero import PWMOutputDevice

logging.basicConfig(level=logging.INFO, format="%(asctime)s [%(levelname)s] %(message)s")

FAN_PIN = 14
PWM_FREQ = 100
CHECK_INTERVAL = 5

TEMP_STEPS = [
    (70, 100),
    (60, 85),
    (50, 70),
    (40, 50),
    (32, 25),
    (25, 15),
]

running = True


def handle_signal(signum, frame):
    global running
    logging.info("Received signal %s, shutting down...", signum)
    running = False


def read_cpu_temp():
    try:
        out = subprocess.check_output(
            ["vcgencmd", "measure_temp"],
            text=True,
            timeout=5,
        ).strip()
        return float(out.split("=")[1].split("'")[0])
    except (subprocess.CalledProcessError, IndexError, ValueError, subprocess.TimeoutExpired, FileNotFoundError):
        try:
            with open("/sys/class/thermal/thermal_zone0/temp", "r") as f:
                return float(f.read().strip()) / 1000.0
        except (IOError, ValueError):
            logging.error("Failed to read CPU temperature from any source.")
            return None


def target_speed(temp):
    for threshold, speed in TEMP_STEPS:
        if temp > threshold:
            return speed
    return 0


def main():
    global running
    signal.signal(signal.SIGINT, handle_signal)
    signal.signal(signal.SIGTERM, handle_signal)

    try:
        fan = PWMOutputDevice(FAN_PIN, frequency=PWM_FREQ, initial_value=0)
    except Exception as e:
        logging.error("Failed to initialize PWM on GPIO%d: %s", FAN_PIN, e)
        sys.exit(1)

    logging.info("Fan control started on GPIO%d @ %d Hz.", FAN_PIN, PWM_FREQ)

    try:
        while running:
            temp = read_cpu_temp()
            if temp is None:
                logging.warning("Skipping fan update due to temperature read failure.")
            else:
                speed = target_speed(temp)
                fan.value = speed / 100.0
                logging.info("CPU temp: %.1f°C -> Fan speed: %d%%", temp, speed)
            time.sleep(CHECK_INTERVAL)
    except Exception as e:
        logging.error("Unexpected error in control loop: %s", e)
    finally:
        try:
            fan.value = 0
            fan.close()
        except Exception:
            pass
        logging.info("GPIO cleanup complete. Exiting.")


if __name__ == "__main__":
    import subprocess
    main()

