import smbus2
import time
import signal
import sys
import logging

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

I2C_BUS = 1
I2C_ADDR = 0x38
MEASURE_CMD = [0xAC, 0x33, 0x00]
STATUS_REG = 0x00
CRC_REG = 0x06
RESET_CMD = 0xBA
INIT_CMD = [0xBE, 0x08, 0x00]

running = True

def signal_handler(sig, frame):
    global running
    running = False

def crc8(data: bytes, init: int = 0xFF, poly: int = 0x31) -> int:
    crc = init
    for byte in data:
        crc ^= byte
        for _ in range(8):
            if crc & 0x80:
                crc = ((crc << 1) ^ poly) & 0xFF
            else:
                crc = (crc << 1) & 0xFF
    return crc

def read_raw(bus: smbus2.SMBus) -> bytes:
    bus.write_i2c_block_data(I2C_ADDR, MEASURE_CMD[0], MEASURE_CMD[1:])
    time.sleep(0.08)
    data = bus.read_i2c_block_data(I2C_ADDR, STATUS_REG, 7)
    return bytes(data)

def read_sensor(bus: smbus2.SMBus):
    raw = read_raw(bus)
    if len(raw) != 7:
        raise IOError(f"Unexpected read length: {len(raw)}")
    status = raw[0]
    if status & 0x80:
        raise IOError(f"Sensor busy (status 0x{status:02X})")
    if not (status & 0x08):
        raise IOError(f"Sensor not calibrated (status 0x{status:02X})")
    if crc8(raw[:6]) != raw[6]:
        raise IOError("CRC mismatch")
    raw_temp = ((raw[3] << 12) | (raw[4] << 4) | (raw[5] >> 4)) & 0xFFFFF
    raw_humid = (((raw[5] & 0x0F) << 16) | (raw[3] >> 4) | (raw[4] << 4)) & 0xFFFFF
    temp_c = (raw_temp / 0x100000) * 200.0 - 50.0
    humid = (raw_humid / 0x100000) * 100.0
    return temp_c, humid

def init_sensor(bus: smbus2.SMBus):
    try:
        bus.write_i2c_block_data(I2C_ADDR, RESET_CMD, [])
        time.sleep(0.02)
        status = bus.read_byte_data(I2C_ADDR, STATUS_REG)
        if not (status & 0x08):
            bus.write_i2c_block_data(I2C_ADDR, INIT_CMD[0], INIT_CMD[1:])
            time.sleep(0.01)
    except IOError as e:
        logging.error(f"Sensor initialisation failed: {e}")
        raise

def main():
    global running
    signal.signal(signal.SIGINT, signal_handler)
    try:
        bus = smbus2.SMBus(I2C_BUS)
    except FileNotFoundError:
        logging.error(f"I2C bus {I2C_BUS} not found. Enable I2C with raspi-config.")
        sys.exit(1)
    except PermissionError:
        logging.error(f"Permission denied on I2C bus {I2C_BUS}. Run as root or add user to i2c group.")
        sys.exit(1)
    try:
        init_sensor(bus)
        while running:
            try:
                temp_c, humid = read_sensor(bus)
                temp_f = temp_c * 9.0 / 5.0 + 32.0
                ts = time.strftime("%Y-%m-%d %H:%M:%S")
                print(f"Timestamp: {ts}")
                print(f"Temperature: {temp_c:.2f}°C / {temp_f:.2f}°F")
                print(f"Humidity: {humid:.2f}%")
                print("-" * 40)
            except IOError as e:
                logging.error(f"Sensor read error: {e}")
            except Exception as e:
                logging.error(f"Unexpected error: {e}")
            for _ in range(5):
                if not running:
                    break
                time.sleep(1)
    finally:
        bus.close()
        logging.info("I2C bus closed. Exiting.")

if __name__ == "__main__":
    main()

