import time
import board
import adafruit_dht

# DHT11 data pin connected to GPIO4 (physical pin 7) on the Raspberry Pi.
# The adafruit_circuitpython_dht library uses board.D4 for GPIO4.
DHT_PIN = board.D4

# Initialize the DHT11 sensor.
# use_pulseio=False is recommended on Raspberry Pi to avoid pulseio dependency issues.
dht_device = adafruit_dht.DHT11(DHT_PIN, use_pulseio=False)

def read_temperature():
    """Read temperature from the DHT11 and return it in Celsius, or None on error."""
    try:
        temperature = dht_device.temperature
        if temperature is None:
            print("Error: DHT11 returned None for temperature.")
            return None
        return temperature
    except RuntimeError as error:
        # DHT11 checksum or timing errors are common; log and continue.
        print(f"Error reading DHT11: {error}")
        return None
    except Exception as error:
        # Catch-all for unexpected I/O or library errors.
        print(f"Unexpected error reading DHT11: {error}")
        return None

def main():
    """Main loop: read temperature every 5 seconds and print with timestamp."""
    try:
        while True:
            temperature = read_temperature()
            if temperature is not None:
                timestamp = time.strftime("%Y-%m-%d %H:%M:%S")
                print(f"Temperature: {temperature:.1f}°C at {timestamp}")
            time.sleep(5)
    except KeyboardInterrupt:
        print("\nExiting program.")
    except Exception as error:
        print(f"Fatal error in main loop: {error}")

if __name__ == "__main__":
    main()

