import subprocess
import time
import signal
import sys
import logging
from gpiozero import PWMOutputDevice

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

FAN_PIN = 14
PWM_FREQ = 100
INTERVAL = 5
TEMP_THRESHOLDS = [
    (70, 100),
    (60, 85),
    (50, 70),
    (40, 50),
    (32, 25),
    (25, 15),
]

running = True
fan = None

def signal_handler(signum, frame):
    global running
    running = False

def get_cpu_temp():
    try:
        result = subprocess.run(['vcgencmd', 'measure_temp'], capture_output=True, text=True, check=True, timeout=5)
        return float(result.stdout.split('=')[1].split("'")[0])
    except (subprocess.CalledProcessError, IndexError, ValueError, subprocess.TimeoutExpired, FileNotFoundError) as e:
        logging.error(f"Failed to get CPU temperature: {e}")
        return None

def get_fan_speed(temp):
    for threshold, speed in TEMP_THRESHOLDS:
        if temp > threshold:
            return speed
    return 0

def main():
    global fan
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        fan = PWMOutputDevice(FAN_PIN, frequency=PWM_FREQ, initial_value=0)
    except Exception as e:
        logging.warning(f"Failed to initialise PWM on GPIO{FAN_PIN}: {e}. Running in degraded mode.")

    last_speed = 0
    try:
        while running:
            temp = get_cpu_temp()
            if temp is not None:
                speed = get_fan_speed(temp)
                last_speed = speed
                logging.info(f"CPU: {temp:.1f}°C -> Fan: {speed}%")
            else:
                logging.warning(f"Temperature unavailable, keeping last fan speed: {last_speed}%")
            time.sleep(INTERVAL)
    finally:
        if fan is not None:
            fan.close()
        logging.info("Fan control stopped.")

if __name__ == '__main__':
    main()

