import signal
import sys
import time
from gpiozero import PWMOutputDevice

FAN_PIN = 18
PWM_FREQ = 100
TEMP_THRESHOLD = 40.0
LOW_POWER_DUTY = 0.20
HIGH_POWER_DUTY = 1.0
READ_INTERVAL = 5

fan = None
running = True

def cleanup(signum=None, frame=None):
    global running
    running = False
    if fan is not None:
        try:
            fan.close()
        except Exception:
            pass
    if signum is not None:
        sys.exit(0)

def get_cpu_temp():
    try:
        with open('/sys/class/thermal/thermal_zone0/temp', 'r') as f:
            return float(f.read().strip()) / 1000.0
    except (IOError, ValueError):
        return None

def main():
    global fan
    signal.signal(signal.SIGINT, cleanup)
    signal.signal(signal.SIGTERM, cleanup)
    try:
        fan = PWMOutputDevice(FAN_PIN, frequency=PWM_FREQ, initial_value=0)
    except Exception as e:
        print(f"Failed to initialize PWM on GPIO{FAN_PIN}: {e}", file=sys.stderr)
        sys.exit(1)
    while running:
        temp = get_cpu_temp()
        if temp is None:
            print("Warning: could not read CPU temperature; skipping cycle.", file=sys.stderr)
        else:
            if temp > TEMP_THRESHOLD:
                fan.value = HIGH_POWER_DUTY
                print(f"CPU temp {temp:.1f}C -> fan 100%")
            else:
                fan.value = LOW_POWER_DUTY
                print(f"CPU temp {temp:.1f}C -> fan {LOW_POWER_DUTY*100:.0f}%")
        for _ in range(READ_INTERVAL):
            if not running:
                break
            time.sleep(1)
    cleanup()

