import serial
import time
import signal
import sys

SERIAL_PORT = '/dev/ttyUSB0'
BAUD_RATE = 9600
TIMEOUT = 1
TEMP_THRESHOLD = 30.0
HUMIDITY_THRESHOLD = 70.0

running = True

def signal_handler(signum, frame):
    global running
    running = False

def parse_sensor_data(data):
    try:
        parts = data.split(',')
        if len(parts) != 2:
            raise ValueError("Expected 2 comma-separated values")
        temperature = float(parts[0])
        humidity = float(parts[1])
        return temperature, humidity
    except ValueError as e:
        print(f"Error parsing data: {e}")
        return None, None

def check_alerts(temperature, humidity):
    if temperature > TEMP_THRESHOLD:
        print("Alert: Temperature too high!")
    if humidity > HUMIDITY_THRESHOLD:
        print("Alert: Humidity too high!")

def main():
    global running
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    ser = None
    try:
        ser = serial.Serial(SERIAL_PORT, BAUD_RATE, timeout=TIMEOUT)
        print(f"Connected to {SERIAL_PORT} at {BAUD_RATE} baud.")

        while running:
            try:
                raw = ser.readline()
                if not raw:
                    continue
                line = raw.decode('ascii', errors='replace').strip()
                if not line:
                    continue

                temperature, humidity = parse_sensor_data(line)
                if temperature is not None and humidity is not None:
                    print(f"Temperature: {temperature:.1f}°C, Humidity: {humidity:.1f}%")
                    check_alerts(temperature, humidity)

                time.sleep(1)

            except serial.SerialException as e:
                print(f"Serial communication error: {e}")
                break
            except OSError as e:
                print(f"I/O error: {e}")
                break

    except serial.SerialException as e:
        print(f"Failed to open serial port: {e}")
    except Exception as e:
        print(f"Unexpected error: {e}")
    finally:
        if ser is not None and ser.is_open:
            ser.close()
            print("Serial port closed.")
        print("Program terminated.")

if __name__ == "__main__":
    main()

