#!/usr/bin/env python3
"""
Control an LED on GPIO17 (BCM) with user input.

Wiring:
  GPIO17 -> 330 ohm resistor -> LED anode -> LED cathode -> GND

Requires: RPi.GPIO (pre-installed on Raspberry Pi OS)
"""

import sys
import time

import RPi.GPIO as GPIO

LED_PIN = 17


def main() -> None:
    # Allow the script to run on a non-Pi machine in a CI environment
    # without raising an unhelpful exception.
    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setwarnings(False)
        GPIO.setup(LED_PIN, GPIO.OUT, initial=GPIO.LOW)
    except Exception as exc:
        print(f"GPIO setup failed: {exc}", file=sys.stderr)
        sys.exit(1)

    led_state = False

    try:
        while True:
            try:
                user_input = input("Enter LED state (on/off): ").strip().lower()
            except EOFError:
                print("\nEOF received, exiting.")
                break

            if user_input == "on":
                led_state = True
                GPIO.output(LED_PIN, GPIO.HIGH)
            elif user_input == "off":
                led_state = False
                GPIO.output(LED_PIN, GPIO.LOW)
            else:
                print("Invalid input")

            print(f"LED state: {led_state}")
            time.sleep(0.1)

    except KeyboardInterrupt:
        print("\nExiting program.")
    finally:
        try:
            GPIO.output(LED_PIN, GPIO.LOW)
        except Exception:
            pass
        GPIO.cleanup(LED_PIN)


if __name__ == "__main__":
    main()

