        sys.exit(1)
    except Exception as e:
        print(f"An error occurred: {e}")
        sys.exit(1)
    finally:
        if sensor is not None:
            try:
                sensor.close()
            except Exception:
                pass
        print("\nGPIO cleanup complete. Exiting.")

if __name__ == "__main__":
    main()

