import signal
import sys
import time
from gpiozero import DigitalInputDevice
from gpiozero.exc import GPIOZeroError, DeviceClosed

MONITORED_PINS = [17, 27, 22]
POLL_INTERVAL = 1.0

_running = True

def _handle_signal(signum, frame):
    global _running
    _running = False

def main():
    global _running
    _running = True

    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    sensors = []
    try:
        for pin in MONITORED_PINS:
            try:
                sensor = DigitalInputDevice(pin, pull_up=True, bounce_time=None)
                sensors.append(sensor)
            except GPIOZeroError as e:
                print(f"Error: failed to initialize GPIO{pin}: {e}", file=sys.stderr)
                for s in sensors:
                    s.close()
                return 1
    except Exception as e:
        print(f"Unexpected error during GPIO init: {e}", file=sys.stderr)
        for s in sensors:
            s.close()
        return 1

    print(f"Monitoring GPIO pins: {MONITORED_PINS} (poll every {POLL_INTERVAL}s)")
    print("Press Ctrl+C to exit.")

    try:
        while _running:
            for idx, sensor in enumerate(sensors):
                try:
                    if sensor.is_active:
                        print(f"Response for sensor {idx + 1}")
                except DeviceClosed:
                    print(f"Warning: sensor {idx + 1} device closed unexpectedly.", file=sys.stderr)
                except Exception as e:
                    print(f"Warning: error reading sensor {idx + 1}: {e}", file=sys.stderr)
            time.sleep(POLL_INTERVAL)
    except Exception as e:
        print(f"Runtime error: {e}", file=sys.stderr)
    finally:
        for sensor in sensors:
            try:
                sensor.close()
            except Exception:
                pass
        print("GPIO cleanup complete.")

    return 0

if __name__ == "__main__":
    sys.exit(main())

