import sys
import signal
import threading
import time
import RPi.GPIO as GPIO
import DOG

# Constants
DEFAULT_LOG_FILE = "data.log"
POLL_INTERVAL = 0.1  # seconds

# Global state
server_running = False
log_file_path = DEFAULT_LOG_FILE
receive_thread = None
lock = threading.Lock()

# Help messages
help_messages = {
    "help": "Call 'help <command>' for details.\nCommands: display, help, send, start, stop, write, exit",
    "start": "Starts listening and saves data to a file. Usage: start <filename>",
    "stop": "Stops the server and stops listening.",
    "display": "Displays the data received so far. Usage: display",
    "send": "Sends data using DOG.send(). Usage: send <data>",
    "write": "Writes data directly to the log file. Usage: write <data>",
    "exit": "Exits the server.",
}

# GPIO setup
GPIO.setmode(GPIO.BCM)

def signal_handler(sig, frame):
    """Handles SIGINT and SIGTERM for clean shutdown."""
    print("\nSignal received, stopping server...")
    stop_server()
    GPIO.cleanup()
    sys.exit(0)

def receive_data():
    """Continuously receives data and writes it to the log file."""
    global server_running, log_file_path
    while server_running:
        try:
            data = DOG.receive()
            if data:
                with lock:
                    try:
                        with open(log_file_path, "a") as f:
                            f.write(data + "\n")
                    except IOError as e:
                        print(f"Error writing to file: {e}")
        except Exception as e:
            print(f"Error receiving data: {e}")
            server_running = False
            break
        time.sleep(POLL_INTERVAL)

def start_server(filename):
    """Starts the server and begins listening for data."""
    global server_running, log_file_path, receive_thread
    if server_running:
        print("Server is already running.")
        return

    log_file_path = filename
    try:
        with open(log_file_path, "w") as f:
            f.write("")
    except IOError as e:
        print(f"Error creating file: {e}")
        return

    server_running = True
    receive_thread = threading.Thread(target=receive_data, daemon=True)
    receive_thread.start()
    print(f"Server started. Logging to: {log_file_path}")

def stop_server():
    """Stops the server and stops listening for data."""
    global server_running, receive_thread
    if not server_running and receive_thread is None:
        return
    server_running = False
    if receive_thread is not None and receive_thread.is_alive():
        receive_thread.join(timeout=1.0)
    print("Server stopped.")

def display_data():
    """Displays the data received so far."""
    global server_running, log_file_path
    if not server_running:
        print("Server is not running. Start the server first.")
        return
    try:
        with open(log_file_path, "r") as f:
            print(f.read())
    except IOError as e:
        print(f"Error reading file: {e}")

def send_data(data):
    """Sends data using DOG.send()."""
    if not server_running:
        print("Server is not running. Start the server first.")
        return
    try:
        DOG.send(data)
        print(f"Sent: {data}")
    except Exception as e:
        print(f"Error sending data: {e}")

def write_data(data):
    """Writes data directly to the log file."""
    global server_running, log_file_path
    if not server_running:
        print("Server is not running. Start the server first.")
        return
    try:
        with open(log_file_path, "a") as f:
            f.write(data + "\n")
        print(f"Wrote: {data}")
    except IOError as e:
        print(f"Error writing to file: {e}")

def process_command(command):
    """Processes user commands."""
    parts = command.split()
    if not parts:
        return

    cmd = parts[0].lower()
    args = parts[1:]

    if cmd == "help":
        if len(args) == 1 and args[0] in help_messages:
            print(help_messages[args[0]])
        else:
            print(help_messages["help"])
    elif cmd == "start":
        if len(args) == 1:
            start_server(args[0])
        else:
            print(help_messages["start"])
    elif cmd == "stop":
        stop_server()
    elif cmd == "display":
        display_data()
    elif cmd == "send":
        if len(args) == 1:
            send_data(args[0])
        else:
            print(help_messages["send"])
    elif cmd == "write":
        if len(args) == 1:
            write_data(args[0])
        else:
            print(help_messages["write"])
    elif cmd == "exit":
        stop_server()
        GPIO.cleanup()
        sys.exit(0)
    else:
        print("Invalid command. Type 'help' for available commands.")

def run_server():
    """Main server loop."""
    while True:
        try:
            command = input("JAYES@ROVER53:\t")
            process_command(command)
        except EOFError:
            print("\nEOF received, exiting.")
            stop_server()
            GPIO.cleanup()
            sys.exit(0)
        except KeyboardInterrupt:
            print("\nKeyboard interrupt, exiting.")
            stop_server()
            GPIO.cleanup()
            sys.exit(0)
        except Exception as e:
            print(f"An unexpected error occurred: {e}")

if __name__ == "__main__":
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)
    try:
        run_server()
    except Exception as e:
        print(f"Fatal error: {e}")
        GPIO.cleanup()
        sys.exit(1)

