    args = parts[1:]

    if cmd == "help":
        if len(args) == 1 and args[0] in help_messages:
            print(help_messages[args[0]])
        else:
            print(help_messages["help"])
    elif cmd == "start":
        if len(args) == 1:
            start_server(args[0])
        else:
            print(help_messages["start"])
    elif cmd == "stop":
        stop_server()
    elif cmd == "display":
        display_data()
    elif cmd == "send":
        if len(args) == 1:
            send_data(args[0])
        else:
            print(help_messages["send"])
    elif cmd == "write":
        if len(args) == 1:
            write_data(args[0])
        else:
            print(help_messages["write"])
    elif cmd == "exit":
        stop_server()
        GPIO.cleanup()
        sys.exit(0)
    else:
        print("Invalid command. Type 'help' for available commands.")

def run_server():
    """Main server loop."""
    while True:
        try:
            command = input("JAYES@ROVER53:\t")
            process_command(command)
        except EOFError:
            print("\nEOF received, exiting.")
            stop_server()
            GPIO.cleanup()
            sys.exit(0)
        except KeyboardInterrupt:
            print("\nKeyboard interrupt, exiting.")
            stop_server()
            GPIO.cleanup()
            sys.exit(0)
        except Exception as e:
            print(f"An unexpected error occurred: {e}")

if __name__ == "__main__":
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)
    try:
        run_server()
    except Exception as e:
        print(f"Fatal error: {e}")
        GPIO.cleanup()
        sys.exit(1)

