import asyncio
import json
import logging
import os
import signal
import sys
import time
from pathlib import Path

import numpy as np
import psutil
import sounddevice as sd
from gpiozero import LED
from gpiozero.exc import GPIOZeroError
from tflite_runtime.interpreter import Interpreter

try:
    import aiohttp
except ImportError:
    aiohttp = None

# Configure logging
logging.basicConfig(
    filename='voice_assistant.log',
    level=logging.INFO,
    format='%(asctime)s - %(levelname)s - %(message)s'
)

# Global variables
config = {}
running = True
cpu_usage_threshold = 80.0
memory_usage_threshold = 90.0
disk_usage_threshold = 90.0
alert_led = None
interpreter = None
sentiment_scores = {'positive': 0.0, 'negative': 0.0, 'neutral': 0.0}
last_cpu_usage = 0.0
last_memory_usage = 0.0
last_disk_usage = 0.0
last_heartbeat_time = 0.0
last_config_update_time = 0.0
config_lock = asyncio.Lock()
cpu_usage_task = None
memory_usage_task = None
disk_usage_task = None
heartbeat_task = None
config_update_task = None
audio_task = None
shutdown_event = asyncio.Event()


class ConfigurationError(Exception):
    pass


class AudioError(Exception):
    pass


class SentimentAnalysisError(Exception):
    pass


class CloudCommunicationError(Exception):
    pass


def load_config(config_file='config.json'):
    global config
    try:
        with open(config_file, 'r') as f:
            config = json.load(f)
        logging.info("Configuration loaded successfully.")
    except FileNotFoundError:
        logging.error(f"Configuration file not found: {config_file}")
        raise ConfigurationError(f"Configuration file not found: {config_file}")
    except json.JSONDecodeError as e:
        logging.error(f"Invalid JSON in configuration file: {e}")
        raise ConfigurationError(f"Invalid JSON in configuration file: {e}")
    except Exception as e:
        logging.error(f"Error loading configuration: {e}")
        raise ConfigurationError(f"Error loading configuration: {e}")


def validate_config():
    required_keys = ['sampling_rate', 'audio_channels', 'keyword_spotting_model', 'sentiment_analysis_model',
                     'positive_sentiment_threshold', 'negative_sentiment_threshold', 'alert_led_pin',
                     'cloud_endpoint', 'api_key', 'api_secret', 'heartbeat_interval', 'config_update_interval']
    for key in required_keys:
        if key not in config:
            raise ConfigurationError(f"Missing required configuration key: {key}")
    if not isinstance(config['positive_sentiment_threshold'], (int, float)) or not isinstance(config['negative_sentiment_threshold'], (int, float)):
        raise ConfigurationError("Sentiment thresholds must be numbers.")
    if not isinstance(config['sampling_rate'], int) or config['sampling_rate'] <= 0:
        raise ConfigurationError("Invalid sampling rate.")
    if not isinstance(config['audio_channels'], int) or config['audio_channels'] <= 0:
        raise ConfigurationError("Invalid number of audio channels.")
    if not isinstance(config['alert_led_pin'], int):
        raise ConfigurationError("Alert LED pin must be an integer.")
    if config['alert_led_pin'] < 0 or config['alert_led_pin'] > 27:
        raise ConfigurationError("Invalid GPIO pin for LED. Must be between 0 and 27.")
    if not isinstance(config['heartbeat_interval'], int) or config['heartbeat_interval'] <= 0:
        raise ConfigurationError("Invalid heartbeat interval.")
    if not isinstance(config['config_update_interval'], int) or config['config_update_interval'] <= 0:
        raise ConfigurationError("Invalid config update interval.")


def initialize_sentiment_interpreter(model_path):
    try:
        if not Path(model_path).exists():
            raise FileNotFoundError(f"Model file not found: {model_path}")
        interpreter = Interpreter(model_path=model_path)
        interpreter.allocate_tensors()
        logging.info("Sentiment analysis interpreter initialized successfully.")
        return interpreter
    except Exception as e:
        logging.error(f"Error initializing sentiment analysis interpreter: {e}")
        raise SentimentAnalysisError(f"Error initializing sentiment analysis interpreter: {e}")


def initialize_keyword_interpreter(model_path):
    try:
        if not Path(model_path).exists():
            raise FileNotFoundError(f"Model file not found: {model_path}")
        interpreter = Interpreter(model_path=model_path)
        interpreter.allocate_tensors()
        logging.info("Keyword spotting interpreter initialized successfully.")
        return interpreter
    except Exception as e:
        logging.error(f"Error initializing keyword spotting interpreter: {e}")
        raise SentimentAnalysisError(f"Error initializing keyword spotting interpreter: {e}")


def perform_sentiment_analysis(text, interpreter):
    try:
        input_details = interpreter.get_input_details()
        output_details = interpreter.get_output_details()
        input_data = np.array([text], dtype=input_details[0]['dtype'])
        interpreter.set_tensor(input_details[0]['index'], input_data)
        interpreter.invoke()
        output_data = interpreter.get_tensor(output_details[0]['index'])
        scores = output_data[0]
        sentiment = "positive" if scores[0] > scores[1] else ("negative" if scores[1] > scores[0] else "neutral")
        return sentiment, scores
    except Exception as e:
        logging.error(f"Error performing sentiment analysis: {e}")
        raise SentimentAnalysisError(f"Error performing sentiment analysis: {e}")


def perform_keyword_spotting(audio_data, interpreter):
    try:
        input_details = interpreter.get_input_details()
        output_details = interpreter.get_output_details()
        input_data = np.array([audio_data], dtype=input_details[0]['dtype'])
        interpreter.set_tensor(input_details[0]['index'], input_data)
        interpreter.invoke()
        output_data = interpreter.get_tensor(output_details[0]['index'])
        return bool(output_data[0][0])
    except Exception as e:
        logging.error(f"Error performing keyword spotting: {e}")
        return False


def check_sentiment_thresholds(sentiment, sentiment_scores):
    if sentiment == "positive" and sentiment_scores['positive'] > config['positive_sentiment_threshold']:
        logging.warning("Positive sentiment threshold exceeded!")
        trigger_alert()
    elif sentiment == "negative" and sentiment_scores['negative'] > config['negative_sentiment_threshold']:
        logging.warning("Negative sentiment threshold exceeded!")
        trigger_alert()


def trigger_alert():
    global alert_led
    if alert_led:
        try:
            alert_led.on()
            logging.warning("Alert triggered!")
        except GPIOZeroError as e:
            logging.error(f"Error triggering alert: {e}")


def check_system_resources():
    global last_cpu_usage, last_memory_usage, last_disk_usage
    try:
        cpu_usage = psutil.cpu_percent(interval=None)
        memory = psutil.virtual_memory()
        disk_usage = psutil.disk_usage("/")
        if cpu_usage > cpu_usage_threshold:
            logging.warning(f"CPU usage high: {cpu_usage}%")
        if memory.percent > memory_usage_threshold:
            logging.warning(f"Memory usage high: {memory.percent}%")
        if disk_usage.percent > disk_usage_threshold:
            logging.warning(f"Disk usage high: {disk_usage.percent}%")
        last_cpu_usage = cpu_usage
        last_memory_usage = memory.percent
        last_disk_usage = disk_usage.percent
    except Exception as e:
        logging.error(f"Error checking system resources: {e}")


def send_heartbeat(session, cloud_endpoint, api_key, api_secret):
    if not session:
        return
    try:
        url = f"{cloud_endpoint}/api/v1/heartbeat"
        headers = {'Content-Type': 'application/json', 'X-API-Key': api_key}
        data = {'status': 'running', 'timestamp': time.time()}
        async with session.post(url, json=data, headers=headers) as response:
            if response.status != 200:
                logging.error(f"Heartbeat failed with status code: {response.status}")
            else:
                logging.info("Heartbeat sent successfully.")
    except Exception as e:
        logging.error(f"Error sending heartbeat: {e}")
        raise CloudCommunicationError(f"Error sending heartbeat: {e}")


async def check_for_config_updates(session, cloud_endpoint, api_key, api_secret):
    global config, last_config_update_time
    while not shutdown_event.is_set():
        try:
            if time.time() - last_config_update_time > config['config_update_interval']:
                url = f"{cloud_endpoint}/api/v1/config"
                headers = {'Content-Type': 'application/json', 'X-API-Key': api_key}
                async with session.get(url, headers=headers) as response:
                    if response.status == 200:
                        new_config = await response.json()
                        async with config_lock:
                            config.update(new_config)
                            last_config_update_time = time.time()
                        logging.info("Configuration updated from cloud.")
                    else:
                        logging.warning(f"Failed to update configuration from cloud. Status code: {response.status}")
        except Exception as e:
            logging.error(f"Error checking for configuration updates: {e}")
        await asyncio.sleep(config['config_update_interval'])


async def log_system_resources(session, cloud_endpoint, api_key, api_secret):
    global cpu_usage_task, memory_usage_task, disk_usage_task
    while not shutdown_event.is_set():
        try:
            check_system_resources()
            if cpu_usage_task and not cpu_usage_task.done():
                cpu_usage_task.cancel()
            if memory_usage_task and not memory_usage_task.done():
                memory_usage_task.cancel()
            if disk_usage_task and not disk_usage_task.done():
                disk_usage_task.cancel()
            cpu_usage_task = asyncio.create_task(log_cpu_usage(session, cloud_endpoint, api_key, api_secret))
            memory_usage_task = asyncio.create_task(log_memory_usage(session, cloud_endpoint, api_key, api_secret))
            disk_usage_task = asyncio.create_task(log_disk_usage(session, cloud_endpoint, api_key, api_secret))
        except Exception as e:
            logging.error(f"Error logging system resources: {e}")
        await asyncio.sleep(config['heartbeat_interval'])


async def log_cpu_usage(session, cloud_endpoint, api_key, api_secret):
    while not shutdown_event.is_set():
        try:
            cpu_usage = psutil.cpu_percent(interval=None)
            url = f"{cloud_endpoint}/api/v1/system_resources"
            headers = {'Content-Type': 'application/json', 'X-API-Key': api_key}
            data = {'cpu_usage': cpu_usage, 'timestamp': time.time()}
            async with session.post(url, json=data, headers=headers) as response:
                if response.status != 200:
                    logging.error(f"Failed to log CPU usage. Status code: {response.status}")
                else:
                    logging.info(f"CPU usage logged: {cpu_usage}%")
        except Exception as e:
            logging.error(f"Error logging CPU usage: {e}")
        await asyncio.sleep(config['heartbeat_interval'])


async def log_memory_usage(session, cloud_endpoint, api_key, api_secret):
    while not shutdown_event.is_set():
        try:
            memory = psutil.virtual_memory()
            url = f"{cloud_endpoint}/api/v1/system_resources"
            headers = {'Content-Type': 'application/json', 'X-API-Key': api_key}
            data = {'memory_usage': memory.percent, 'timestamp': time.time()}
            async with session.post(url, json=data, headers=headers) as response:
                if response.status != 200:
                    logging.error(f"Failed to log memory usage. Status code: {response.status}")
                else:
                    logging.info(f"Memory usage logged: {memory.percent}%")
        except Exception as e:
            logging.error(f"Error logging memory usage: {e}")
        await asyncio.sleep(config['heartbeat_interval'])


async def log_disk_usage(session, cloud_endpoint, api_secret, api_key):
    while not shutdown_event.is_set():
        try:
            disk_usage = psutil.disk_usage("/")
            url = f"{cloud_endpoint}/api/v1/system_resources"
            headers = {'Content-Type': 'application/json', 'X-API-Key': api_key}
            data = {'disk_usage': disk_usage.percent, 'timestamp': time.time()}
            async with session.post(url, json=data, headers=headers) as response:
                if response.status != 200:
                    logging.error(f"Failed to log disk usage. Status code: {response.status}")
                else:
                    logging.info(f"Disk usage logged: {disk_usage.percent}%")
        except Exception as e:
            logging.error(f"Error logging disk usage: {e}")
        await asyncio.sleep(config['heartbeat_interval'])


async def capture_audio():
    global running, audio_task
    while running:
        try:
            logging.info("Starting audio capture...")
            sampling_rate = config['sampling_rate']
            audio_channels = config['audio_channels']
            duration = 1  # seconds
            buffer_size = int(sampling_rate * duration)
            audio_data = np.zeros((audio_channels, buffer_size), dtype=np.float32)
            audio_task = asyncio.create_task(record_audio(audio_data))
            await audio_task
            logging.info("Audio capture complete.")
        except Exception as e:
            logging.error(f"Error capturing audio: {e}")
            await asyncio.sleep(5)
        await asyncio.sleep(5)


async def record_audio(audio_data):
    try:
        with sd.InputStream(samplerate=sampling_rate, channels=audio_channels, dtype='float32', blocksize=buffer_size):
            while running:
                audio_frame = await sd.read(samplerate=sampling_rate, channels=audio_channels, dtype='float32', blocksize=buffer_size)
                if audio_frame is None:
                    logging.warning("Audio frame is None. Stopping audio recording.")
                    break
                audio_data = audio_frame.astype(np.float32)
                logging.debug(f"Audio data recorded: {audio_data.shape}")
                await process_audio(audio_data)
    except sd.PortAudioError as e:
        logging.error(f"Audio device error: {e}")
        raise AudioError(f"Audio device error: {e}")
    except Exception as e:
        logging.error(f"Error recording audio: {e}")
        raise AudioError(f"Error recording audio: {e}")


async def process_audio(audio_data):
    try:
        keyword_spotted = perform_keyword_spotting(audio_data, interpreter)
        if keyword_spotted:
            logging.info("Keyword spotted!")
            sentiment, sentiment_scores = perform_sentiment_analysis("Hello", interpreter)
            logging.info(f"Sentiment: {sentiment}, Scores: {sentiment_scores}")
            check_sentiment_thresholds(sentiment, sentiment_scores)
        else:
            logging.info("No keyword spotted.")
    except SentimentAnalysisError as e:
        logging.error(f"Sentiment analysis error: {e}")
    except Exception as e:
        logging.error(f"Error processing audio: {e}")


async def main():
    global running, alert_led, interpreter, last_heartbeat_time, heartbeat_task, config_update_task, cpu_usage_task, memory_usage_task, disk_usage_task, audio_task
    try:
        load_config()
        validate_config()
        logging.info("Starting voice assistant...")
        alert_led = LED(config['alert_led_pin'])
        interpreter = initialize_sentiment_interpreter(config['sentiment_analysis_model'])
        keyword_interpreter = initialize_keyword_interpreter(config['keyword_spotting_model'])
        if aiohttp:
            async with aiohttp.ClientSession() as session:
                last_heartbeat_time = time.time()
                heartbeat_task = asyncio.create_task(send_heartbeat(session, config['cloud_endpoint'], config['api_key'], config['api_secret']))
                config_update_task = asyncio.create_task(check_for_config_updates(session, config['cloud_endpoint'], config['api_key'], config['api_secret']))
                cpu_usage_task = asyncio.create_task(log_cpu_usage(session, config['cloud_endpoint'], config['api_key'], config['api_secret']))
                memory_usage_task = asyncio.create_task(log_memory_usage(session, config['cloud_endpoint'], config['api_key'], config['api_secret']))
                disk_usage_task = asyncio.create_task(log_disk_usage(session, config['cloud_endpoint'], config['api_secret'], config['api_key']))
                await capture_audio()
        else:
            logging.warning("aiohttp not installed. Disabling cloud communication.")
    except ConfigurationError as e:
        logging.error(f"Configuration error: {e}")
        print(f"Configuration error: {e}")
    except AudioError as e:
        logging.error(f"Audio error: {e}")
        print(f"Audio error: {e}")
    except Exception as e:
        logging.error(f"Unexpected error: {e}")
        print(f"Unexpected error: {e}")
    finally:
        running = False
        shutdown_event.set()
        if audio_task and not audio_task.done():
            audio_task.cancel()
        if heartbeat_task and not heartbeat_task.done():
            heartbeat_task.cancel()
        if config_update_task and not config_update_task.done():
            config_update_task.cancel()
        if cpu_usage_task and not cpu_usage_task.done():
            cpu_usage_task.cancel()
        if memory_usage_task and not memory_usage_task.done():
            memory_usage_task.cancel()
        if disk_usage_task and not disk_usage_task.done():
            disk_usage_task.cancel()
        if alert_led:
            alert_led.close()
        logging.info("Voice assistant stopped.")


def signal_handler(sig, frame):
    global running
    logging.info(f"Signal {sig} received. Shutting down...")
    running = False
    shutdown_event.set()


if __name__ == "__main__":
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)
    try:
        asyncio.run(main())
    except KeyboardInterrupt:
        pass
    except Exception as e:
        logging.error(f"Fatal error: {e}")
        sys.exit(1)

