        raise ConfigurationError("Invalid config update interval.")


def initialize_sentiment_interpreter(model_path):
    try:
        if not Path(model_path).exists():
            raise FileNotFoundError(f"Model file not found: {model_path}")
        interpreter = Interpreter(model_path=model_path)
        interpreter.allocate_tensors()
        logging.info("Sentiment analysis interpreter initialized successfully.")
        return interpreter
    except Exception as e:
        logging.error(f"Error initializing sentiment analysis interpreter: {e}")
        raise SentimentAnalysisError(f"Error initializing sentiment analysis interpreter: {e}")


def initialize_keyword_interpreter(model_path):
    try:
        if not Path(model_path).exists():
            raise FileNotFoundError(f"Model file not found: {model_path}")
        interpreter = Interpreter(model_path=model_path)
        interpreter.allocate_tensors()
        logging.info("Keyword spotting interpreter initialized successfully.")
        return interpreter
    except Exception as e:
        logging.error(f"Error initializing keyword spotting interpreter: {e}")
        raise SentimentAnalysisError(f"Error initializing keyword spotting interpreter: {e}")


def perform_sentiment_analysis(text, interpreter):
    try:
        input_details = interpreter.get_input_details()
        output_details = interpreter.get_output_details()
        input_data = np.array([text], dtype=input_details[0]['dtype'])
        interpreter.set_tensor(input_details[0]['index'], input_data)
        interpreter.invoke()
        output_data = interpreter.get_tensor(output_details[0]['index'])
        scores = output_data[0]
        sentiment = "positive" if scores[0] > scores[1] else ("negative" if scores[1] > scores[0] else "neutral")
        return sentiment, scores
    except Exception as e:
        logging.error(f"Error performing sentiment analysis: {e}")
        raise SentimentAnalysisError(f"Error performing sentiment analysis: {e}")


def perform_keyword_spotting(audio_data, interpreter):
    try:
        input_details = interpreter.get_input_details()
        output_details = interpreter.get_output_details()
        input_data = np.array([audio_data], dtype=input_details[0]['dtype'])
        interpreter.set_tensor(input_details[0]['index'], input_data)
        interpreter.invoke()
        output_data = interpreter.get_tensor(output_details[0]['index'])
        return bool(output_data[0][0])
    except Exception as e:
        logging.error(f"Error performing keyword spotting: {e}")
        return False


def check_sentiment_thresholds(sentiment, sentiment_scores):
    if sentiment == "positive" and sentiment_scores['positive'] > config['positive_sentiment_threshold']:
        logging.warning("Positive sentiment threshold exceeded!")
        trigger_alert()
    elif sentiment == "negative" and sentiment_scores['negative'] > config['negative_sentiment_threshold']:
        logging.warning("Negative sentiment threshold exceeded!")
        trigger_alert()


def trigger_alert():
    global alert_led
    if alert_led:
        try:
            alert_led.on()
            logging.warning("Alert triggered!")
        except GPIOZeroError as e:
            logging.error(f"Error triggering alert: {e}")


def check_system_resources():
    global last_cpu_usage, last_memory_usage, last_disk_usage
    try:
        cpu_usage = psutil.cpu_percent(interval=None)
        memory = psutil.virtual_memory()
        disk_usage = psutil.disk_usage("/")
        if cpu_usage > cpu_usage_threshold:
            logging.warning(f"CPU usage high: {cpu_usage}%")
        if memory.percent > memory_usage_threshold:
            logging.warning(f"Memory usage high: {memory.percent}%")
        if disk_usage.percent > disk_usage_threshold:
            logging.warning(f"Disk usage high: {disk_usage.percent}%")
        last_cpu_usage = cpu_usage
        last_memory_usage = memory.percent
        last_disk_usage = disk_usage.percent
    except Exception as e:
        logging.error(f"Error checking system resources: {e}")


def send_heartbeat(session, cloud_endpoint, api_key, api_secret):
    if not session:
        return
    try:
        url = f"{cloud_endpoint}/api/v1/heartbeat"
        headers = {'Content-Type': 'application/json', 'X-API-Key': api_key}
        data = {'status': 'running', 'timestamp': time.time()}
        async with session.post(url, json=data, headers=headers) as response:
            if response.status != 200:
                logging.error(f"Heartbeat failed with status code: {response.status}")
            else:
                logging.info("Heartbeat sent successfully.")
    except Exception as e:
        logging.error(f"Error sending heartbeat: {e}")
        raise CloudCommunicationError(f"Error sending heartbeat: {e}")


async def check_for_config_updates(session, cloud_endpoint, api_key, api_secret):
    global config, last_config_update_time
    while not shutdown_event.is_set():
        try:
            if time.time() - last_config_update_time > config['config_update_interval']:
                url = f"{cloud_endpoint}/api/v1/config"
                headers = {'Content-Type': 'application/json', 'X-API-Key': api_key}
                async with session.get(url, headers=headers) as response:
                    if response.status == 200:
                        new_config = await response.json()
                        async with config_lock:
                            config.update(new_config)
                            last_config_update_time = time.time()
                        logging.info("Configuration updated from cloud.")
                    else:
                        logging.warning(f"Failed to update configuration from cloud. Status code: {response.status}")
        except Exception as e:
            logging.error(f"Error checking for configuration updates: {e}")
        await asyncio.sleep(config['config_update_interval'])


async def log_system_resources(session, cloud_endpoint, api_key, api_secret):
    global cpu_usage_task, memory_usage_task, disk_usage_task
    while not shutdown_event.is_set():
        try:
            check_system_resources()
            if cpu_usage_task and not cpu_usage_task.done():
                cpu_usage_task.cancel()
            if memory_usage_task and not memory_usage_task.done():
                memory_usage_task.cancel()
            if disk_usage_task and not disk_usage_task.done():
                disk_usage_task.cancel()
            cpu_usage_task = asyncio.create_task(log_cpu_usage(session, cloud_endpoint, api_key, api_secret))
            memory_usage_task = asyncio.create_task(log_memory_usage(session, cloud_endpoint, api_key, api_secret))
            disk_usage_task = asyncio.create_task(log_disk_usage(session, cloud_endpoint, api_key, api_secret))
        except Exception as e:
            logging.error(f"Error logging system resources: {e}")
        await asyncio.sleep(config['heartbeat_interval'])


async def log_cpu_usage(session, cloud_endpoint, api_key, api_secret):
    while not shutdown_event.is_set():
        try:
            cpu_usage = psutil.cpu_percent(interval=None)
            url = f"{cloud_endpoint}/api/v1/system_resources"
            headers = {'Content-Type': 'application/json', 'X-API-Key': api_key}
            data = {'cpu_usage': cpu_usage, 'timestamp': time.time()}
            async with session.post(url, json=data, headers=headers) as response:
                if response.status != 200:
                    logging.error(f"Failed to log CPU usage. Status code: {response.status}")
                else:
                    logging.info(f"CPU usage logged: {cpu_usage}%")
        except Exception as e:
            logging.error(f"Error logging CPU usage: {e}")
        await asyncio.sleep(config['heartbeat_interval'])


async def log_memory_usage(session, cloud_endpoint, api_key, api_secret):
