                else:
                    logging.info(f"Disk usage logged: {disk_usage.percent}%")
        except Exception as e:
            logging.error(f"Error logging disk usage: {e}")
        await asyncio.sleep(config['heartbeat_interval'])


async def capture_audio():
    global running, audio_task
    while running:
        try:
            logging.info("Starting audio capture...")
            sampling_rate = config['sampling_rate']
            audio_channels = config['audio_channels']
            duration = 1  # seconds
            buffer_size = int(sampling_rate * duration)
            audio_data = np.zeros((audio_channels, buffer_size), dtype=np.float32)
            audio_task = asyncio.create_task(record_audio(audio_data))
            await audio_task
            logging.info("Audio capture complete.")
        except Exception as e:
            logging.error(f"Error capturing audio: {e}")
            await asyncio.sleep(5)
        await asyncio.sleep(5)


async def record_audio(audio_data):
    try:
        with sd.InputStream(samplerate=sampling_rate, channels=audio_channels, dtype='float32', blocksize=buffer_size):
            while running:
                audio_frame = await sd.read(samplerate=sampling_rate, channels=audio_channels, dtype='float32', blocksize=buffer_size)
                if audio_frame is None:
                    logging.warning("Audio frame is None. Stopping audio recording.")
                    break
                audio_data = audio_frame.astype(np.float32)
                logging.debug(f"Audio data recorded: {audio_data.shape}")
                await process_audio(audio_data)
    except sd.PortAudioError as e:
        logging.error(f"Audio device error: {e}")
        raise AudioError(f"Audio device error: {e}")
    except Exception as e:
        logging.error(f"Error recording audio: {e}")
        raise AudioError(f"Error recording audio: {e}")


async def process_audio(audio_data):
    try:
        keyword_spotted = perform_keyword_spotting(audio_data, interpreter)
        if keyword_spotted:
            logging.info("Keyword spotted!")
            sentiment, sentiment_scores = perform_sentiment_analysis("Hello", interpreter)
            logging.info(f"Sentiment: {sentiment}, Scores: {sentiment_scores}")
            check_sentiment_thresholds(sentiment, sentiment_scores)
        else:
            logging.info("No keyword spotted.")
    except SentimentAnalysisError as e:
        logging.error(f"Sentiment analysis error: {e}")
    except Exception as e:
        logging.error(f"Error processing audio: {e}")


async def main():
    global running, alert_led, interpreter, last_heartbeat_time, heartbeat_task, config_update_task, cpu_usage_task, memory_usage_task, disk_usage_task, audio_task
    try:
        load_config()
        validate_config()
        logging.info("Starting voice assistant...")
        alert_led = LED(config['alert_led_pin'])
        interpreter = initialize_sentiment_interpreter(config['sentiment_analysis_model'])
        keyword_interpreter = initialize_keyword_interpreter(config['keyword_spotting_model'])
        if aiohttp:
            async with aiohttp.ClientSession() as session:
                last_heartbeat_time = time.time()
                heartbeat_task = asyncio.create_task(send_heartbeat(session, config['cloud_endpoint'], config['api_key'], config['api_secret']))
                config_update_task = asyncio.create_task(check_for_config_updates(session, config['cloud_endpoint'], config['api_key'], config['api_secret']))
                cpu_usage_task = asyncio.create_task(log_cpu_usage(session, config['cloud_endpoint'], config['api_key'], config['api_secret']))
                memory_usage_task = asyncio.create_task(log_memory_usage(session, config['cloud_endpoint'], config['api_key'], config['api_secret']))
                disk_usage_task = asyncio.create_task(log_disk_usage(session, config['cloud_endpoint'], config['api_secret'], config['api_key']))
                await capture_audio()
        else:
            logging.warning("aiohttp not installed. Disabling cloud communication.")
    except ConfigurationError as e:
        logging.error(f"Configuration error: {e}")
        print(f"Configuration error: {e}")
    except AudioError as e:
        logging.error(f"Audio error: {e}")
        print(f"Audio error: {e}")
    except Exception as e:
        logging.error(f"Unexpected error: {e}")
        print(f"Unexpected error: {e}")
    finally:
        running = False
        shutdown_event.set()
        if audio_task and not audio_task.done():
            audio_task.cancel()
        if heartbeat_task and not heartbeat_task.done():
            heartbeat_task.cancel()
        if config_update_task and not config_update_task.done():
            config_update_task.cancel()
        if cpu_usage_task and not cpu_usage_task.done():
            cpu_usage_task.cancel()
        if memory_usage_task and not memory_usage_task.done():
            memory_usage_task.cancel()
        if disk_usage_task and not disk_usage_task.done():
            disk_usage_task.cancel()
        if alert_led:
            alert_led.close()
        logging.info("Voice assistant stopped.")


def signal_handler(sig, frame):
    global running
    logging.info(f"Signal {sig} received. Shutting down...")
    running = False
    shutdown_event.set()


if __name__ == "__main__":
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)
    try:
        asyncio.run(main())
    except KeyboardInterrupt:
        pass
    except Exception as e:
        logging.error(f"Fatal error: {e}")
        sys.exit(1)

