import time
import signal
import sys
import board
import busio
import adafruit_tsl2561
from gpiozero import PWMLED

# Constants
LED_PIN = 18
PWM_FREQUENCY = 1000
UPDATE_INTERVAL = 1.0
TSL2561_I2C_ADDRESS = 0x39

# Global flag for graceful shutdown
_running = True

def signal_handler(sig, frame):
    global _running
    _running = False

def initialize_i2c():
    try:
        i2c = busio.I2C(board.SCL, board.SDA)
        # Scan for the TSL2561 sensor at the default address
        if TSL2561_I2C_ADDRESS not in i2c.scan():
            print(f"Error: TSL2561 sensor not found at I2C address 0x{TSL2561_I2C_ADDRESS:02X}")
            return None
        return i2c
    except Exception as e:
        print(f"Error initializing I2C bus: {e}")
        return None

def initialize_light_sensor(i2c_bus):
    try:
        sensor = adafruit_tsl2561.TSL2561(i2c_bus, address=TSL2561_I2C_ADDRESS)
        # Enable the sensor and set a reasonable integration time
        sensor.enabled = True
        sensor.integration_time = adafruit_tsl2561.INTEGRATIONTIME_101MS
        return sensor
    except Exception as e:
        print(f"Error initializing TSL2561 light sensor: {e}")
        return None

def initialize_led(pin, frequency):
    try:
        led = PWMLED(pin, frequency=frequency)
        led.value = 0.0
        return led
    except Exception as e:
        print(f"Error initializing LED on GPIO {pin}: {e}")
        return None

def read_light_intensity(sensor):
    try:
        lux = sensor.lux
        if lux is None:
            print("Warning: Sensor returned None for lux value.")
            return None
        return lux
    except Exception as e:
        print(f"Error reading light intensity: {e}")
        return None

def map_to_brightness(lux):
    if lux is None:
        return 0.0
    # Map 0-10000 lux to 0-100% brightness
    brightness = (lux / 100.0) * 100.0
    return min(100.0, max(0.0, brightness))

def main():
    global _running
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    i2c_bus = initialize_i2c()
    if i2c_bus is None:
        sys.exit(1)

    light_sensor = initialize_light_sensor(i2c_bus)
    if light_sensor is None:
        sys.exit(1)

    led = initialize_led(LED_PIN, PWM_FREQUENCY)
    if led is None:
        sys.exit(1)

    current_brightness = 0.0

    try:
        while _running:
            lux = read_light_intensity(light_sensor)
            if lux is not None:
                brightness = map_to_brightness(lux)
                current_brightness = brightness
                print(f"Light Intensity: {lux:.2f} lux, LED Brightness: {brightness:.2f}%")
            else:
                print(f"Light Intensity: Sensor read error, LED Brightness: {current_brightness:.2f}%")

            led.value = current_brightness / 100.0
            time.sleep(UPDATE_INTERVAL)

    except Exception as e:
        print(f"Unexpected error in main loop: {e}")
    finally:
        if led is not None:
            led.close()
        print("Program terminated. GPIO cleaned up.")

if __name__ == "__main__":
    main()

