import RPi.GPIO as GPIO
import time
import sys

# Line-following robot using two TCRT5000 IR sensors
# Left sensor on GPIO 5, right sensor on GPIO 6 (BCM numbering)
LEFT_SENSOR_PIN = 5
RIGHT_SENSOR_PIN = 6
SAMPLE_COUNT = 10
SAMPLE_INTERVAL = 0.5  # seconds


def setup_sensors():
    """Configure GPIO pins for the two IR sensors.
    Raises RuntimeError if GPIO setup fails.
    """
    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(LEFT_SENSOR_PIN, GPIO.IN, pull_up_down=GPIO.PUD_UP)
        GPIO.setup(RIGHT_SENSOR_PIN, GPIO.IN, pull_up_down=GPIO.PUD_UP)
    except Exception as e:
        raise RuntimeError(f"Failed to initialize GPIO: {e}")


def read_sensors():
    """Read both IR sensors and return their states (0=black line, 1=white surface).
    Returns (left_state, right_state) or raises RuntimeError on read failure.
    """
    try:
        left_state = GPIO.input(LEFT_SENSOR_PIN)
        right_state = GPIO.input(RIGHT_SENSOR_PIN)
        return left_state, right_state
    except Exception as e:
        raise RuntimeError(f"Failed to read sensor data: {e}")


def decide_steering(left_state, right_state):
    """Decide steering direction based on sensor readings.
    Returns one of: 'forward', 'turn-left', 'turn-right', 'search'.
    """
    if left_state == 0 and right_state == 0:
        return "forward"
    if left_state == 1 and right_state == 1:
        return "search"
    if left_state == 0 and right_state == 1:
        return "turn-right"
    if left_state == 1 and right_state == 0:
        return "turn-left"
    return "unknown"


def cleanup_gpio():
    """Safely release GPIO resources."""
    try:
        GPIO.cleanup()
    except Exception:
        pass  # Ignore cleanup errors


def main():
    """Main loop: sample sensors, decide steering, print status."""
    try:
        setup_sensors()
    except RuntimeError as e:
        print(f"Initialization error: {e}", file=sys.stderr)
        sys.exit(1)

    try:
        for sample_index in range(SAMPLE_COUNT):
            left_state, right_state = read_sensors()
            steering = decide_steering(left_state, right_state)
            print(f"Sample {sample_index+1}: left={left_state}, right={right_state}, steering={steering}")
            time.sleep(SAMPLE_INTERVAL)
    except KeyboardInterrupt:
        print("\nLine-following stopped by user")
    except RuntimeError as e:
        print(f"Runtime error during sampling: {e}", file=sys.stderr)
    finally:
        cleanup_gpio()


if __name__ == "__main__":
    main()

