END_SIGNAL = "01111111"
BASE_BUFFER = "00000001"
TRANSMIT_DELAY = 0.0005

# Global flag for graceful shutdown
_running = True

def signal_handler(sig, frame):
    """Handles SIGINT and SIGTERM for graceful shutdown."""
    global _running
    logging.info(f"Signal {sig} received. Shutting down gracefully...")
    _running = False

def char_to_buffer(char):
    """Converts a character to its 8-bit buffer representation."""
    try:
        ascii_value = ord(char)
        binary_string = bin(ascii_value)[2:].zfill(7)
        return BASE_BUFFER + binary_string
    except (TypeError, IndexError) as e:
        logging.error(f"Invalid character '{char}' for conversion: {e}")
        return None

def buffer_to_char(buffer):
    """Converts an 8-bit buffer representation back to a character."""
    try:
        return chr(int(buffer[1:], 2))
    except (ValueError, IndexError) as e:
        logging.error(f"Invalid buffer '{buffer}' for conversion: {e}")
        return None

def string_to_buffer_list(input_string):
    """Converts a string to a list of 8-bit buffer representations."""
    return [char_to_buffer(char) for char in input_string]

def buffer_list_to_string(buffer_list):
    """Converts a list of 8-bit buffer representations back to a string."""
