#!/usr/bin/python3
"""
OutputPin: robust GPIO output control on Raspberry Pi using pigpio.

Provides a context-managed class for driving a single Broadcom BCM pin as
OUTPUT, with full error handling and clean shutdown.
"""

import time
import pigpio


class PigpioConnectionError(Exception):
    """Raised when the pigpio daemon cannot be reached."""


class InvalidPinNumberError(Exception):
    """Raised when the provided pin number is invalid."""


class InvalidValueError(Exception):
    """Raised when the provided value is invalid."""


class OutputPin:
    """Controls a single GPIO pin as a digital output via pigpio."""

    def __init__(
        self,
        pin_number: int,
        initial_value: int,
        pi_instance: pigpio.pi,
    ) -> None:
        """
        Initialize the OutputPin.

        Args:
            pin_number: Broadcom BCM pin number (0-31).
            initial_value: Initial output level (0 or 1).
            pi_instance: A connected pigpio.pi instance.

        Raises:
            PigpioConnectionError: If the pigpio daemon is unreachable.
            InvalidPinNumberError: If pin_number is outside 0-31.
            InvalidValueError: If initial_value is not 0 or 1.
        """
        if not isinstance(pin_number, int) or not (0 <= pin_number <= 31):
            raise InvalidPinNumberError(
                f"pin_number must be an integer in 0-31, got {pin_number!r}"
            )
        if not isinstance(initial_value, int) or initial_value not in (0, 1):
            raise InvalidValueError(
                f"initial_value must be 0 or 1, got {initial_value!r}"
            )
        if pi_instance is None or not pi_instance.connected:
            raise PigpioConnectionError("pigpio daemon is not connected")

        self.pin_number = pin_number
        self.pi = pi_instance
        self._value = initial_value

        try:
            self.pi.set_mode(self.pin_number, pigpio.OUTPUT)
            self.pi.write(self.pin_number, self._value)
        except pigpio.error as exc:
            raise RuntimeError(
                f"Failed to initialize GPIO {self.pin_number}: {exc}"
            ) from exc

    def set_value(self, value: int) -> None:
        """
        Set the output pin to the given value.

        Args:
            value: Desired output level (0 or 1).

        Raises:
            InvalidValueError: If value is not 0 or 1.
            RuntimeError: If the pigpio write fails.
        """
        if not isinstance(value, int) or value not in (0, 1):
            raise InvalidValueError(
                f"Invalid value {value!r}; must be 0 or 1"
            )
        if self.pi is None or not self.pi.connected:
            raise RuntimeError("pigpio connection is not available")

        try:
            self.pi.write(self.pin_number, value)
            self._value = value
        except pigpio.error as exc:
            raise RuntimeError(
                f"Failed to write to GPIO {self.pin_number}: {exc}"
            ) from exc

    def shutdown(self) -> None:
        """
        Release the pin: set it to INPUT and close the pigpio connection.

        Safe to call even if the pin was never fully initialized.
        """
        if self.pi is not None:
            try:
                self.pi.set_mode(self.pin_number, pigpio.INPUT)
            except pigpio.error:
                pass  # best-effort; ignore if already closed
            try:
                self.pi.stop()
            except pigpio.error:
                pass

    def __enter__(self) -> "OutputPin":
        return self

    def __exit__(self, exc_type, exc_val, exc_tb) -> None:
        self.shutdown()


if __name__ == "__main__":
    BCM_PIN = 17
    pi = pigpio.pi()
    if not pi.connected:
        print("ERROR: could not connect to pigpio daemon. Is pigpiod running?")
        raise SystemExit(1)

    try:
        with OutputPin(BCM_PIN, 1, pi) as pin:
            print(f"GPIO {BCM_PIN} set to OUTPUT, initial=1")
            for _ in range(10):
                pin.set_value(1)
                time.sleep(0.5)
                pin.set_value(0)
                time.sleep(0.5)
    except (PigpioConnectionError, InvalidPinNumberError, InvalidValueError) as exc:
        print(f"ERROR: {exc}")
    finally:
        pi.stop()

