import RPi.GPIO as GPIO
import time
import logging
import threading
import signal
import sys

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

DATA_OUT_PIN = 5
TIMER_OUT_PIN = 6
DATA_IN_PIN = 20
TIMER_IN_PIN = 21

START_BYTE = [1, 0, 1, 1, 1, 1, 1, 1]
END_BYTE = [1, 1, 1, 1, 1, 1, 1, 1]
BIT_DELAY = 0.0001

_shutdown_event = threading.Event()


def _signal_handler(signum, frame):
    logging.info(f"Signal {signum} received, shutting down.")
    _shutdown_event.set()


def _setup_gpio():
    GPIO.setmode(GPIO.BCM)
    GPIO.setwarnings(False)
    GPIO.setup(DATA_OUT_PIN, GPIO.OUT, initial=GPIO.LOW)
    GPIO.setup(TIMER_OUT_PIN, GPIO.OUT, initial=GPIO.LOW)
    GPIO.setup(DATA_IN_PIN, GPIO.IN, pull_up_down=GPIO.PUD_DOWN)
    GPIO.setup(TIMER_IN_PIN, GPIO.IN, pull_up_down=GPIO.PUD_DOWN)


def _cleanup_gpio():
    try:
        GPIO.output(DATA_OUT_PIN, GPIO.LOW)
        GPIO.output(TIMER_OUT_PIN, GPIO.LOW)
    except Exception:
        pass
    GPIO.cleanup()


def char_to_bits(char: str) -> list:
    if len(char) != 1:
        raise ValueError("Input must be a single character.")
    return [int(bit) for bit in bin(ord(char))[2:].zfill(8)]


def bits_to_char(bits: list) -> str:
    if len(bits) != 8:
        raise ValueError("Input must be exactly 8 bits.")
    return chr(int("".join(map(str, bits)), 2))


def string_to_bits_list(input_string: str) -> list:
    return [char_to_bits(char) for char in input_string]


def bits_list_to_string(bits_list: list) -> str:
    return "".join(bits_to_char(bits) for bits in bits_list)


def send_data(data: str):
    try:
        _setup_gpio()
        logging.info(f"Sending data: {data}")
        bits_to_send = [START_BYTE] + [char_to_bits(char) for char in data] + [END_BYTE]
        for bits in bits_to_send:
            for bit in bits:
                GPIO.output(TIMER_OUT_PIN, GPIO.LOW)
                GPIO.output(DATA_OUT_PIN, bit)
                time.sleep(BIT_DELAY)
                GPIO.output(TIMER_OUT_PIN, GPIO.HIGH)
                time.sleep(BIT_DELAY)
                GPIO.output(TIMER_OUT_PIN, GPIO.LOW)
        logging.info(f"Data sent: {data}")
    except Exception as e:
        logging.error(f"Error sending data: {e}")
        raise
    finally:
        _cleanup_gpio()


def _receive_byte():
    byte = []
    for _ in range(8):
        while not _shutdown_event.is_set():
            if GPIO.input(TIMER_IN_PIN) == GPIO.HIGH:
                byte.append(GPIO.input(DATA_IN_PIN))
                break
            time.sleep(0.00001)
    return byte if byte else None


def receive_data(timeout: float = 5.0) -> str:
    try:
        _setup_gpio()
        logging.info("Waiting for data...")
        received_bytes = []
        start_time = time.time()

        def on_timer_rising(channel):
            if _shutdown_event.is_set():
                return
            if time.time() - start_time > timeout:
                _shutdown_event.set()
                return
            received_bytes.append(GPIO.input(DATA_IN_PIN))

        GPIO.add_event_detect(TIMER_IN_PIN, GPIO.RISING, callback=on_timer_rising)
        try:
            while not _shutdown_event.is_set():
                if len(received_bytes) == 8:
                    received_bytes.append(_receive_byte())
                    if received_bytes[-1] is None:
                        logging.warning("Timeout waiting for byte start.")
                        return ""
                    if received_bytes[-1] == START_BYTE:
                        break
                time.sleep(0.00001)
        finally:
            GPIO.remove_event_detect(TIMER_IN_PIN)
        if _shutdown_event.is_set():
            logging.warning("Receive interrupted by shutdown.")
            return ""
        while received_bytes and received_bytes[-1] != END_BYTE:
            received_bytes.pop()
            if not received_bytes:
                logging.warning("Timeout waiting for end byte.")
                return ""
        if not received_bytes:
            logging.warning("No valid data received.")
            return ""
        logging.info(f"Received data: {bits_list_to_string(received_bytes[1:-1])}")
        return bits_list_to_string(received_bytes[1:-1])
    except Exception as e:
        logging.error(f"Error receiving data: {e}")
        return ""
    finally:
        _cleanup_gpio()


if __name__ == "__main__":
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)
    try:
        send_data("Hello")
        time.sleep(0.1)
        received = receive_data(timeout=5.0)
        print(f"Received: {received}")
    except Exception as e:
        logging.error(f"Fatal error: {e}")
        sys.exit(1)

