import signal
import sys
import time

try:
    from gpiozero import PWMOutputDevice
except ImportError:
    print("Error: gpiozero is not installed. Install with: pip install gpiozero", file=sys.stderr)
    sys.exit(1)

FAN_PIN = 12
PWM_FREQ = 25000  # 25 kHz - standard for 4-wire PWM fans

fan = None
running = True

def cleanup():
    global fan
    if fan is not None:
        try:
            fan.value = 0  # Turn fan off
            fan.close()    # Release the GPIO resource
        except Exception:
            pass
        fan = None

def signal_handler(signum, frame):
    global running
    running = False

def main():
    global fan

    # Register signal handlers for clean exit
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    # Initialize PWM output device. gpiozero may fall back to software PWM
    # if hardware PWM is unavailable (e.g., mocked/emulated environments).
    try:
        fan = PWMOutputDevice(FAN_PIN, frequency=PWM_FREQ, initial_value=0)
    except Exception as e:
        print(f"Error initializing PWM on GPIO{FAN_PIN}: {e}", file=sys.stderr)
        sys.exit(1)

    print(f"PWM fan control started on GPIO{FAN_PIN} at {PWM_FREQ} Hz.")
    print("Enter a speed between 0 and 100, or 'q' to quit.")

    try:
        while running:
            try:
                user_input = input("Fan Speed (0-100): ").strip()
            except EOFError:
                print("\nEOF received, exiting.")
                break

            if user_input.lower() == 'q':
                break

            try:
                speed = float(user_input)
            except ValueError:
                print("Invalid input. Please enter a number between 0 and 100.")
                continue

            if not (0 <= speed <= 100):
                print("Invalid input. Please enter a number between 0 and 100.")
                continue

            # gpiozero uses 0.0 to 1.0 for duty cycle
            fan.value = speed / 100.0
            print(f"Fan speed set to {speed:.1f}%")

    except Exception as e:
        print(f"An error occurred: {e}", file=sys.stderr)
    finally:
        cleanup()
        print("Fan control stopped. GPIO resources released.")

if __name__ == "__main__":
    main()

