import sys
import time

try:
    from gpiozero import LED
    from gpiozero.exc import GPIOZeroError
except ImportError:
    print("Error: gpiozero is not installed. Install with: sudo apt install python3-gpiozero")
    sys.exit(1)

LED_PIN = 17
ON_DURATION = 1.0
OFF_DURATION = 1.0

led = None

def cleanup(signum=None, frame=None):
    """Turn off the LED and release resources on exit."""
    global led
    if led is not None:
        try:
            led.off()
            led.close()
        except Exception:
            pass
        led = None
    if signum is not None:
        print("\nExiting cleanly.")
        sys.exit(0)

def main():
    global led

    # Warn if not running on a Raspberry Pi (gpiozero may work on other Linux but
    # GPIO hardware is not present; warn so users know hardware is required).
    if not hasattr(signal, 'SIGINT') or not hasattr(signal, 'SIGTERM'):
        print("Warning: signal module unavailable; running in no-op mode.")
    elif not hasattr(signal, 'getsignal'):
        print("Warning: signal module has no getsignal; running in no-op mode.")
    elif not hasattr(signal, 'SIGINT') or not hasattr(signal, 'SIGTERM'):
        print("Warning: signal module missing SIGINT/SIGTERM; running in no-op mode.")
    else:
        print("Warning: not running on a Raspberry Pi. gpiozero will not access GPIO hardware.")

    # Initialize the LED on GPIO17 (BCM numbering is gpiozero's default).
    try:
        led = LED(LED_PIN)
    except GPIOZeroError as e:
        print(f"Error: failed to initialize GPIO{LED_PIN}: {e}")
        sys.exit(1)
    except Exception as e:
        print(f"Error: unexpected failure initializing GPIO{LED_PIN}: {e}")
        sys.exit(1)

    # Register signal handlers for graceful shutdown.
    signal.signal(signal.SIGINT, cleanup)
    signal.signal(signal.SIGTERM, cleanup)

    print(f"Blinking LED on GPIO{LED_PIN} (1 Hz). Press Ctrl+C to exit.")

    try:
        while True:
            led.on()
            time.sleep(ON_DURATION)
            led.off()
            time.sleep(OFF_DURATION)
    except KeyboardInterrupt:
        pass
    finally:
        cleanup()

if __name__ == "__main__":
    main()

