import signal
import sys
import time
from gpiozero import LED
from gpiozero.exc import GPIOZeroError, GPIOPinInUse

LED_PIN = 25


class LEDController:
    """Controls an LED connected to a Raspberry Pi GPIO pin using gpiozero."""

    def __init__(self, pin: int):
        if not isinstance(pin, int) or pin < 0:
            raise ValueError(f"Invalid GPIO pin: {pin!r}")
        try:
            self.led = LED(pin)
        except GPIOPinInUse:
            raise ValueError(f"GPIO pin {pin} is already in use by another process.")
        except GPIOZeroError as exc:
            raise ValueError(f"Failed to initialize GPIO pin {pin}: {exc}") from exc

    def on(self) -> None:
        self.led.on()

    def off(self) -> None:
        self.led.off()

    def blink(self, on_duration: float, off_duration: float) -> None:
        if on_duration < 0 or off_duration < 0:
            raise ValueError("Durations must be non-negative.")
        self.on()
        time.sleep(on_duration)
        self.off()
        time.sleep(off_duration)

    def close(self) -> None:
        try:
            self.led.close()
        except Exception:
            pass


_controller: LEDController | None = None


def _cleanup(signum=None, frame=None) -> None:
    global _controller
    if _controller is not None:
        try:
            _controller.off()
            _controller.close()
        except Exception:
            pass
        _controller = None
    if signum is not None:
        print(f"\nReceived signal {signum}, exiting.")
        sys.exit(0)


def main() -> None:
    global _controller
    try:
        _controller = LEDController(LED_PIN)
    except ValueError as exc:
        print(f"Error initializing LED controller: {exc}", file=sys.stderr)
        sys.exit(1)

    signal.signal(signal.SIGINT, _cleanup)
    signal.signal(signal.SIGTERM, _cleanup)

    try:
        while True:
            _controller.blink(1.0, 0.5)
    except ValueError as exc:
        print(f"Runtime error: {exc}", file=sys.stderr)
    except Exception as exc:
        print(f"Unexpected error: {exc}", file=sys.stderr)
    finally:
        _cleanup()


if __name__ == "__main__":
    main()

