import logging
import signal
import sys
import time

from gpiozero import Motor, DigitalOutputDevice
from gpiozero.exc import GPIOZeroError, DeviceClosed

logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s - %(levelname)s - %(message)s",
)

FORWARD_PIN_LEFT = 17
BACKWARD_PIN_LEFT = 18
FORWARD_PIN_RIGHT = 22
BACKWARD_PIN_RIGHT = 23
ENABLE_A_PIN = 12
ENABLE_B_PIN = 13
TILT_THRESHOLD = 20
EXECUTE_DURATION = 0.5
TILT_READINGS = [25, -25, 0, 30, -15, 40, -30, 10]


class ChassisController:
    """Controls a two-motor rover chassis using gpiozero."""

    def __init__(self):
        self.left_motor = None
        self.right_motor = None
        self.enable_a = None
        self.enable_b = None
        self._initialized = False
        try:
            self.left_motor = Motor(forward=FORWARD_PIN_LEFT, backward=BACKWARD_PIN_LEFT)
            self.right_motor = Motor(forward=FORWARD_PIN_RIGHT, backward=BACKWARD_PIN_RIGHT)
            self.enable_a = DigitalOutputDevice(ENABLE_A_PIN, active_high=True, initial_value=False)
            self.enable_b = DigitalOutputDevice(ENABLE_B_PIN, active_high=True, initial_value=False)
            self.enable_a.on()
            self.enable_b.on()
            self._initialized = True
            logging.info("ChassisController initialized successfully.")
        except GPIOZeroError as e:
            logging.error("GPIO initialization failed: %s", e)
            self.cleanup()
            raise

    def drive_forward(self, speed_fraction):
        if not self._initialized:
            logging.error("Controller not initialized; cannot drive.")
            return
        try:
            self.left_motor.forward(speed_fraction)
            self.right_motor.forward(speed_fraction)
            logging.info("Driving forward at speed %.2f", speed_fraction)
        except DeviceClosed as e:
            logging.error("Motor device closed unexpectedly: %s", e)
        except GPIOZeroError as e:
            logging.error("GPIO error while driving forward: %s", e)

    def turn_left(self, speed_fraction):
        if not self._initialized:
            logging.error("Controller not initialized; cannot turn.")
            return
        try:
            self.left_motor.backward(speed_fraction)
            self.right_motor.forward(speed_fraction)
            logging.info("Turning left at speed %.2f", speed_fraction)
        except DeviceClosed as e:
            logging.error("Motor device closed unexpectedly: %s", e)
        except GPIOZeroError as e:
            logging.error("GPIO error while turning left: %s", e)

    def turn_right(self, speed_fraction):
        if not self._initialized:
            logging.error("Controller not initialized; cannot turn.")
            return
        try:
            self.left_motor.forward(speed_fraction)
            self.right_motor.backward(speed_fraction)
            logging.info("Turning right at speed %.2f", speed_fraction)
        except DeviceClosed as e:
