import random
import time
import signal
import sys
from gpiozero import LED
from gpiozero.exc import GPIOZeroError

# Configuration
LED_PIN = 18
ALERT_THRESHOLD = 50
NUM_READINGS = 5
DELAY_SECONDS = 2
SENSOR_FAILURE_RATE = 0.1  # 10% chance of failure
RETRY_ATTEMPTS = 1

# Global flag for graceful shutdown
_running = True

def signal_handler(signum, frame):
    """Handle SIGINT/SIGTERM for clean shutdown."""
    global _running
    _running = False
    print("\nShutdown signal received. Cleaning up...")

def simulate_water_quality_reading():
    """Simulates a water quality reading as a percentage (0-100)."""
    return random.randint(0, 100)

def read_sensor_with_retry():
    """Reads the water quality sensor with a retry mechanism."""
    for attempt in range(RETRY_ATTEMPTS + 1):
        try:
            quality = simulate_water_quality_reading()
            if random.random() < SENSOR_FAILURE_RATE:
                print(f"Sensor read failed (attempt {attempt + 1}/{RETRY_ATTEMPTS + 1}).")
            else:
                return quality
        except Exception as e:
            print(f"Unexpected error during sensor read (attempt {attempt + 1}/{RETRY_ATTEMPTS + 1}): {e}")
        if attempt < RETRY_ATTEMPTS:
            time.sleep(0.5)
    return None

def control_led(led, quality):
    """Controls the LED based on the water quality reading."""
    if quality < ALERT_THRESHOLD:
        led.on()
        print("Alert: Water quality is low!")
    else:
        led.off()
        print("Water quality is normal.")

def main():
    """Main function to simulate water quality monitoring."""
    global _running

    # Register signal handlers for graceful shutdown
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    led = None
    try:
        # Initialize LED with error handling
        try:
            led = LED(LED_PIN)
            print(f"LED initialized on GPIO{LED_PIN} (BCM).")
        except GPIOZeroError as e:
            print(f"Failed to initialize LED on GPIO{LED_PIN}: {e}")
            sys.exit(1)
        except Exception as e:
            print(f"Unexpected error during LED initialization: {e}")
            sys.exit(1)

        # Main loop
        for i in range(NUM_READINGS):
            if not _running:
                break

            print(f"\nReading {i + 1}/{NUM_READINGS}")
            quality = read_sensor_with_retry()

            if quality is None:
                print("Failed to obtain a valid sensor reading after retries. Skipping this reading.")
                continue

            print(f"Simulated Water Quality: {quality}%")
            control_led(led, quality)

            # Wait for the specified delay, checking for shutdown
            for _ in range(DELAY_SECONDS):
                if not _running:
                    break
                time.sleep(1)

    except Exception as e:
        print(f"An error occurred: {e}")
    finally:
        # Clean up resources
        if led is not None:
            try:
                led.close()
                print("LED resource released.")
            except Exception as e:
                print(f"Error releasing LED resource: {e}")
        print("Program finished.")

if __name__ == "__main__":
    main()

