import signal
import time
from gpiozero import LED
from gpiozero.exc import GPIOZeroError, GPIODeviceError

# Define GPIO pins for the LEDs (BCM numbering)
LED1_PIN = 18
LED2_PIN = 23

# Global references for cleanup
led1 = None
led2 = None

def cleanup():
    """Turn off and close both LED resources."""
    global led1, led2
    for led in (led1, led2):
        if led is not None:
            try:
                led.off()
                led.close()
            except Exception as e:
                print(f"Warning: error during cleanup of {led.pin}: {e}")
    led1 = None
    led2 = None

def signal_handler(sig, frame):
    """Handle Ctrl+C to ensure clean resource release."""
    print("\nInterrupt received, cleaning up...")
    cleanup()
    exit(0)

def turn_on():
    """Turn on both LEDs."""
    try:
        led1.on()
        led2.on()
        print("Both LEDs are ON")
    except (GPIOZeroError, GPIODeviceError) as e:
        print(f"Error turning on LEDs: {e}")
    except Exception as e:
        print(f"Unexpected error turning on LEDs: {e}")

def turn_off():
    """Turn off both LEDs."""
    try:
        led1.off()
        led2.off()
        print("Both LEDs are OFF")
    except (GPIOZeroError, GPIODeviceError) as e:
        print(f"Error turning off LEDs: {e}")
    except Exception as e:
        print(f"Unexpected error turning off LEDs: {e}")

def toggle():
    """Toggle both LEDs on for 1 second, then off for 1 second."""
    try:
        turn_on()
        time.sleep(1)
        turn_off()
        time.sleep(1)
    except Exception as e:
        print(f"Error during toggle operation: {e}")

def main():
    """Main function to initialize LEDs and run the toggle loop."""
    global led1, led2
    try:
        led1 = LED(LED1_PIN)
        led2 = LED(LED2_PIN)
        print("LEDs initialized successfully.")
    except (GPIOZeroError, GPIODeviceError) as e:
        print(f"Error initializing LEDs: {e}")
        cleanup()
        return
    except Exception as e:
        print(f"Unexpected error during initialization: {e}")
        cleanup()
        return

    # Register signal handler for graceful shutdown
    signal.signal(signal.SIGINT, signal_handler)

    try:
        for i in range(5):
            toggle()
            print(f"Cycle {i + 1} completed.")
    except Exception as e:
        print(f"Error during toggle loop: {e}")
    finally:
        cleanup()

if __name__ == "__main__":
    main()

