import signal
import sys
import time
import logging
import serial
from pymodbus.client import ModbusSerialClient
from pymodbus.exceptions import ModbusException
from pymodbus.payload import BinaryPayloadDecoder
from pymodbus.constants import Endian

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')
logger = logging.getLogger(__name__)


class Servo:
    """
    A class to control and monitor a servo motor via Modbus RTU over UART on a Raspberry Pi.
    """

    # Register map for the servo motor
    REGISTERS = {
        "CONTROL": {
            "R/W": "W",
            "Register": 0x3100,
            "functioncode": 6,
            "Value": {
                "Stop": 0x0006,
                "Start": 0x000F,
            },
        },
        "STATUS": {
            "R/W": "R",
            "Register": 0x3000,
            "functioncode": 3,
        },
        "OPMODE": {
            "R/W": "W",
            "Register": 0x3500,
            "functioncode": 6,
            "Value": {
                "Position": 1,
            },
        },
        "VelocityCommand": {
            "R/W": "W",
            "Register": 0x6F00,
            "functioncode": 16,
        },
        "VelocityFeedback": {
            "R/W": "R",
            "Register": 0x3B00,
            "functioncode": 3,
            "read_length": 2,
        },
        "PositionCommand": {
            "R/W": "W",
            "Register": 0x4000,
            "functioncode": 16,
        },
        "PositionFeedback": {
            "R/W": "R",
            "Register": 0x3700,
            "functioncode": 3,
            "read_length": 2,
        },
    }

    def __init__(self, port="/dev/serial0", baudrate=115200, timeout=1.0):
        self._running = True
        self.client = None
        self._connect(port, baudrate, timeout)

    def _connect(self, port, baudrate, timeout):
        try:
            self.client = ModbusSerialClient(
                port=port,
                baudrate=baudrate,
                bytesize=8,
                parity="N",
                stopbits=1,
                timeout=timeout,
            )
            if not self.client.connect():
                raise serial.SerialException(f"Failed to open serial port {port}")
            logger.info(f"Connected to servo on {port} at {baudrate} baud.")
        except (serial.SerialException, ModbusException, OSError) as e:
            logger.warning(f"Could not connect to servo on {port}: {e}. Running in degraded mode.")
            self.client = None

    def _read_register(self, register_name, count=1):
        if self.client is None:
            return None
        try:
            reg = self.REGISTERS[register_name]
            if reg["R/W"] != "R":
                raise KeyError(f"Register {register_name} is not readable.")
            addr = reg["Register"]
            if reg.get("read_length", 1) != count:
                raise KeyError(f"Register {register_name} read_length is {reg['read_length']}, expected {count}.")
            result = self.client.read_holding_registers(address=addr, count=count, slave=1)
            if result.isError():
                raise ModbusException(f"Modbus error reading {register_name}: {result}")
            return result.registers[0] if count == 1 else result.registers
        except (KeyError, ModbusException, IndexError) as e:
            logger.error(f"Error reading register {register_name}: {e}")
            return None

    def _write_register(self, register_name, value):
        if self.client is None:
            return False
        try:
            reg = self.REGISTERS[register_name]
            if reg["R/W"] != "W":
                raise KeyError(f"Register {register_name} is not writable.")
            addr = reg["Register"]
            if reg.get("functioncode") == 6:
                result = self.client.write_register(address=addr, value=value, slave=1)
            elif reg.get("functioncode") == 16:
                result = self.client.write_registers(address=addr, values=[value], slave=1)
            else:
                raise KeyError(f"Unknown function code for {register_name}.")
            if result.isError():
                raise ModbusException(f"Modbus error writing {register_name}: {result}")
            return True
        except (KeyError, ModbusException) as e:
            logger.error(f"Error writing to register {register_name}: {e}")
            return False

    def get_status(self):
        status = self._read_register("STATUS")
        if status is None:
            return None
        return {
            "Status": status,
            "Error": 0 if status == 0 else 1,
            "Warning": 1 if status & 0x02 else 0,
            "BusError": 1 if status & 0x04 else 0,
            "Home": 1 if status & 0x08 else 0,
            "Limit": 1 if status & 0x10 else 0,
            "Direction": 1 if status & 0x20 else 0,
            "Stop": 1 if status & 0x40 else 0,
            "Fault": 1 if status & 0x80 else 0,
        }

    def get_velocity(self):
        velocity = self._read_register("VelocityFeedback")
        if velocity is None:
            return None
        return {
            "Velocity": velocity,
            "VelocityUnit": 1 if velocity > 0 else 0,
        }

    def get_position(self):
        position = self._read_register("PositionFeedback")
        if position is None:
            return None
        return {
            "Position": position,
            "PositionUnit": 1 if position > 0 else 0,
        }

    def set_velocity(self, velocity):
        if self.client is None:
            return False
        try:
            value = int(self.REGISTERS["VelocityCommand"]["Value"][str(velocity)])
            return self._write_register("VelocityCommand", value)
        except (KeyError, ValueError) as e:
            logger.error(f"Invalid velocity value: {e}")
            return False

    def set_position(self, position):
        if self.client is None:
            return False
        try:
            value = int(self.REGISTERS["PositionCommand"]["Value"][str(position)])
            return self._write_register("PositionCommand", value)
        except (KeyError, ValueError) as e:
            logger.error(f"Invalid position value: {e}")
            return False

    def stop(self):
        if self.client is not None:
            try:
                self._write_register("CONTROL", self.REGISTERS["CONTROL"]["Value"]["Stop"])
            except Exception as e:
                logger.error(f"Error stopping servo: {e}")
        self._running = False

    def close(self):
        self._running = False
        if self.client is not None:
            try:
                self.client.close()
            except Exception as e:
                logger.error(f"Error closing serial connection: {e}")
            finally:
                self.client = None


def main():
    servo = Servo(port="/dev/serial0", baudrate=115200, timeout=1.0)

    def signal_handler(sig, frame):
        logger.info("Signal received, stopping servo...")
        servo.stop()
        servo.close()
        sys.exit(0)

    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        if servo.client is not None:
            servo.set_position(100)
            time.sleep(1)
            servo.set_velocity(100)
            time.sleep(1)
            servo.stop()
    except Exception as e:
        logger.error(f"Unexpected error: {e}")
    finally:
        servo.close()


if __name__ == "__main__":
    main()

