#!/usr/bin/env python3
"""
Garage door controller for Raspberry Pi using Pimoroni Automation HAT.

Wiring:
  - Automation HAT connected to Raspberry Pi 40-pin header.
  - Garage door reed switch between Automation HAT input 1 (GPIO26) and GND.
  - Automation HAT relay channel 1 (GPIO15) drives the garage door opener
    control input (e.g., a 12 V DC adapter with a suitable MOSFET driver).

The reed switch reads as HIGH (1) when the door is closed, LOW (0) when open.
"""

import logging
import signal
import sys
import time

logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s - %(levelname)s - %(message)s",
)

DOOR_CLOSED = "closed"
DOOR_OPEN = "open"

# Module-level reference for signal handler
_garage = None


def _cleanup(signum=None, frame=None):
    """Ensure the relay is OFF on exit or signal."""
    global _garage
    if _garage is not None:
        try:
            _garage.trigger(DOOR_CLOSED)
            logging.info("Relay de-energized on exit.")
        except Exception as exc:
            logging.error("Error during cleanup: %s", exc)
        _garage = None
    if signum is not None:
        sys.exit(0)


def _trigger_relay(state):
    """Energize relay.one for 0.5 s, then de-energize it."""
    try:
        automationhat.relay.one.on()
        time.sleep(0.5)
        automationhat.relay.one.off()
        logging.info("Relay energized for %.1f s (%s).", 0.5, state)
    except Exception as exc:
        logging.error("Failed to trigger relay: %s", exc)
        raise


def _read_state():
    """Read the door state from the reed switch.

    Returns:
        str: DOOR_CLOSED or DOOR_OPEN.

    Raises:
        RuntimeError: if the state pin cannot be read or the value is
        invalid.
    """
    try:
        value = automationhat.input.one.read()
    except Exception as exc:
        logging.error("Error reading input one: %s", exc)
        raise RuntimeError(f"Failed to read input one: {exc}") from exc

    if value is None:
        raise RuntimeError("Input one returned None.")
    if value not in (0, 1):
        raise RuntimeError(f"Unexpected input value: {value!r}")
    return DOOR_CLOSED if value == 1 else DOOR_OPEN


def _verify_automationhat():
    """Verify that automationhat is connected and the relay is OFF."""
    try:
        if not automationhat.is_connected():
            raise RuntimeError("Automation HAT not detected on the I2C bus.")
    except Exception as exc:
        logging.error("Automation HAT connection check failed: %s", exc)
        raise RuntimeError(f"Automation HAT connection check failed: {exc}") from exc

    try:
        if automationhat.relay.one.is_active():
            logging.warning("Relay one was active on startup; forcing OFF.")
            automationhat.relay.one.off()
    except Exception as exc:
        logging.error("Failed to read relay state on startup: %s", exc)
        raise RuntimeError(f"Failed to read relay state on startup: {exc}") from exc


def _install_signal_handlers(garage):
    """Install SIGINT and SIGTERM handlers for clean shutdown."""
    signal.signal(signal.SIGINT, lambda s, f: _cleanup(s, f))
    signal.signal(signal.SIGTERM, lambda s, f: _cleanup(s, f))
    logging.info("Installed signal handlers for clean shutdown.")


def main():
    """Main entry point: instantiate GarageDoor and toggle the door."""
    global _garage

    # --- Initialization with error handling ---
    try:
        _verify_automationhat()
    except RuntimeError:
        logging.error("Cannot continue without Automation HAT. Exiting.")
        sys.exit(0)

    try:
        _install_signal_handlers(None)  # placeholder; signal handler will use _garage
    except Exception as exc:
        logging.error("Failed to install signal handlers: %s", exc)
        sys.exit(0)

    try:
        _garage = My_Garage(state_pin=1)
    except Exception as exc:
        logging.error("Failed to initialize GarageDoor: %s", exc)
        sys.exit(0)

    # --- Main loop ---
    try:
        while True:
            try:
                current_state = _garage.state
            except Exception as exc:
                logging.error("Failed to read door state: %s", exc)
                time.sleep(1)
                continue

            if current_state == DOOR_CLOSED:
                logging.info("Door is closed; triggering open.")
                try:
                    _trigger_relay(DOOR_OPEN)
                except Exception as exc:
                    logging.error("Failed to trigger open: %s", exc)
            else:
                logging.info("Door is open; triggering close.")
                try:
                    _trigger_relay(DOOR_CLOSED)
                except Exception as exc:
                    logging.error("Failed to trigger close: %s", exc)

            time.sleep(1)

    except KeyboardInterrupt:
        logging.info("KeyboardInterrupt received; shutting down.")
    except Exception as exc:
        logging.error("Unexpected error in main loop: %s", exc)
    finally:
        _cleanup()


if __name__ == "__main__":
    main()

