        if not automationhat.is_connected():
            raise RuntimeError("Automation HAT not detected on the I2C bus.")
    except Exception as exc:
        logging.error("Automation HAT connection check failed: %s", exc)
        raise RuntimeError(f"Automation HAT connection check failed: {exc}") from exc

    try:
        if automationhat.relay.one.is_active():
            logging.warning("Relay one was active on startup; forcing OFF.")
            automationhat.relay.one.off()
    except Exception as exc:
        logging.error("Failed to read relay state on startup: %s", exc)
        raise RuntimeError(f"Failed to read relay state on startup: {exc}") from exc


def _install_signal_handlers(garage):
    """Install SIGINT and SIGTERM handlers for clean shutdown."""
    signal.signal(signal.SIGINT, lambda s, f: _cleanup(s, f))
    signal.signal(signal.SIGTERM, lambda s, f: _cleanup(s, f))
    logging.info("Installed signal handlers for clean shutdown.")


def main():
    """Main entry point: instantiate GarageDoor and toggle the door."""
    global _garage

    # --- Initialization with error handling ---
    try:
        _verify_automationhat()
    except RuntimeError:
        logging.error("Cannot continue without Automation HAT. Exiting.")
        sys.exit(0)

    try:
        _install_signal_handlers(None)  # placeholder; signal handler will use _garage
    except Exception as exc:
        logging.error("Failed to install signal handlers: %s", exc)
        sys.exit(0)

    try:
