    except Exception as exc:
        logging.error("Failed to initialize GarageDoor: %s", exc)
        sys.exit(0)

    # --- Main loop ---
    try:
        while True:
            try:
                current_state = _garage.state
            except Exception as exc:
                logging.error("Failed to read door state: %s", exc)
                time.sleep(1)
                continue

            if current_state == DOOR_CLOSED:
                logging.info("Door is closed; triggering open.")
                try:
                    _trigger_relay(DOOR_OPEN)
                except Exception as exc:
                    logging.error("Failed to trigger open: %s", exc)
            else:
                logging.info("Door is open; triggering close.")
                try:
                    _trigger_relay(DOOR_CLOSED)
                except Exception as exc:
                    logging.error("Failed to trigger close: %s", exc)

            time.sleep(1)

    except KeyboardInterrupt:
        logging.info("KeyboardInterrupt received; shutting down.")
    except Exception as exc:
        logging.error("Unexpected error in main loop: %s", exc)
    finally:
        _cleanup()


if __name__ == "__main__":
    main()

