    global _pca, _esc_value, _steering_value, _curses_ok

    if _pca is not None:
        try:
            _pca.channels[PWM_CHANNEL_ESC].duty_cycle = (
                _pca.channels[PWM_CHANNEL_ESC].duty_cycle
            )
        except Exception:
            pass
        try:
            _pca.channels[PWM_CHANNEL_STEERING].duty_cycle = (
                _pca.channels[PWM_CHANNEL_STEERING].duty_cycle
            )
        except Exception:
            pass

    if _pca is not None:
        try:
            _pca.deinit()
        except Exception:
            pass
        _pca = None

    if _curses_ok:
        try:
            curses.nocbreak()
            curses.echo()
            curses.endwin()
        except Exception:
            pass
        _curses_ok = False

    if signum is not None:
        sys.exit(0)


def _init_pca9685():
    """Initialize I2C bus and PCA9685; return PCA instance or None on failure."""
    global _pca
    try:
        i2c = busio.I2C(board.SCL, board.SDA)
    except Exception as exc:
        print(f"Error initializing I2C bus: {exc}", file=sys.stderr)
        return None

    try:
        _pca = PCA9685(i2c, address=0x40)
        _pca.frequency = PWM_FREQUENCY
    except Exception as exc:
        print(f"Error initializing PCA9685 at 0x40: {exc}", file=sys.stderr)
        return None

    return _pca


def _set_pwm(channel, value):
    """Set a PCA9685 channel duty cycle with error handling."""
    if _pca is None:
        return False
    try:
        _pca.channels[channel].duty_cycle = value
        return True
    except Exception as exc:
        print(f"Error writing PWM channel {channel}: {exc}", file=sys.stderr)
        return False


def calibrate_esc(pwm):
    """Ramp ESC from 200 to 600 then back to 200 in 20-step increments."""
    for value in range(THROTTLE_REVERSE_MAX, THROTTLE_FORWARD_MAX + 1, CALIBRATION_INCREMENT):
        if not _set_pwm(PWM_CHANNEL_ESC, value):
            return False
        time.sleep(CALIBRATION_DELAY)
    for value in range(THROTTLE_FORWARD_MAX, THROTTLE_REVERSE_MAX - 1, -CALIBRATION_INCREMENT):
        if not _set_pwm(PWM_CHANNEL_ESC, value):
            return False
        time.sleep(CALIBRATION_DELAY)
    return True


def _safe_getch():
    """Return curses getch() or None if unavailable."""
    try:
        return curses.getch(_screen)
    except Exception:
        return None


def main(stdscr):
    """Main curses loop for RC car control."""
    global _esc_value, _steering_value, _curses_ok

    _curses_ok = True
    try:
        curses.noecho()
        curses.cbreak()
        stdscr.keypad(True)
    except Exception as exc:
        print(f"Error setting up curses: {exc}", file=sys.stderr)
        _curses_ok = False
        return

    pwm = _init_pca9685()
    if pwm is None:
        return

    if not calibrate_esc(pwm):
        return

    _set_pwm(PWM_CHANNEL_ESC, THROTTLE_STOP_VALUE)
    _set_pwm(PWM_CHANNEL_STEERING, STEERING_CENTER_VALUE)

    try:
        while True:
            ch = _safe_getch()
            if ch is None:
                break

            if ch == ord('q'):
                _esc_value = THROTTLE_STOP_VALUE
                _steering_value = STEERING_CENTER_VALUE
            elif ch == ord('x'):
                break
            elif ch == curses.KEY_UP:
                _esc_value = min(THROTTLE_FORWARD_MAX, _esc_value + 20)
            elif ch == curses.KEY_DOWN:
                _esc_value = max(THROTTLE_REVERSE_MAX, _esc_value - 20)
            elif ch == curses.KEY_LEFT:
                _steering_value = max(STEERING_MAX_LEFT, _steering_value - 20)
            elif ch == curses.KEY_RIGHT:
                _steering_value = min(STEERING_MAX_RIGHT, _steering_value + 20)

            _set_pwm(PWM_CHANNEL_ESC, _esc_value)
            _set_pwm(PWM_CHANNEL_STEERING, _steering_value)

    finally:
        _cleanup()


def _no_terminal():
    """Print a message when run in a headless / no-terminal environment."""
    print("No terminal available; nothing to do. Exiting cleanly.", file=sys.stderr)
    sys.exit(0)


def _signal_handler(signum, frame):
    _cleanup(signum, frame)


if __name__ == "__main__":
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    try:
        curses.wrapper(main)
    except Exception as exc:
        print(f"Fatal error: {exc}", file=sys.stderr)
        _cleanup()
        sys.exit(1)
    except KeyboardInterrupt:
        _cleanup()
        sys.exit(0)
    except Exception as exc:
        print(f"Unexpected error: {exc}", file=sys.stderr)
        _cleanup()
        sys.exit(0)

