import signal
import sys
import logging
from flask import Flask, request, jsonify
from gpiozero import OutputDevice
from gpiozero.exc import GPIOZeroError

app = Flask(__name__)
logging.basicConfig(level=logging.INFO)
logger = logging.getLogger(__name__)

RELAY_PIN = 23
relay = None

def init_relay():
    global relay
    try:
        relay = OutputDevice(RELAY_PIN, active_high=True, initial_value=False)
        logger.info("Relay initialized on GPIO%d", RELAY_PIN)
    except GPIOZeroError as e:
        logger.error("Failed to initialize relay on GPIO%d: %s", RELAY_PIN, e)
        sys.exit(1)

def cleanup(signum=None, frame=None):
    global relay
    if relay is not None:
        try:
            relay.close()
            logger.info("Relay GPIO%d released", RELAY_PIN)
        except Exception as e:
            logger.error("Error releasing relay: %s", e)
        relay = None
    if signum is not None:
        sys.exit(0)

@app.route('/relay', methods=['POST'])
def relay_control():
    try:
        data = request.get_json(silent=True)
        if not isinstance(data, dict):
            return jsonify({'error': 'Invalid request'}), 400
        if 'state' not in data:
            return jsonify({'error': 'Invalid request'}), 400
        state = str(data['state']).lower()
        if state not in ('on', 'off'):
            return jsonify({'error': 'Invalid request'}), 400
        if relay is None:
            return jsonify({'error': 'Relay not initialized'}), 500
        relay.on() if state == 'on' else relay.off()
        return jsonify({'status': 'Relay state changed'})
    except Exception as e:
        logger.error("Error handling request: %s", e)
        return jsonify({'error': 'Internal server error'}), 500

if __name__ == '__main__':
    init_relay()
    signal.signal(signal.SIGINT, cleanup)
    signal.signal(signal.SIGTERM, cleanup)
    try:
        app.run(host='0.0.0.0', port=5000)
    finally:
        cleanup()

