import re
import logging
from gpiozero import OutputDevice
from gpiozero.exc import GPIOZeroError

logging.basicConfig(level=logging.INFO, format="%(asctime)s %(levelname)s %(message)s")

PUMP_PIN = 20
LIGHT_PIN = 21
ACTUATORS = {}

def match_intent(text):
    """Return the control intent for a plain English hydroponics phrase."""
    phrases = {
        r"turn the pump (on|off)": "pump_on" if "on" in text else "pump_off",
        r"switch the (light|grow light)": "light_toggle",
    }
    for pattern, intent in phrases.items():
        if re.search(pattern, text, re.IGNORECASE):
            return intent
    return None

def apply_intent(intent):
    """Drive gpiozero actuators according to a parsed intent."""
    if intent == "pump_on":
        ACTUATORS["pump"].on()
        logging.info("Nutrient pump turned ON")
    elif intent == "pump_off":
        ACTUATORS["pump"].off()
        logging.info("Nutrient pump turned OFF")
    elif intent == "light_toggle":
        if ACTUATORS["light"].is_active:
            ACTUATORS["light"].off()
        else:
            ACTUATORS["light"].on()
        logging.info("Grow light toggled")
    else:
        logging.warning("Unknown intent: %s", intent)

def cleanup():
    """Turn off and close all actuators."""
    for name, act in ACTUATORS.items():
        try:
            act.off()
            act.close()
        except Exception as exc:
            logging.error("Error closing %s: %s", name, exc)

if __name__ == "__main__":
    try:
        ACTUATORS["pump"] = OutputDevice(PUMP_PIN)
        ACTUATORS["light"] = OutputDevice(LIGHT_PIN)
    except GPIOZeroError as exc:
        logging.error("Failed to initialize GPIO: %s", exc)
        cleanup()
        raise SystemExit(1)

    test_phrases = [
        "turn the pump on",
        "switch the light",
        "turn pump off",
        "unknown command",
    ]
    for phrase in test_phrases:
        intent = match_intent(phrase)
        if intent:
            apply_intent(intent)
        else:
            logging.warning("No intent matched for: %s", phrase)

    cleanup()

