import paho.mqtt.client as mqtt
import time
import logging
import sys

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

BROKER_ADDRESS = "localhost"
BROKER_PORT = 1883
SUBSCRIBE_TOPIC = "city/reports"
KEEPALIVE = 60

noise_keywords = {"car", "horn", "siren"}
traffic_keywords = {"car", "truck", "bus", "accident"}

def classify_report(report_text):
    """Return the best keyword category for a short urban report."""
    tokens = set(report_text.lower().split())
    if tokens & noise_keywords:
        return "noise"
    if tokens & traffic_keywords:
        return "traffic"
    return "other"

def on_connect(client, userdata, flags, reason_code, properties):
    """Callback for when the client connects to the broker."""
    if reason_code == 0:
        logging.info("Connected to MQTT broker successfully")
        client.subscribe(SUBSCRIBE_TOPIC)
    else:
        logging.error(f"Failed to connect to MQTT broker, reason code: {reason_code}")

def on_disconnect(client, userdata, flags, reason_code, properties):
    """Callback for when the client disconnects from the broker."""
    logging.info(f"Disconnected from MQTT broker, reason code: {reason_code}")

def on_message(client, userdata, message):
    """Callback for when a message is received from the broker."""
    try:
        report_text = message.payload.decode("utf-8")
        category = classify_report(report_text)
        logging.info("Report: %s -> %s", report_text, category)
        userdata["counts"][category] = userdata["counts"].get(category, 0) + 1
    except Exception as e:
        logging.error("Error processing message: %s", e)

def main():
    """Set up the MQTT client and run the urban monitoring loop."""
    node_counts = {"noise": 0, "traffic": 0, "other": 0}
    client = mqtt.Client(
        callback_api_version=mqtt.CallbackAPIVersion.VERSION2,
        userdata=node_counts
    )
    client.on_connect = on_connect
    client.on_disconnect = on_disconnect
    client.on_message = on_message

    try:
        client.connect(BROKER_ADDRESS, BROKER_PORT, KEEPALIVE)
    except Exception as e:
        logging.error("Failed to connect to MQTT broker: %s", e)
        sys.exit(1)

    client.loop_start()
    time.sleep(5)
    client.loop_stop()
    client.disconnect()
    logging.info("Urban monitoring node stopped")

if __name__ == "__main__":
    main()

