        try:
            self._bus.read_byte_data(self.address, REG_SECONDS)
        except OSError as exc:
            self.close()
            raise RuntimeError(
                f"No DS1338 found at address 0x{self.address:02X} on bus {i2c_bus}: {exc}"
            ) from exc

