import serial
import time
import signal
import sys

class ESP8266:
    def __init__(self, port='/dev/serial0', baud_rate=115200, timeout=1.0):
        self.port = port
        self.baud_rate = baud_rate
        self.timeout = timeout
        self.ser = None
        try:
            self.ser = serial.Serial(port, baud_rate, timeout=timeout)
            print(f"Serial port {port} opened at {baud_rate} baud.")
        except serial.SerialException as e:
            print(f"Error opening serial port {port}: {e}")
            raise

    def _send_command(self, command, timeout=1.0, wait_for=b'OK'):
        if not self.ser or not self.ser.is_open:
            print("Serial port is not open.")
            return None
        try:
            self.ser.reset_input_buffer()
            self.ser.write((command + '\r\n').encode('utf-8'))
            response = b''
            start_time = time.time()
            while time.time() - start_time < timeout:
                if self.ser.in_waiting > 0:
                    chunk = self.ser.read(self.ser.in_waiting)
                    if chunk:
                        response += chunk
                        if wait_for in response:
                            break
                else:
                    time.sleep(0.01)
            return response
        except serial.SerialException as e:
            print(f"Serial communication error: {e}")
            return None

    def test_connection(self):
        response = self._send_command('AT', timeout=1.0, wait_for=b'OK')
        return response is not None and b'OK' in response

    def restart(self):
        response = self._send_command('AT+RST', timeout=5.0, wait_for=b'OK')
        if response is not None and b'OK' in response:
            print("ESP8266 restarted.")
            time.sleep(2)
            return self.test_connection()
        return False

    def connect_wifi(self, ssid, password):
        command = f'AT+CWJAP="{ssid}","{password}"'
        response = self._send_command(command, timeout=10.0, wait_for=b'OK')
        if response is not None and b'OK' in response:
            print("Connected to WiFi.")
            return True
        return False

    def disconnect_wifi(self):
        response = self._send_command('AT+CWQAP', timeout=1.0, wait_for=b'OK')
        if response is not None and b'OK' in response:
            print("Disconnected from WiFi.")
            return True
        return False

    def get_ip(self):
        response = self._send_command('AT+CIFSR', timeout=2.0, wait_for=b'OK')
        if response is not None and b'OK' in response:
            try:
                ip_start = response.index(b'STAIP:')
                ip_end = response.index(b'",')
                ip = response[ip_start+5:ip_end]
                ip = ip.decode('utf-8', errors='ignore').strip()
                return ip
            except ValueError:
                return None
        return None

    def send_http_request(self, method, url, host, port=80, headers=None, data=None):
        if headers is None:
            headers = {}
        request = f"{method} {url} HTTP/1.1\r\n"
        request += f"Host: {host}\r\n"
        for key, value in headers.items():
            request += f"{key}: {value}\r\n"
        request += "Connection: close\r\n"
        request += "\r\n"
        if data:
            request += data
        start_response = self._send_command(f'AT+CIPSTART="TCP","{host}",{port}', timeout=10.0, wait_for=b'OK')
        if start_response is None or b'OK' not in start_response:
            return None
        send_command = f'AT+CIPSEND={len(request)}'
        send_response = self._send_command(send_command, timeout=5.0, wait_for=b'>')
        if send_response is None or b'>' not in send_response:
            return None
        response = self._send_command(request, timeout=10.0, wait_for=b'TEXT')
        if response is None or b'TEXT' not in response:
            return None
        return response

    def receive_http_response(self, timeout=5.0):
        response = b''
        start_time = time.time()
        while time.time() - start_time < timeout:
            if self.ser.in_waiting > 0:
                chunk = self.ser.read(self.ser.in_waiting)
                if chunk:
                    response += chunk
                    if b'CLOSED' in response:
                        break
            else:
                time.sleep(0.01)
        if b'CLOSED' in response:
            print("Connection closed by server.")
        return response

    def close(self):
        if self.ser and self.ser.is_open:
            self.ser.close()
            print("Serial port closed.")

def signal_handler(sig, frame):
    print("\nExiting...")
    if esp:
        esp.close()
    sys.exit(0)

if __name__ == '__main__':
    esp = None
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)
    try:
        esp = ESP8266(port='/dev/serial0', baud_rate=115200, timeout=1.0)
        if esp.test_connection():
            print("ESP8266 is responding.")
            if esp.connect_wifi('SSID', 'PASSWORD'):
                ip = esp.get_ip()
                print(f"IP: {ip}")
                response = esp.send_http_request('GET', 'http://example.com', 'example.com')
                if response:
                    print(f"HTTP Response: {response}")
                else:
                    print("Failed to send HTTP request.")
            else:
                print("Failed to connect to WiFi.")
        else:
            print("ESP8266 is not responding.")
    except Exception as e:
        print(f"An error occurred: {e}")
    finally:
        if esp:
            esp.close()

