import time
import signal
import sys
from gpiozero import OutputDevice

SERIAL_PORT = '/dev/ttyUSB0'
BAUD_RATE = 9600
ALARM_PIN = 18
RADIATION_THRESHOLD = 50.0
READ_TIMEOUT = 1.0
LOOP_DELAY = 1.0

_running = True

def _signal_handler(signum, frame):
    global _running
    _running = False

def main():
    global _running

    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    try:
        alarm = OutputDevice(ALARM_PIN, active_high=True, initial_value=False)
    except Exception as e:
        print(f"Failed to initialize GPIO {ALARM_PIN}: {e}", file=sys.stderr)
        sys.exit(1)

    try:
        ser = serial.Serial(
            port=SERIAL_PORT,
            baudrate=BAUD_RATE,
            bytesize=serial.EIGHTBITS,
            parity=serial.PARITY_NONE,
            stopbits=serial.STOPBITS_ONE,
            timeout=READ_TIMEOUT,
        )
    except serial.SerialException as e:
        print(f"Error opening serial port {SERIAL_PORT}: {e}", file=sys.stderr)
        alarm.close()
        sys.exit(1)

    try:
        while _running:
            try:
                raw = ser.readline()
            except serial.SerialException as e:
                print(f"Serial read error: {e}", file=sys.stderr)
                break

            if not raw:
                continue

            line = raw.decode('ascii', errors='replace').strip()
            if not line:
                continue

            try:
                radiation_level = float(line)
            except ValueError:
                print(f"Invalid data received (not a float): {line!r}", file=sys.stderr)
                continue

            if radiation_level > RADIATION_THRESHOLD:
                alarm.on()
            else:
                alarm.off()

            time.sleep(LOOP_DELAY)

    except KeyboardInterrupt:
        pass
    finally:
        try:
            alarm.off()
            alarm.close()
        except Exception:
            pass
        try:
            ser.close()
        except Exception:
            pass

if __name__ == '__main__':
    main()

