import serial
import time
import signal
import sys
from gpiozero import OutputDevice

SERIAL_PORT = '/dev/ttyUSB0'
BAUD_RATE = 9600
READ_TIMEOUT = 1.0
FLOW_THRESHOLD = 10.0
POLL_INTERVAL = 1.0
ALARM_PIN = 17

running = True
serial_port = None
alarm = None

def signal_handler(signum, frame):
    global running
    running = False

def cleanup():
    global serial_port, alarm
    if serial_port is not None and serial_port.is_open:
        try:
            serial_port.close()
            print("Serial port closed.")
        except Exception as e:
            print(f"Error closing serial port: {e}")
    if alarm is not None:
        try:
            alarm.close()
            print("GPIO alarm pin released.")
        except Exception as e:
            print(f"Error releasing GPIO: {e}")

def main():
    global serial_port, alarm
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        serial_port = serial.Serial(
            SERIAL_PORT,
            BAUD_RATE,
            bytesize=serial.EIGHTBITS,
            parity=serial.PARITY_NONE,
            stopbits=serial.STOPBITS_ONE,
            timeout=READ_TIMEOUT
        )
        print(f"Opened {SERIAL_PORT} @ {BAUD_RATE} baud.")
    except serial.SerialException as e:
        print(f"Failed to open serial port {SERIAL_PORT}: {e}")
        sys.exit(1)
    except Exception as e:
        print(f"Unexpected error opening serial port: {e}")
        sys.exit(1)

    try:
        alarm = OutputDevice(ALARM_PIN, active_high=True, initial_value=False)
        print(f"GPIO pin {ALARM_PIN} configured as alarm output.")
    except Exception as e:
        print(f"Failed to initialize GPIO pin {ALARM_PIN}: {e}")
        cleanup()
        sys.exit(1)

    try:
        while running:
            try:
                raw = serial_port.readline()
                if not raw:
                    continue

                line = raw.decode('ascii', errors='replace').strip()
                if not line:
                    continue

                try:
                    flow_rate = float(line)
                except ValueError:
                    print(f"Invalid data received (not numeric): '{line}'")
                    continue

                print(f"Flow Rate: {flow_rate:.2f} L/min")

                if flow_rate > FLOW_THRESHOLD:
                    alarm.on()
                else:
                    alarm.off()

            except serial.SerialException as e:
                print(f"Serial read error: {e}")
                break
            except OSError as e:
                print(f"I/O error during serial read: {e}")
                break

            time.sleep(POLL_INTERVAL)

    finally:
        cleanup()

if __name__ == "__main__":
    main()

