import serial
import serial.tools.list_ports
import time
import signal
import sys
from datetime import datetime

SERIAL_PORT = '/dev/ttyUSB0'
BAUD_RATE = 9600
TIMEOUT = 1
LOG_FILE = 'co2_readings_log.txt'
SAMPLE_INTERVAL = 5

_running = True

def _signal_handler(signum, frame):
    global _running
    _running = False

def initialize_serial(port, baudrate, timeout):
    try:
        ser = serial.Serial(port, baudrate, timeout=timeout)
        print(f"Opened {port} @ {baudrate} baud")
        return ser
    except serial.SerialException as e:
        print(f"Error opening serial port {port}: {e}", file=sys.stderr)
        return None
    except Exception as e:
        print(f"Unexpected error opening serial port: {e}", file=sys.stderr)
        return None

def read_co2_level(ser):
    try:
        raw = ser.readline()
        if not raw:
            return None
        line = raw.decode('ascii', errors='replace').strip()
        if not line:
            return None
        return int(line)
    except ValueError:
        print(f"Invalid data received (not an integer): {line!r}", file=sys.stderr)
        return None
    except serial.SerialException as e:
        print(f"Serial read error: {e}", file=sys.stderr)
        return None
    except Exception as e:
        print(f"Unexpected read error: {e}", file=sys.stderr)
        return None

def log_co2_reading(log_file, co2_level):
    timestamp = datetime.now().isoformat(timespec='seconds')
    log_entry = f"{timestamp} - CO2: {co2_level} ppm\n"
    try:
        with open(log_file, 'a', encoding='utf-8') as f:
            f.write(log_entry)
            f.flush()
    except OSError as e:
        print(f"Error writing to log file: {e}", file=sys.stderr)

def display_co2_level(co2_level):
    print(f"CO2 Level: {co2_level} ppm")

def main():
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    ser = initialize_serial(SERIAL_PORT, BAUD_RATE, TIMEOUT)
    if ser is None:
        sys.exit(1)

    try:
        while _running:
            co2 = read_co2_level(ser)
            if co2 is not None:
                log_co2_reading(LOG_FILE, co2)
                display_co2_level(co2)
            time.sleep(SAMPLE_INTERVAL)
    except Exception as e:
        print(f"Fatal error in main loop: {e}", file=sys.stderr)
    finally:
        if ser and ser.is_open:
            ser.close()
            print("Serial port closed.")
        print("Program terminated.")

if __name__ == "__main__":
    main()

