import serial
import time
import signal
import sys

SERIAL_PORT = '/dev/serial0'
BAUD_RATE = 9600
TIMEOUT = 1

running = True

def signal_handler(sig, frame):
    global running
    running = False

def nmea_to_decimal(raw_value, direction):
    """Convert NMEA ddmm.mmmm format to decimal degrees."""
    if not raw_value or not direction:
        return None
    try:
        dot = raw_value.index('.')
        deg_len = dot - 2
        degrees = float(raw_value[:deg_len])
        minutes = float(raw_value[deg_len:])
        decimal = degrees + minutes / 60.0
        if direction in ('S', 'W'):
            decimal = -decimal
        return round(decimal, 6)
    except (ValueError, IndexError):
        return None

def parse_gprmc(data):
    """Parse $GPRMC sentence and return (lat, lon) in decimal degrees."""
    if not data.startswith('$GPRMC'):
        return None, None
    parts = data.split(',')
    if len(parts) < 8:
        return None, None
    status = parts[2]
    if status != 'A':
        return None, None
    lat = nmea_to_decimal(parts[3], parts[4])
    lon = nmea_to_decimal(parts[5], parts[6])
    return lat, lon

def main():
    global running
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    ser = None
    try:
        ser = serial.Serial(SERIAL_PORT, BAUD_RATE, timeout=TIMEOUT)
        print(f"Opened {SERIAL_PORT} at {BAUD_RATE} baud.")
        while running:
            try:
                raw = ser.readline()
                if not raw:
                    continue
                line = raw.decode('ascii', errors='replace').strip()
                if not line:
                    continue
                lat, lon = parse_gprmc(line)
                if lat is not None and lon is not None:
                    print(f"Latitude: {lat}, Longitude: {lon}")
                    time.sleep(1)
            except serial.SerialException as e:
                print(f"Serial read error: {e}")
                time.sleep(1)
            except Exception as e:
                print(f"Unexpected error: {e}")
                time.sleep(1)
    except serial.SerialException as e:
        print(f"Failed to open {SERIAL_PORT}: {e}")
    except Exception as e:
        print(f"Fatal error: {e}")
    finally:
        if ser is not None and ser.is_open:
            ser.close()
            print("Serial port closed.")
        print("Exiting.")

if __name__ == '__main__':
    main()

