import serial
import pynmea2
import time
import signal
import sys

SERIAL_PORT = '/dev/ttyUSB0'
BAUD_RATE = 9600
TIMEOUT = 1
LOG_FILE = 'gps_coordinates_log.txt'

running = True

def signal_handler(sig, frame):
    global running
    running = False

def log_coordinates(lat, lon, alt):
    timestamp = time.strftime('%Y-%m-%dT%H:%M:%S')
    log_entry = f'{timestamp} - Latitude: {lat}, Longitude: {lon}, Altitude: {alt} m\n'
    try:
        with open(LOG_FILE, 'a') as f:
            f.write(log_entry)
    except IOError as e:
        print(f'Error writing to log file: {e}', file=sys.stderr)

def main():
    global running
    signal.signal(signal.SIGINT, signal_handler)

    try:
        ser = serial.Serial(SERIAL_PORT, BAUD_RATE, timeout=TIMEOUT)
    except serial.SerialException as e:
        print(f'Error opening serial port: {e}', file=sys.stderr)
        sys.exit(1)

    try:
        while running:
            try:
                line = ser.readline().decode('ascii', errors='replace').strip()
                if not line:
                    continue

                if line.startswith('$GPGGA'):
                    try:
                        msg = pynmea2.parse(line)
                        if msg.gps_qual == 1:
                            lat = msg.latitude
                            lon = msg.longitude
                            alt = msg.altitude if msg.altitude is not None else 0.0
                            log_coordinates(lat, lon, alt)
                            print(f'Current Coordinates: Latitude={lat}, Longitude={lon}, Altitude={alt} m')
                        else:
                            print('GPS fix not valid (quality < 1).')
                    except pynmea2.ParseError as e:
                        print(f'NMEA parse error: {e}', file=sys.stderr)
            except serial.SerialException as e:
                print(f'Serial communication error: {e}', file=sys.stderr)
                break
            except UnicodeDecodeError as e:
                print(f'Decoding error: {e}', file=sys.stderr)

            time.sleep(0.1)
    finally:
        if ser.is_open:
            ser.close()
        print('Serial port closed. Exiting.')

if __name__ == '__main__':
    main()

