import serial
import time
import threading
import signal
import sys
from datetime import datetime

SERIAL_PORT = '/dev/ttyUSB0'
BAUD_RATE = 9600
TIMEOUT = 1
LOG_FILE = 'water_flow_log.txt'

stop_event = threading.Event()


def signal_handler(signum, frame):
    print(f"\nReceived signal {signum}, stopping flow monitor...")
    stop_event.set()


def log_flow_rate(flow_rate):
    timestamp = datetime.now().isoformat(timespec='seconds')
    log_entry = f"{timestamp} - Flow Rate: {flow_rate} L/min\n"
    try:
        with open(LOG_FILE, 'a', encoding='utf-8') as logfile:
            logfile.write(log_entry)
    except OSError as e:
        print(f"Error writing to log file: {e}")


def read_flow_data():
    ser = None
    try:
        ser = serial.Serial(SERIAL_PORT, BAUD_RATE, timeout=TIMEOUT)
        print(f"Connected to {SERIAL_PORT} at {BAUD_RATE} baud.")

        while not stop_event.is_set():
            try:
                raw = ser.readline()
                if not raw:
                    continue

                line = raw.decode('ascii', errors='replace').strip()
                if not line:
                    continue

                try:
                    flow_rate = float(line)
                    print(f"Flow Rate: {flow_rate} L/min")
                    log_flow_rate(flow_rate)
                except ValueError:
                    print(f"Invalid data received (not a float): '{line}'")

            except serial.SerialException as e:
                print(f"Serial I/O error: {e}")
                break

            time.sleep(1)

    except serial.SerialException as e:
        print(f"Failed to open serial port {SERIAL_PORT}: {e}")
    except Exception as e:
        print(f"Unexpected error: {e}")
    finally:
        if ser is not None and ser.is_open:
            ser.close()
            print("Serial port closed.")


if __name__ == "__main__":
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    reader_thread = threading.Thread(target=read_flow_data, daemon=True)
    reader_thread.start()

    try:
        while not stop_event.is_set():
            time.sleep(0.5)
    except KeyboardInterrupt:
        stop_event.set()

    reader_thread.join(timeout=5)
    print("Flow monitor stopped.")
    sys.exit(0)

