import serial
import signal
import sys
import logging
from dataclasses import dataclass
from typing import Optional

logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s - %(levelname)s - %(message)s",
)
logger = logging.getLogger(__name__)


@dataclass
class GPS_readings:
    latitude: Optional[float] = None
    latitude_dir: Optional[str] = None
    longitude: Optional[float] = None
    longitude_dir: Optional[str] = None
    num_satellites: Optional[int] = None
    altitude: Optional[float] = None

    def __str__(self):
        return (
            f"Lat: {self.latitude} ({self.latitude_dir}), "
            f"Lon: {self.longitude} ({self.longitude_dir}), "
            f"Sats: {self.num_satellites}, Alt: {self.altitude} m"
        )


class GPSReader:
    def __init__(self, port: str = "/dev/serial0", baudrate: int = 9600, timeout: float = 1.0):
        self.port = port
        self.baudrate = baudrate
        self.timeout = timeout
        self.serial_port: Optional[serial.Serial] = None
        self._running = True

    def connect(self) -> bool:
        try:
            self.serial_port = serial.Serial(
                port=self.port,
                baudrate=self.baudrate,
                bytesize=serial.EIGHTBITS,
                parity=serial.PARITY_NONE,
                stopbits=serial.STOPBITS_ONE,
                timeout=self.timeout,
            )
            logger.info("Connected to GPS on %s at %d baud", self.port, self.baudrate)
            return True
        except serial.SerialException as e:
            logger.error("Failed to open serial port %s: %s", self.port, e)
            self.serial_port = None
            return False

    def disconnect(self) -> None:
        if self.serial_port is not None:
            try:
                if self.serial_port.is_open:
                    self.serial_port.close()
                    logger.info("Serial port %s closed", self.port)
            except Exception as e:
                logger.error("Error closing serial port: %s", e)
            finally:
                self.serial_port = None

    def _nmea_to_decimal(self, value: str, direction: str) -> Optional[float]:
        if not value or not direction:
            return None
        try:
            dot = value.index(".")
            deg_len = dot - 2
            degrees = float(value[:deg_len])
            minutes = float(value[deg_len:])
            decimal = degrees + minutes / 60.0
            if direction in ("S", "W"):
                decimal = -decimal
            return decimal
        except (ValueError, IndexError):
            return None

    def _parse_gpgga(self, line: str) -> Optional[GPS_readings]:
        if not line.startswith("$GPGGA"):
            return None
        fields = line.split(",")
        if len(fields) < 15:
            logger.warning("GPGGA sentence too short: %s", line)
            return None
        try:
            talker = fields[0]
            fix_quality = fields[6]
            if not talker.startswith("$GPGGA") or fix_quality == "0":
                logger.warning("No GPS fix or invalid talker: %s", line)
                return None
            lat_raw = fields[2]
            lat_dir = fields[3]
            lon_raw = fields[4]
            lon_dir = fields[5]
            num_satellites = fields[7]
            altitude = fields[9]
            if not lat_raw or not lon_raw or not altitude:
                logger.warning("Missing GPS field: %s", line)
                return None
            lat = self._nmea_to_decimal(lat_raw, lat_dir)
            lon = self._nmea_to_decimal(lon_raw, lon_dir)
            try:
                alt = float(altitude) if altitude else None
            except ValueError:
                alt = None
            try:
                num_sat = int(num_satellites) if num_satellites else None
            except ValueError:
                num_sat = None
            return GPS_readings(
                latitude=lat,
                latitude_dir=lat_dir,
                longitude=lon,
                longitude_dir=lon_dir,
                num_satellites=num_sat,
                altitude=alt,
            )
        except (ValueError, IndexError) as e:
            logger.warning("Error parsing GPGGA: %s - line: %s", e, line)
            return None

    def read_data(self) -> Optional[GPS_readings]:
        if self.serial_port is None or not self.serial_port.is_open:
            return None
        try:
            raw = self.serial_port.readline()
        except serial.SerialException as e:
            logger.error("Serial read error: %s", e)
            return None
        if not raw:
            logger.warning("Serial read timeout")
            return None
        try:
            line = raw.decode("utf-8", errors="ignore").strip()
        except Exception as e:
            logger.warning("Decode error: %s", e)
            return None
        if not line:
            return None
        return self._parse_gpgga(line)

    def stop(self) -> None:
        self._running = False


def main() -> None:
    reader = GPSReader()

    def signal_handler(signum, frame):
        logger.info("Signal %d received, shutting down...", signum)
        reader.stop()

    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    if not reader.connect():
        sys.exit(1)

    try:
        while reader._running:
            readings = reader.read_data()
            if readings is not None:
                logger.info("GPS: %s", readings)
    except Exception as e:
        logger.error("Unexpected error in main loop: %s", e)
    finally:
        reader.disconnect()


if __name__ == "__main__":
    main()

