                        baudrate=self._baudrate,
                        bytesize=serial.EIGHTBITS,
                        parity=serial.PARITY_NONE,
                        stopbits=serial.STOPBITS_ONE,
                        timeout=self._timeout,
                    )
                except serial.SerialException as exc:
                    self._serial = None
                    raise RuntimeError(f"Failed to open serial port {self._port}: {exc}") from exc

    def close(self):
        with self._lock:
            if self._serial is not None:
                try:
                    self._serial.close()
                except Exception:
                    pass
                self._serial = None

    def send(self, command):
        if self._serial is None:
            raise RuntimeError("Serial port is not open")
        payload = (command + "\n").encode("ascii")
        bytes_written = self._serial.write(payload)
        self._serial.flush()
        if bytes_written != len(payload):
            raise RuntimeError(f"Short write: {bytes_written}/{len(payload)} bytes sent")

    def receive_line(self):
        if self._serial is None:
            raise RuntimeError("Serial port is not open")
        try:
            raw = self._serial.readline()
        except serial.SerialException as exc:
            raise RuntimeError(f"Serial read error: {exc}") from exc
        if not raw:
            return None
        return raw.decode("ascii", errors="replace").strip()

    @property
    def is_open(self):
        with self._lock:
            return self._serial is not None


serial_communicator = SerialCommunicator("/dev/ttyUSB0", baudrate=9600)


# ---------------------------------------------------------------------------
# Flask routes
# ---------------------------------------------------------------------------
@app.route("/version", methods=["GET"])
def get_device_version():
    try:
        serial_communicator.open()
    except RuntimeError as exc:
        return Response(f"Error opening serial port: {exc}\n", status=500, mimetype="text/plain")

    try:
        serial_communicator.send("*IDN?\n")
        response = serial_communicator.receive_line()
    finally:
        serial_communicator.close()

    if response is None:
        return Response("No response from device (timeout)\n", status=504, mimetype="text/plain")
    return Response(response + "\n", mimetype="text/plain")


@app.route("/data", methods=["GET"])
def get_all_data():
    items = data_manager.get_all()
    return jsonify(items)


@app.route("/data/<int:item_id>", methods=["GET"])
def get_data_by_id(item_id):
    item = data_manager.get_by_id(item_id)
    if item is None:
        return Response("Item not found\n", status=404, mimetype="text/plain")
    return jsonify(item)


@app.route("/data", methods=["POST"])
def create_data():
    try:
        name = request.get_json(force=True).get("name", "")
        done = request.get_json(force=True).get("done", False)
        data_manager.create(name, done)
    except ValueError as exc:
        return Response(f"Validation error: {exc}\n", status=400, mimetype="text/plain")
    except Exception as exc:
        return Response(f"Internal error: {exc}\n", status=500, mimetype="text/plain")
    item = data_manager.get_by_id(data_manager._data[-1]["id"])
    return jsonify(item), 201


# ---------------------------------------------------------------------------
# Graceful shutdown
# ---------------------------------------------------------------------------
_shutdown = threading.Event()


def _signal_handler(signum, frame):
    print(f"\nReceived signal {signum}, shutting down...")
    _shutdown.set()


signal.signal(signal.SIGINT, _signal_handler)
signal.signal(signal.SIGTERM, _signal_handler)


if __name__ == "__main__":
    try:
        app.run(host="0.0.0.0", port=5000, debug=False)
    finally:
        print("Flask server stopped.")

