import serial
import time
import sys

SERIAL_PORT = '/dev/ttyUSB0'
BAUD_RATE = 9600
TIMEOUT = 1
LOG_FILE = 'access_log.txt'


def log_access(tag_id: str) -> None:
    """Append a timestamped RFID access event to the log file."""
    timestamp = time.strftime('%Y-%m-%d %H:%M:%S')
    log_entry = f'{timestamp} - RFID Tag: {tag_id}\n'
    try:
        with open(LOG_FILE, 'a', encoding='utf-8') as logfile:
            logfile.write(log_entry)
            logfile.flush()
    except OSError as e:
        print(f'Error writing to log file: {e}', file=sys.stderr)
    print(f'Access granted for RFID Tag: {tag_id}')


def main() -> None:
    """Continuously read RFID tag IDs from the serial port and log them."""
    serial_connection = None
    try:
        serial_connection = serial.Serial(
            SERIAL_PORT,
            BAUD_RATE,
            timeout=TIMEOUT
        )
        print(f'Listening for RFID tags on {SERIAL_PORT}...')

        while True:
            try:
                raw_line = serial_connection.readline()
            except serial.SerialException as e:
                print(f'Serial read error: {e}', file=sys.stderr)
                break

            if not raw_line:
                # Timeout occurred with no data
                continue

            rfid_data = raw_line.decode('ascii', errors='replace').strip()
            if rfid_data:
                log_access(rfid_data)

    except serial.SerialException as e:
        print(f'Error opening serial port: {e}', file=sys.stderr)
    except KeyboardInterrupt:
        print('\nProgram terminated by user.')
    except Exception as e:
        print(f'An unexpected error occurred: {e}', file=sys.stderr)
    finally:
        if serial_connection is not None and serial_connection.is_open:
            serial_connection.close()
            print('Serial port closed.')


if __name__ == '__main__':
    main()

