from flask import Flask, Response, request, jsonify
import serial
import time
import signal
import sys

app = Flask(__name__)
app.secret_key = 'secret_key'
DATA = [
    {'id': 1, 'name': 'Chips', 'done': False},
    {'id': 2, 'name': 'Guacamole', 'done': False}
]
SERIAL_PORT = '/dev/ttyUSB0'
BAUD_RATE = 9600
SERIAL_TIMEOUT = 1.0

running = True
serial_conn = None


def signal_handler(signum, frame):
    global running
    running = False


signal.signal(signal.SIGINT, signal_handler)
signal.signal(signal.SIGTERM, signal_handler)


def get_serial_response():
    global serial_conn
    if serial_conn is None:
        return None
    try:
        serial_conn.reset_input_buffer()
        serial_conn.write(b'*IDN?\n')
        time.sleep(0.1)
        raw = serial_conn.read_all()
        if not raw:
            return None
        return raw.decode('utf-8', errors='replace')
    except serial.SerialException as e:
        return f"Serial error: {e}"
    except OSError as e:
        return f"OS error: {e}"
    except Exception as e:
        return f"Unexpected error: {e}"


@app.route('/version')
def version():
    global serial_conn
    try:
        serial_conn = serial.Serial(
            port=SERIAL_PORT,
            baudrate=BAUD_RATE,
            bytesize=serial.EIGHTBITS,
            parity=serial.PARITY_NONE,
            stopbits=serial.STOPBITS_ONE,
            timeout=SERIAL_TIMEOUT
        )
    except serial.SerialException as e:
        return Response(f"Error opening serial port: {e}<br>", status=503, mimetype='text/html')
    except Exception as e:
        return Response(f"Unexpected error opening serial port: {e}<br>", status=503, mimetype='text/html')

    try:
        response = get_serial_response()
        if isinstance(response, str) and '<br>' in response:
            response = response.replace('<br>', '\n')
        html = f"<h1>Instrument Response</h1><pre>{response}</pre>"
        return Response(html, mimetype='text/html')
    finally:
        if serial_conn and serial_conn.is_open:
            serial_conn.close()


@app.route('/getdata')
def get_data():
    return jsonify(DATA)


@app.route('/getset/<int:item_id>')
def get_set_item(item_id):
    item = next((it for it in DATA if it['id'] == item_id), None)
    if item is None:
        return jsonify({'error': 'Item not found'}), 404
    return jsonify(item)


@app.route('/getpost/<int:item_id>/<name>')
def get_post_item(item_id, name):
    new_name = name if name else ''
    new_done = False
    for item in DATA:
        if item['id'] == item_id:
            item['name'] = new_name
            item['done'] = new_done
            return jsonify(DATA)
    new_item = {'id': len(DATA) + 1, 'name': new_name, 'done': new_done}
    DATA.append(new_item)
    return jsonify(DATA)


@app.route('/postjson', methods=['GET', 'POST'])
def post_json():
    if request.method == 'POST':
        try:
            if request.is_json:
                data = request.get_json(silent=False)
            else:
                data = request.form
            item_id = len(DATA) + 1
            name = data.get('name', '') if isinstance(data.get('name'), str) else ''
            done_str = data.get('done', 'false')
            done = done_str.lower() in ('true', '1', 'yes')
            new_item = {'id': item_id, 'name': name, 'done': done}
            DATA.append(new_item)
            return jsonify(DATA)
        except (KeyError, TypeError, ValueError) as e:
            return jsonify({'error': f'Malformed input: {e}'}), 400
    else:
        return jsonify(DATA)


if __name__ == '__main__':
    try:
        app.run(host='0.0.0.0', debug=False)
    finally:
        if serial_conn and serial_conn.is_open:
            serial_conn.close()

