import serial
import time
import sys

BLUETOOTH_PORT = "/dev/rfcomm4"
BLUETOOTH_BAUDRATE = 38400


def send_command(ser, command):
    """Send a command to the Bluetooth device, prefixed with 'X' and terminated with newline."""
    try:
        command_with_prefix = f"X{command}\n"
        ser.write(command_with_prefix.encode("utf-8"))
        time.sleep(0.1)  # Small delay to avoid flooding the device
    except serial.SerialException as e:
        raise RuntimeError(f"Failed to send command '{command}': {e}") from e


def main():
    """Main function to establish Bluetooth connection and send user commands."""
    ser = None
    try:
        ser = serial.Serial(BLUETOOTH_PORT, BLUETOOTH_BAUDRATE, timeout=1)
        print(f"Connected to Bluetooth device on {BLUETOOTH_PORT} at {BLUETOOTH_BAUDRATE} baud.")

        while True:
            try:
                user_command = input("Enter command (or 'exit' to quit): ")
            except EOFError:
                print("\nEOF received, exiting.")
                break

            if user_command.lower() == "exit":
                print("Exiting...")
                break

            try:
                send_command(ser, user_command)
            except RuntimeError as e:
                print(f"Error: {e}")
                break

    except serial.SerialException as e:
        print(f"Error: Could not open serial port {BLUETOOTH_PORT}: {e}")
        sys.exit(1)
    except KeyboardInterrupt:
        print("\nInterrupted by user.")
    finally:
        if ser is not None and ser.is_open:
            ser.close()
            print("Serial connection closed.")


if __name__ == "__main__":
    main()

